window.WME01_TOPICS = [{"slug":"01_QuantitiesUnitsModelling","name":"Quantities, Units & Modelling","primaryCount":0,"count":42,"crossCount":42},{"slug":"02_WorkingWithVectors","name":"Working with Vectors","primaryCount":27,"count":42,"crossCount":15},{"slug":"03_KinematicsGraphs","name":"Kinematics Graphs","primaryCount":12,"count":17,"crossCount":5},{"slug":"04_ConstantAcceleration1D","name":"Constant Acceleration in 1D","primaryCount":16,"count":66,"crossCount":50},{"slug":"05_ConstantAcceleration2D","name":"Constant Acceleration in 2D","primaryCount":1,"count":22,"crossCount":21},{"slug":"06_Forces","name":"Forces","primaryCount":15,"count":29,"crossCount":14},{"slug":"07_NewtonsSecondLaw","name":"Newton's Second Law","primaryCount":12,"count":55,"crossCount":43},{"slug":"08_ResolvingForcesInclinedPlanes","name":"Resolving Forces, Inclined Planes","primaryCount":19,"count":29,"crossCount":10},{"slug":"09_MomentumImpulseCollisions","name":"Momentum, Impulse & Collisions","primaryCount":18,"count":22,"crossCount":4},{"slug":"10_Moments","name":"Moments","primaryCount":18,"count":18,"crossCount":0}];
window.WME01_QUESTIONS = [{"id":"WME01-01_2019_Oct_Q07","year":2019,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2019","qNo":7,"marks":7,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["06_Forces"],"secondaryTopicNames":["Forces"],"topics":["02_WorkingWithVectors","06_Forces"],"topicNames":["Working with Vectors","Forces"],"image":"ial/wme01/questions/WME01-01_Y2019_Oct_Q07_M07_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2019_Oct_Q07_M07_02_WorkingWithVectors.png","finalAnswer":"$(i)\\ |\\mathbf P|=\\sqrt{52}\\ \\mathrm{N}\\approx7.21\\ \\mathrm{N}.\\quad (ii)\\ \\text{bearing}=074^\\circ$.","steps":[{"title":"Resolve 2F","body":"Since $\\mathbf F$ has magnitude $4$ N on a bearing of $120^\\circ$, $2\\mathbf F$ has magnitude $8$ N on the same bearing."},{"title":"Write the components","body":"$2\\mathbf F=8\\sin120^\\circ\\mathbf i+8\\cos120^\\circ\\mathbf j=4\\sqrt3\\mathbf i-4\\mathbf j$. Also $\\mathbf G=6\\mathbf j$."},{"title":"Find P","body":"$\\mathbf P=2\\mathbf F+\\mathbf G=4\\sqrt3\\mathbf i+2\\mathbf j$."},{"title":"Find the magnitude","body":"$|\\mathbf P|=\\sqrt{(4\\sqrt3)^2+2^2}=\\sqrt{48+4}=\\sqrt{52}$ N."},{"title":"Find the bearing angle","body":"The vector is in the north-east quadrant. The angle east of north satisfies $\\tan\\theta=\\dfrac{4\\sqrt3}{2}=2\\sqrt3$."},{"title":"State the bearing","body":"$\\theta=73.9^\\circ$ approximately, so the bearing is $074^\\circ$ to the nearest degree."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2019_Oct_Q08","year":2019,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2019","qNo":8,"marks":14,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["03_KinematicsGraphs"],"secondaryTopicNames":["Kinematics Graphs"],"topics":["02_WorkingWithVectors","03_KinematicsGraphs"],"topicNames":["Working with Vectors","Kinematics Graphs"],"image":"ial/wme01/questions/WME01-01_Y2019_Oct_Q08_M14_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2019_Oct_Q08_M14_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ \\mathbf v_B=20\\mathbf i-20\\sqrt3\\mathbf j\\ \\mathrm{km\\,h^{-1}}.\\quad (b)\\ \\mathbf r=(60-20t)\\mathbf i,\\ \\mathbf s=20t\\mathbf i-20\\sqrt3t\\mathbf j.\\quad (c)\\ 13{:}43$, or $1{:}43\\ \\mathrm{pm}$.","steps":[{"title":"Resolve B's velocity","body":"A bearing of $150^\\circ$ is $30^\\circ$ east of south. Therefore the east component is $40\\sin150^\\circ=20$ and the north component is $40\\cos150^\\circ=-20\\sqrt3$."},{"title":"Write B's velocity","body":"$\\mathbf v_B=20\\mathbf i-20\\sqrt3\\mathbf j\\ \\mathrm{km\\,h^{-1}}$."},{"title":"Write A's position","body":"Boat A starts at $60\\mathbf i$ and travels due west at $20\\ \\mathrm{km\\,h^{-1}}$, so $\\mathbf r=60\\mathbf i-20t\\mathbf i=(60-20t)\\mathbf i$."},{"title":"Write B's position","body":"Boat B starts at O, so $\\mathbf s=t(20\\mathbf i-20\\sqrt3\\mathbf j)=20t\\mathbf i-20\\sqrt3t\\mathbf j$."},{"title":"Find the separation vector","body":"$\\overrightarrow{AB}=\\mathbf s-\\mathbf r=(20t-(60-20t))\\mathbf i-20\\sqrt3t\\mathbf j=(40t-60)\\mathbf i-20\\sqrt3t\\mathbf j$."},{"title":"Use the noon distance","body":"At noon the distance between the boats is $60$ km. Set the later distance equal to $60$: $(40t-60)^2+(-20\\sqrt3t)^2=60^2$."},{"title":"Solve for t","body":"Expanding gives $2800t^2-4800t=0$, so $t(2800t-4800)=0$. The later time is $t=\\dfrac{4800}{2800}=\\dfrac{12}{7}$ hours."},{"title":"Convert to clock time","body":"$\\dfrac{12}{7}$ hours is $1$ hour and $42.857\\ldots$ minutes after noon, which rounds to $1{:}43$ pm, or $13{:}43$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2020_Jan_Q06","year":2020,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2020","qNo":6,"marks":11,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":[],"secondaryTopicNames":[],"topics":["02_WorkingWithVectors"],"topicNames":["Working with Vectors"],"image":"ial/wme01/questions/WME01-01_Y2020_Jan_Q06_M11_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2020_Jan_Q06_M11_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ |\\mathbf F|=\\sqrt{101}\\ \\mathrm{N}.\\quad (b)\\ 39.3^\\circ\\text{ approximately}.\\quad (c)\\ a=6.5$.","steps":[{"title":"Find the magnitude","body":"For $\\mathbf F=10\\mathbf i+\\mathbf j$, $|\\mathbf F|=\\sqrt{10^2+1^2}=\\sqrt{101}$ N."},{"title":"Find the direction angle of F","body":"The angle that $\\mathbf F$ makes with the positive $\\mathbf i$ direction is $\\alpha$, where $\\tan\\alpha=\\dfrac{1}{10}$. Thus $\\alpha=5.71^\\circ$ approximately."},{"title":"Compare with i plus j","body":"The vector $\\mathbf i+\\mathbf j$ makes an angle of $45^\\circ$ with the positive $\\mathbf i$ direction."},{"title":"Find the angle between the vectors","body":"So the required angle is $45^\\circ-5.71^\\circ=39.29^\\circ$, approximately $39.3^\\circ$."},{"title":"Write the resultant","body":"The resultant of $10\\mathbf i+\\mathbf j$ and $-15\\mathbf i+a\\mathbf j$ is $-5\\mathbf i+(a+1)\\mathbf j$."},{"title":"Use the parallel opposite direction","body":"Parallel but opposite to $2\\mathbf i-3\\mathbf j$ means the resultant is a positive multiple of $-2\\mathbf i+3\\mathbf j$."},{"title":"Solve for a","body":"Let $-5\\mathbf i+(a+1)\\mathbf j=\\lambda(-2\\mathbf i+3\\mathbf j)$. From the $\\mathbf i$ component, $-5=-2\\lambda$, so $\\lambda=2.5$. Then $a+1=3(2.5)=7.5$, hence $a=6.5$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_Jan_Q05","year":2021,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2021","qNo":5,"marks":7,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["06_Forces"],"secondaryTopicNames":["Forces"],"topics":["02_WorkingWithVectors","06_Forces"],"topicNames":["Working with Vectors","Forces"],"image":"ial/wme01/questions/WME01-01_Y2021_Jan_Q05_M07_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2021_Jan_Q05_M07_02_WorkingWithVectors.png","finalAnswer":"$(i)\\ |\\mathbf{R}|=\\sqrt{244}\\ \\mathrm{N}\\approx15.6\\ \\mathrm{N}.\\quad (ii)\\ \\text{bearing}=206^\\circ$.","steps":[{"title":"Resolve F into components","body":"A bearing of $240^\\circ$ is $60^\\circ$ west of south. Hence $\\mathbf{F}=(-8\\sin60^\\circ)\\mathbf{i}+(-8\\cos60^\\circ)\\mathbf{j}=-4\\sqrt3\\mathbf{i}-4\\mathbf{j}$."},{"title":"Add G","body":"The force $\\mathbf{G}$ is due south with magnitude $10$, so $\\mathbf{G}=-10\\mathbf{j}$. Therefore $\\mathbf{R}=\\mathbf{F}+\\mathbf{G}=-4\\sqrt3\\mathbf{i}-14\\mathbf{j}$."},{"title":"Find the magnitude","body":"$|\\mathbf{R}|=\\sqrt{(-4\\sqrt3)^2+(-14)^2}=\\sqrt{48+196}=\\sqrt{244}\\ \\mathrm{N}$."},{"title":"Find the bearing angle","body":"The resultant points south-west. The angle west of south satisfies $\\tan\\theta=\\dfrac{4\\sqrt3}{14}=\\dfrac{2\\sqrt3}{7}$."},{"title":"State the bearing","body":"$\\theta=26.3^\\circ$. Bearing $=180^\\circ+26.3^\\circ=206.3^\\circ$, so the bearing is $206^\\circ$ to the nearest degree."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_Jan_Q06","year":2021,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2021","qNo":6,"marks":12,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["05_ConstantAcceleration2D"],"secondaryTopicNames":["Constant Acceleration in 2D"],"topics":["02_WorkingWithVectors","05_ConstantAcceleration2D"],"topicNames":["Working with Vectors","Constant Acceleration in 2D"],"image":"ial/wme01/questions/WME01-01_Y2021_Jan_Q06_M12_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2021_Jan_Q06_M12_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ \\mathbf{r}_A=(11+3t)\\mathbf{i}+(11-t)\\mathbf{j}.\\quad (b)\\ t=5.5\\ \\mathrm{s}.\\quad (c)\\ \\overrightarrow{AB}=(t-4)\\mathbf{i}+(5-t)\\mathbf{j}.\\quad (d)\\ \\text{minimum distance}=\\sqrt{0.5}\\ \\mathrm{m}\\approx0.71\\ \\mathrm{m}$.","steps":[{"title":"Write Agatha position","body":"$\\mathbf{r}_A=(11\\mathbf{i}+11\\mathbf{j})+t(3\\mathbf{i}-\\mathbf{j})=(11+3t)\\mathbf{i}+(11-t)\\mathbf{j}$."},{"title":"Find point P","body":"At $t=6$, Agatha is at $(11+18)\\mathbf{i}+(11-6)\\mathbf{j}=29\\mathbf{i}+5\\mathbf{j}$."},{"title":"Write Brionie position","body":"$\\mathbf{r}_B=(7\\mathbf{i}+16\\mathbf{j})+t(4\\mathbf{i}-2\\mathbf{j})=(7+4t)\\mathbf{i}+(16-2t)\\mathbf{j}$."},{"title":"Show Brionie passes P","body":"Set $7+4t=29$ to get $t=5.5$. Also $16-2t=5$ gives $t=5.5$. So Brionie also passes through P at $t=5.5$ s."},{"title":"Find AB vector","body":"$\\overrightarrow{AB}=\\mathbf{r}_B-\\mathbf{r}_A=[7+4t-(11+3t)]\\mathbf{i}+[16-2t-(11-t)]\\mathbf{j}$."},{"title":"Simplify AB","body":"So $\\overrightarrow{AB}=(t-4)\\mathbf{i}+(5-t)\\mathbf{j}$ m."},{"title":"Minimise distance squared","body":"$AB^2=(t-4)^2+(5-t)^2=2(t-4.5)^2+0.5$."},{"title":"State the minimum distance","body":"The minimum occurs when $t=4.5$, giving $AB^2=0.5$. Hence the minimum distance is $\\sqrt{0.5}=0.707\\ldots\\ \\mathrm{m}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_MayJune_Q03","year":2021,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2021","qNo":3,"marks":9,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["06_Forces","07_NewtonsSecondLaw"],"secondaryTopicNames":["Forces","Newton's Second Law"],"topics":["02_WorkingWithVectors","06_Forces","07_NewtonsSecondLaw"],"topicNames":["Working with Vectors","Forces","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2021_MayJune_Q03_M09_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2021_MayJune_Q03_M09_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ 34^\\circ\\ \\text{approximately}.\\quad (b)\\ \\lambda=3$.","steps":[{"title":"Find F3 from equilibrium","body":"Equilibrium gives $\\mathbf{F}_1+\\mathbf{F}_2+\\mathbf{F}_3=\\mathbf{0}$. Now $\\mathbf{F}_1+\\mathbf{F}_2=(5\\mathbf{i}+2\\mathbf{j})+(-3\\mathbf{i}+\\mathbf{j})=2\\mathbf{i}+3\\mathbf{j}$."},{"title":"Write F3","body":"So $\\mathbf{F}_3=-2\\mathbf{i}-3\\mathbf{j}$."},{"title":"Find the angle with -j","body":"The vector $-\\mathbf{j}$ points vertically downward. For $\\mathbf{F}_3=-2\\mathbf{i}-3\\mathbf{j}$, the angle from $-\\mathbf{j}$ satisfies $\\tan\\theta=\\dfrac{2}{3}$."},{"title":"State the angle","body":"$\\theta=33.7^\\circ$, so the angle is about $34^\\circ$."},{"title":"Find the new resultant force","body":"With $\\mathbf{F}_4=\\lambda(\\mathbf{i}+3\\mathbf{j})$, the resultant is $(2+\\lambda)\\mathbf{i}+(3+3\\lambda)\\mathbf{j}$."},{"title":"Use the acceleration magnitude","body":"The mass is $4$ kg and acceleration magnitude is $3.25$, so the resultant force magnitude is $4(3.25)=13$ N."},{"title":"Form the equation","body":"$(2+\\lambda)^2+(3+3\\lambda)^2=13^2$."},{"title":"Solve for lambda","body":"Expanding gives $10\\lambda^2+22\\lambda-156=0$. The roots are $3$ and $-5.2$, and since $\\lambda$ is positive, $\\lambda=3$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_MayJune_Q05","year":2021,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2021","qNo":5,"marks":9,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["05_ConstantAcceleration2D"],"secondaryTopicNames":["Constant Acceleration in 2D"],"topics":["02_WorkingWithVectors","05_ConstantAcceleration2D"],"topicNames":["Working with Vectors","Constant Acceleration in 2D"],"image":"ial/wme01/questions/WME01-01_Y2021_MayJune_Q05_M09_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2021_MayJune_Q05_M09_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ T=\\dfrac{11}{4}\\ \\mathrm{h}.\\quad (b)\\ \\mu=8.5$.","steps":[{"title":"Find P acceleration","body":"From 2:00 to 2:30 is $0.5$ hours. The velocity changes from $3\\mathbf{i}+5\\mathbf{j}$ to $\\mathbf{i}+7\\mathbf{j}$."},{"title":"Calculate acceleration","body":"$\\mathbf{a}=\\dfrac{(\\mathbf{i}+7\\mathbf{j})-(3\\mathbf{i}+5\\mathbf{j})}{0.5}=-4\\mathbf{i}+4\\mathbf{j}$."},{"title":"Write P velocity","body":"At time $t$ hours after 2:00, $\\mathbf{v}_P=(3-4t)\\mathbf{i}+(5+4t)\\mathbf{j}$."},{"title":"Use the direction vector","body":"At time $T$, the velocity is parallel to $-\\mathbf{i}+2\\mathbf{j}$, so $\\dfrac{5+4T}{3-4T}=\\dfrac{2}{-1}=-2$."},{"title":"Find T","body":"$5+4T=-2(3-4T)=-6+8T$. Hence $11=4T$ and $T=\\dfrac{11}{4}$ hours."},{"title":"Equate i-components for P and Q","body":"For equal velocities, $3-4t=-4-2t$. This gives $7=2t$, so $t=3.5$."},{"title":"Equate j-components","body":"At $t=3.5$, P's j-component is $5+4(3.5)=19$. Q's j-component is $\\mu+3(3.5)=\\mu+10.5$."},{"title":"Find mu","body":"$\\mu+10.5=19$, so $\\mu=8.5$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_Oct_Q04","year":2021,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2021","qNo":4,"marks":8,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["05_ConstantAcceleration2D","04_ConstantAcceleration1D"],"secondaryTopicNames":["Constant Acceleration in 2D","Constant Acceleration in 1D"],"topics":["02_WorkingWithVectors","05_ConstantAcceleration2D","04_ConstantAcceleration1D"],"topicNames":["Working with Vectors","Constant Acceleration in 2D","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2021_Oct_Q04_M08_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2021_Oct_Q04_M08_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ 162^\\circ.\\quad (b)\\ t=\\dfrac12\\ \\text{or}\\ t=\\dfrac32$.","steps":[{"title":"Find r when t = 2","body":"$\\mathbf{r}=(2-3)\\mathbf{i}+(1-2(2))\\mathbf{j}=-\\mathbf{i}-3\\mathbf{j}$."},{"title":"Find the angle with j","body":"The vector is in the third quadrant. The angle between $\\mathbf{r}$ and the positive $\\mathbf{j}$ direction satisfies $\\tan\\alpha=\\dfrac{1}{3}$ from the vertical comparison."},{"title":"State the angle","body":"$\\alpha=18.4^\\circ$ from the negative $\\mathbf{j}$ direction, so the size of the angle with positive $\\mathbf{j}$ is $180^\\circ-18.4^\\circ=161.6^\\circ$, which is $162^\\circ$."},{"title":"Use the distance condition","body":"Distance from O is $2.5$, so $(t-3)^2+(1-2t)^2=2.5^2$."},{"title":"Form the quadratic","body":"$t^2-6t+9+1-4t+4t^2=6.25$, so $5t^2-10t+3.75=0$."},{"title":"Solve","body":"Multiply by $4$: $20t^2-40t+15=0$, or $4t^2-8t+3=0$. Hence $(2t-1)(2t-3)=0$, so $t=\\dfrac12$ or $t=\\dfrac32$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_Oct_Q08","year":2021,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2021","qNo":8,"marks":12,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["05_ConstantAcceleration2D"],"secondaryTopicNames":["Constant Acceleration in 2D"],"topics":["02_WorkingWithVectors","05_ConstantAcceleration2D"],"topicNames":["Working with Vectors","Constant Acceleration in 2D"],"image":"ial/wme01/questions/WME01-01_Y2021_Oct_Q08_M12_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2021_Oct_Q08_M12_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ \\mathbf{v}=10\\mathbf{i}-5\\mathbf{j}\\ \\mathrm{km\\,h^{-1}}.\\quad (b)\\ \\mathbf{r}=(-2+10t)\\mathbf{i}+(9-5t)\\mathbf{j}.\\quad (c)\\ \\text{lighthouse}=19\\mathbf{i}.\\quad (d)\\ \\text{ship position}=19\\mathbf{i}-1.5\\mathbf{j}$.","steps":[{"title":"Convert the time","body":"From 7:00 to 7:36 is $36$ minutes, which is $0.6$ hours."},{"title":"Find velocity","body":"Displacement $=(4\\mathbf{i}+6\\mathbf{j})-(-2\\mathbf{i}+9\\mathbf{j})=6\\mathbf{i}-3\\mathbf{j}$. Divide by $0.6$: $\\mathbf{v}=10\\mathbf{i}-5\\mathbf{j}$."},{"title":"Write the ship position","body":"$\\mathbf{r}=(-2\\mathbf{i}+9\\mathbf{j})+t(10\\mathbf{i}-5\\mathbf{j})=(-2+10t)\\mathbf{i}+(9-5t)\\mathbf{j}$."},{"title":"Use 8:48","body":"At 8:48, $t=1.8$. The ship position is $(-2+18)\\mathbf{i}+(9-9)\\mathbf{j}=16\\mathbf{i}$. The lighthouse is due east, so it has the same j-component, $0$."},{"title":"Use 9:00","body":"At 9:00, $t=2$. The ship position is $18\\mathbf{i}-\\mathbf{j}$. The lighthouse is north-east of the ship, so its east and north displacements from the ship are equal."},{"title":"Find the lighthouse position","body":"Since the lighthouse has j-component $0$, from $18\\mathbf{i}-\\mathbf{j}$ it is $1$ km north, so it is also $1$ km east. Hence its position is $19\\mathbf{i}$."},{"title":"Find when the ship is due south","body":"Due south of the lighthouse means the ship has i-component $19$. Set $-2+10t=19$, so $t=2.1$."},{"title":"Find the ship position","body":"At $t=2.1$, $\\mathbf{r}=(-2+21)\\mathbf{i}+(9-10.5)\\mathbf{j}=19\\mathbf{i}-1.5\\mathbf{j}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_Jan_Q06","year":2022,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2022","qNo":6,"marks":12,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["07_NewtonsSecondLaw","05_ConstantAcceleration2D"],"secondaryTopicNames":["Newton's Second Law","Constant Acceleration in 2D"],"topics":["02_WorkingWithVectors","07_NewtonsSecondLaw","05_ConstantAcceleration2D"],"topicNames":["Working with Vectors","Newton's Second Law","Constant Acceleration in 2D"],"image":"ial/wme01/questions/WME01-01_Y2022_Jan_Q06_M12_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2022_Jan_Q06_M12_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ p=-6,\\ q=4.\\quad (b)\\ 135^\\circ.\\quad (c)\\ T=2.5$.","steps":[{"title":"Use F = ma","body":"The total force is $(p\\mathbf{i}+q\\mathbf{j})+(2q\\mathbf{i}+p\\mathbf{j})=(p+2q)\\mathbf{i}+(p+q)\\mathbf{j}$. Since the mass is $2$ kg and acceleration is $\\mathbf{i}-\\mathbf{j}$, the total force is $2\\mathbf{i}-2\\mathbf{j}$."},{"title":"Equate components","body":"$p+2q=2$ and $p+q=-2$."},{"title":"Find p and q","body":"Subtract the equations to get $q=4$. Then $p+4=-2$, so $p=-6$."},{"title":"Find the angle with j","body":"The acceleration is $\\mathbf{i}-\\mathbf{j}$. Its dot product with $\\mathbf{j}$ is $-1$, so the angle with the positive $\\mathbf{j}$ direction is obtuse. Since the components are equal in magnitude, the angle is $135^\\circ$."},{"title":"Write the velocity at time T","body":"$\\mathbf{v}=(3\\mathbf{i}-4\\mathbf{j})+T(\\mathbf{i}-\\mathbf{j})=(3+T)\\mathbf{i}+(-4-T)\\mathbf{j}$."},{"title":"Use the direction vector","body":"The velocity is parallel to $11\\mathbf{i}-13\\mathbf{j}$, so $\\dfrac{3+T}{11}=\\dfrac{-4-T}{-13}$."},{"title":"Solve for T","body":"$13(3+T)=11(4+T)$, so $39+13T=44+11T$. Hence $2T=5$ and $T=2.5$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_Jan_Q08","year":2022,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2022","qNo":8,"marks":14,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["05_ConstantAcceleration2D"],"secondaryTopicNames":["Constant Acceleration in 2D"],"topics":["02_WorkingWithVectors","05_ConstantAcceleration2D"],"topicNames":["Working with Vectors","Constant Acceleration in 2D"],"image":"ial/wme01/questions/WME01-01_Y2022_Jan_Q08_M14_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2022_Jan_Q08_M14_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ \\mathbf{r}=(13+3t)\\mathbf{i}+(5-10t)\\mathbf{j}.\\quad (b)\\ \\overrightarrow{AB}=(12t-10)\\mathbf{i}+(24t-10)\\mathbf{j}.\\quad (c)\\ 2\\sqrt5\\ \\mathrm{km}\\approx4.5\\ \\mathrm{km}.\\quad (d)\\ 297^\\circ$.","steps":[{"title":"Write the position of A","body":"$\\mathbf{r}=(13\\mathbf{i}+5\\mathbf{j})+t(3\\mathbf{i}-10\\mathbf{j})=(13+3t)\\mathbf{i}+(5-10t)\\mathbf{j}$."},{"title":"Write the position of B","body":"$\\mathbf{s}=(3\\mathbf{i}-5\\mathbf{j})+t(15\\mathbf{i}+14\\mathbf{j})=(3+15t)\\mathbf{i}+(-5+14t)\\mathbf{j}$."},{"title":"Find AB","body":"$\\overrightarrow{AB}=\\mathbf{s}-\\mathbf{r}=[3+15t-(13+3t)]\\mathbf{i}+[-5+14t-(5-10t)]\\mathbf{j}$."},{"title":"Show the expression","body":"This simplifies to $\\overrightarrow{AB}=(12t-10)\\mathbf{i}+(24t-10)\\mathbf{j}$ km."},{"title":"Use distance squared","body":"The square of the distance is $d^2=(12t-10)^2+(24t-10)^2$."},{"title":"Expand and minimise","body":"$d^2=720t^2-720t+200$. This quadratic is minimum at $t=\\dfrac{720}{2\\cdot720}=\\dfrac12$."},{"title":"Find the shortest distance","body":"At $t=\\dfrac12$, $\\overrightarrow{AB}=(-4)\\mathbf{i}+2\\mathbf{j}$, so the shortest distance is $\\sqrt{(-4)^2+2^2}=\\sqrt{20}=2\\sqrt5\\ \\mathrm{km}$."},{"title":"Find the bearing","body":"At closest approach, B is west and north of A. The angle west of north satisfies $\\tan\\theta=\\dfrac{4}{2}=2$, so $\\theta=63.4^\\circ$. Bearing $=360^\\circ-63.4^\\circ=296.6^\\circ$, which is $297^\\circ$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_MayJune_Q06","year":2022,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2022","qNo":6,"marks":6,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["05_ConstantAcceleration2D"],"secondaryTopicNames":["Constant Acceleration in 2D"],"topics":["02_WorkingWithVectors","05_ConstantAcceleration2D"],"topicNames":["Working with Vectors","Constant Acceleration in 2D"],"image":"ial/wme01/questions/WME01-01_Y2022_MayJune_Q06_M06_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2022_MayJune_Q06_M06_02_WorkingWithVectors.png","finalAnswer":"$\\text{speed}=\\sqrt{52}=2\\sqrt{13}\\ \\mathrm{m\\,s^{-1}}\\approx7.2\\ \\mathrm{m\\,s^{-1}}$.","steps":[{"title":"Find the acceleration","body":"The velocity changes from $-\\mathbf{i}+4\\mathbf{j}$ at $t=1$ to $5\\mathbf{i}-8\\mathbf{j}$ at $t=4$. The time difference is $3$ s."},{"title":"Calculate acceleration","body":"$\\mathbf{a}=\\dfrac{(5\\mathbf{i}-8\\mathbf{j})-(-\\mathbf{i}+4\\mathbf{j})}{3}=\\dfrac{6\\mathbf{i}-12\\mathbf{j}}{3}=2\\mathbf{i}-4\\mathbf{j}$."},{"title":"Find velocity at t = 3.5","body":"From $t=1$ to $t=3.5$ is $2.5$ s, so $\\mathbf{v}=(-\\mathbf{i}+4\\mathbf{j})+2.5(2\\mathbf{i}-4\\mathbf{j})$."},{"title":"Simplify the velocity","body":"$\\mathbf{v}=-\\mathbf{i}+4\\mathbf{j}+5\\mathbf{i}-10\\mathbf{j}=4\\mathbf{i}-6\\mathbf{j}$."},{"title":"Find the speed","body":"Speed $=\\sqrt{4^2+(-6)^2}=\\sqrt{52}=2\\sqrt{13}\\ \\mathrm{m\\,s^{-1}}$, about $7.2\\ \\mathrm{m\\,s^{-1}}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_MayJune_Q08","year":2022,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2022","qNo":8,"marks":17,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["05_ConstantAcceleration2D"],"secondaryTopicNames":["Constant Acceleration in 2D"],"topics":["02_WorkingWithVectors","05_ConstantAcceleration2D"],"topicNames":["Working with Vectors","Constant Acceleration in 2D"],"image":"ial/wme01/questions/WME01-01_Y2022_MayJune_Q08_M17_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2022_MayJune_Q08_M17_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ 135^\\circ.\\quad (b)\\ \\overrightarrow{PQ}=5t\\mathbf{i}+(200-20t)\\mathbf{j}.\\quad (c)\\ 270^\\circ.\\quad (d)\\ 40\\sqrt2\\ \\mathrm{m}.\\quad (e)\\ t=0\\ \\mathrm{s}\\ \\text{or}\\ \\dfrac{320}{17}\\ \\mathrm{s}$.","steps":[{"title":"Find the bearing of Q","body":"Q has velocity $20\\mathbf{i}-20\\mathbf{j}$, so it travels south-east with equal east and south components. Its bearing is $135^\\circ$."},{"title":"Write P position","body":"P starts at the origin and has velocity $15\\mathbf{i}$, so $\\mathbf{p}=15t\\mathbf{i}$."},{"title":"Write Q position","body":"Q starts at $200\\mathbf{j}$ and has velocity $20\\mathbf{i}-20\\mathbf{j}$, so $\\mathbf{q}=20t\\mathbf{i}+(200-20t)\\mathbf{j}$."},{"title":"Show PQ","body":"$\\overrightarrow{PQ}=\\mathbf{q}-\\mathbf{p}=(20t-15t)\\mathbf{i}+(200-20t)\\mathbf{j}=5t\\mathbf{i}+(200-20t)\\mathbf{j}$."},{"title":"Find the bearing at t = 10","body":"At $t=10$, $\\overrightarrow{PQ}=50\\mathbf{i}$. This means Q is east of P, so P is west of Q. The bearing of P from Q is $270^\\circ$."},{"title":"Use the north-east condition","body":"Q is north-east of P when the i and j components of $\\overrightarrow{PQ}$ are equal and positive. So $5t=200-20t$."},{"title":"Find the distance then","body":"The equation gives $t=8$. Then $\\overrightarrow{PQ}=40\\mathbf{i}+40\\mathbf{j}$, so the distance is $\\sqrt{40^2+40^2}=40\\sqrt2\\ \\mathrm{m}$."},{"title":"Set the 200 m distance equation","body":"For distance $200$ m, $(5t)^2+(200-20t)^2=200^2$."},{"title":"Solve for t","body":"This simplifies to $425t^2-8000t=0$, so $t(425t-8000)=0$. Hence $t=0$ or $t=\\dfrac{8000}{425}=\\dfrac{320}{17}$ s."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_Oct_Q06","year":2022,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2022","qNo":6,"marks":9,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["07_NewtonsSecondLaw"],"secondaryTopicNames":["Newton's Second Law"],"topics":["02_WorkingWithVectors","07_NewtonsSecondLaw"],"topicNames":["Working with Vectors","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2022_Oct_Q06_M09_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2022_Oct_Q06_M09_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ 2p+q-4=0.\\quad (b)\\ \\text{speed}=16\\sqrt5\\ \\mathrm{m\\,s^{-1}}\\approx36\\ \\mathrm{m\\,s^{-1}}$.","steps":[{"title":"Find the resultant force","body":"$\\mathbf{F}=(-3\\mathbf{i}+2\\mathbf{j})+(p\\mathbf{i}+q\\mathbf{j})=(p-3)\\mathbf{i}+(q+2)\\mathbf{j}$."},{"title":"Use the direction of motion","body":"Since the particle starts from rest, its motion is in the direction of the resultant force. This direction is $\\mathbf{i}-2\\mathbf{j}$, so $\\dfrac{q+2}{p-3}=-2$."},{"title":"Show the relation","body":"$q+2=-2(p-3)=-2p+6$, hence $2p+q-4=0$."},{"title":"Find q when p = 5","body":"Substitute $p=5$ into $2p+q-4=0$: $10+q-4=0$, so $q=-6$."},{"title":"Find the resultant force","body":"The resultant force is $(5-3)\\mathbf{i}+(-6+2)\\mathbf{j}=2\\mathbf{i}-4\\mathbf{j}$ N."},{"title":"Find acceleration","body":"The mass is $0.5$ kg, so $\\mathbf{a}=\\dfrac{2\\mathbf{i}-4\\mathbf{j}}{0.5}=4\\mathbf{i}-8\\mathbf{j}$."},{"title":"Find velocity at t = 4","body":"Starting from rest, $\\mathbf{v}=\\mathbf{a}t=(4\\mathbf{i}-8\\mathbf{j})4=16\\mathbf{i}-32\\mathbf{j}$."},{"title":"Find the speed","body":"Speed $=\\sqrt{16^2+(-32)^2}=\\sqrt{1280}=16\\sqrt5\\ \\mathrm{m\\,s^{-1}}$, about $36\\ \\mathrm{m\\,s^{-1}}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_Oct_Q08","year":2022,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2022","qNo":8,"marks":16,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["05_ConstantAcceleration2D"],"secondaryTopicNames":["Constant Acceleration in 2D"],"topics":["02_WorkingWithVectors","05_ConstantAcceleration2D"],"topicNames":["Working with Vectors","Constant Acceleration in 2D"],"image":"ial/wme01/questions/WME01-01_Y2022_Oct_Q08_M16_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2022_Oct_Q08_M16_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ 3\\sqrt{17}\\ \\mathrm{km\\,h^{-1}}.\\quad (b)\\ p=-9,\\ q=3.\\quad (c)\\ \\text{bearing}=323^\\circ$.","steps":[{"title":"Find the speed of A","body":"$|\\mathbf{v}_A|=\\sqrt{3^2+12^2}=\\sqrt{153}=3\\sqrt{17}\\ \\mathrm{km\\,h^{-1}}$."},{"title":"Write A position","body":"At time $t$, $\\mathbf{a}=(-9\\mathbf{i}+6\\mathbf{j})+t(3\\mathbf{i}+12\\mathbf{j})=(-9+3t)\\mathbf{i}+(6+12t)\\mathbf{j}$."},{"title":"Write B position","body":"$\\mathbf{b}=(16\\mathbf{i}+6\\mathbf{j})+t(p\\mathbf{i}+q\\mathbf{j})=(16+pt)\\mathbf{i}+(6+qt)\\mathbf{j}$."},{"title":"Use AB vector","body":"$\\overrightarrow{AB}=\\mathbf{b}-\\mathbf{a}=[25+(p-3)t]\\mathbf{i}+[(q-12)t]\\mathbf{j}$."},{"title":"Compare components","body":"Given $\\overrightarrow{AB}=(25-12t)\\mathbf{i}-9t\\mathbf{j}$, compare coefficients: $p-3=-12$ and $q-12=-9$."},{"title":"Find p and q","body":"Therefore $p=-9$ and $q=3$."},{"title":"Find the time when the distance is 15","body":"Use $|\\overrightarrow{AB}|=15$: $(25-12t)^2+(-9t)^2=15^2$."},{"title":"Solve the distance equation","body":"This gives $225t^2-600t+400=0$, so $(3t-4)^2=0$ and $t=\\dfrac43$."},{"title":"Find BA at this time","body":"At $t=\\dfrac43$, $\\overrightarrow{AB}=9\\mathbf{i}-12\\mathbf{j}$. Therefore $\\overrightarrow{BA}=-9\\mathbf{i}+12\\mathbf{j}$."},{"title":"Convert to a bearing","body":"A is north-west of B. The angle west of north satisfies $\\tan\\theta=\\dfrac{9}{12}$, so $\\theta=36.9^\\circ$. Bearing $=360^\\circ-36.9^\\circ=323^\\circ$ to the nearest degree."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2023_Jan_Q03","year":2023,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2023","qNo":3,"marks":10,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["05_ConstantAcceleration2D"],"secondaryTopicNames":["Constant Acceleration in 2D"],"topics":["02_WorkingWithVectors","05_ConstantAcceleration2D"],"topicNames":["Working with Vectors","Constant Acceleration in 2D"],"image":"ial/wme01/questions/WME01-01_Y2023_Jan_Q03_M10_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2023_Jan_Q03_M10_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ 3\\sqrt5\\ \\mathrm{m\\,s^{-1}}\\approx6.7\\ \\mathrm{m\\,s^{-1}}.\\quad (b)\\ 27^\\circ.\\quad (c)\\ T=3.2$.","steps":[{"title":"Find the velocity at t = 2","body":"$\\mathbf{v}=(14\\mathbf{i}-5\\mathbf{j})+2(-4\\mathbf{i}+\\mathbf{j})=6\\mathbf{i}-3\\mathbf{j}$."},{"title":"Find the speed","body":"The speed is $\\sqrt{6^2+(-3)^2}=\\sqrt{45}=3\\sqrt5\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Find the angle with i","body":"The velocity $6\\mathbf{i}-3\\mathbf{j}$ is below the positive $\\mathbf{i}$ direction. The acute angle satisfies $\\tan\\theta=\\dfrac{3}{6}$."},{"title":"State the angle","body":"$\\theta=26.6^\\circ$, so the size of the angle is $27^\\circ$ to the nearest degree."},{"title":"Write the velocity at time T","body":"$\\mathbf{v}(T)=(14-4T)\\mathbf{i}+(-5+T)\\mathbf{j}$."},{"title":"Use the given direction","body":"The direction is parallel to $2\\mathbf{i}-3\\mathbf{j}$, so the component ratio must match: $\\dfrac{14-4T}{2}=\\dfrac{-5+T}{-3}$."},{"title":"Solve for T","body":"$-3(14-4T)=2(-5+T)$, so $-42+12T=-10+2T$. Hence $10T=32$ and $T=3.2$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2023_MayJune_Q02","year":2023,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2023","qNo":2,"marks":10,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["06_Forces","07_NewtonsSecondLaw"],"secondaryTopicNames":["Forces","Newton's Second Law"],"topics":["02_WorkingWithVectors","06_Forces","07_NewtonsSecondLaw"],"topicNames":["Working with Vectors","Forces","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2023_MayJune_Q02_M10_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2023_MayJune_Q02_M10_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ \\mathbf{F}_3=(14-3c)\\mathbf{i}+(-7-4c)\\mathbf{j}.\\quad (b)\\ 118^\\circ\\ \\text{approximately}.\\quad (c)\\ m=2$.","steps":[{"title":"Use equilibrium","body":"For equilibrium, $\\mathbf{F}_1+\\mathbf{F}_2+\\mathbf{F}_3=\\mathbf{0}$. Hence $\\mathbf{F}_3=-(\\mathbf{F}_1+\\mathbf{F}_2)$."},{"title":"Find F3","body":"$\\mathbf{F}_1+\\mathbf{F}_2=(3c-14)\\mathbf{i}+(4c+7)\\mathbf{j}$, so $\\mathbf{F}_3=(14-3c)\\mathbf{i}+(-7-4c)\\mathbf{j}$."},{"title":"Find the resultant when c = 2","body":"When $c=2$, $\\mathbf{F}_1=6\\mathbf{i}+8\\mathbf{j}$ and $\\mathbf{F}_2=-14\\mathbf{i}+7\\mathbf{j}$. Therefore the resultant is $-8\\mathbf{i}+15\\mathbf{j}$."},{"title":"Find the angle","body":"The resultant is in the second quadrant. Its angle from the positive $\\mathbf{i}$ direction is $180^\\circ-\\tan^{-1}\\left(\\dfrac{15}{8}\\right)=118.1^\\circ$, so the angle is about $118^\\circ$."},{"title":"Find the magnitude of the resultant","body":"$|\\mathbf{R}|=\\sqrt{(-8)^2+15^2}=17\\ \\mathrm{N}$."},{"title":"Use F = ma","body":"The acceleration magnitude is $8.5\\ \\mathrm{m\\,s^{-2}}$, so $17=8.5m$. Hence $m=2$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2023_MayJune_Q08","year":2023,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2023","qNo":8,"marks":9,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["05_ConstantAcceleration2D"],"secondaryTopicNames":["Constant Acceleration in 2D"],"topics":["02_WorkingWithVectors","05_ConstantAcceleration2D"],"topicNames":["Working with Vectors","Constant Acceleration in 2D"],"image":"ial/wme01/questions/WME01-01_Y2023_MayJune_Q08_M09_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2023_MayJune_Q08_M09_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ \\mathbf{r}=(t-2)\\mathbf{i}+(2t+1)\\mathbf{j}.\\quad (b)\\ \\mathbf{s}=(25-t)\\mathbf{i}+(25-t)\\mathbf{j}.\\quad (c)\\ \\overrightarrow{SR}=(2t-27)\\mathbf{i}+(3t-24)\\mathbf{j}.\\quad (d)\\ t=\\dfrac{126}{13}\\ \\mathrm{s}\\approx9.7\\ \\mathrm{s}$.","steps":[{"title":"Find the velocity of R","body":"R moves from $-2\\mathbf{i}+\\mathbf{j}$ to $9\\mathbf{i}+23\\mathbf{j}$ in $11$ s. Its displacement is $11\\mathbf{i}+22\\mathbf{j}$, so its velocity is $\\mathbf{i}+2\\mathbf{j}$."},{"title":"Write r","body":"$\\mathbf{r}=(-2\\mathbf{i}+\\mathbf{j})+t(\\mathbf{i}+2\\mathbf{j})=(t-2)\\mathbf{i}+(2t+1)\\mathbf{j}$."},{"title":"Write s","body":"Point C has position vector $25\\mathbf{i}+25\\mathbf{j}$. Since S moves with velocity $-\\mathbf{i}-\\mathbf{j}$, $\\mathbf{s}=(25-t)\\mathbf{i}+(25-t)\\mathbf{j}$."},{"title":"Find SR vector","body":"$\\overrightarrow{SR}=\\mathbf{r}-\\mathbf{s}=[(t-2)-(25-t)]\\mathbf{i}+[(2t+1)-(25-t)]\\mathbf{j}$."},{"title":"Simplify SR","body":"Therefore $\\overrightarrow{SR}=(2t-27)\\mathbf{i}+(3t-24)\\mathbf{j}$ m."},{"title":"Minimise the distance squared","body":"The distance squared is $d^2=(2t-27)^2+(3t-24)^2$."},{"title":"Expand the quadratic","body":"$d^2=4t^2-108t+729+9t^2-144t+576=13t^2-252t+1305$."},{"title":"Find the minimum time","body":"The quadratic is minimum at $t=\\dfrac{252}{2\\cdot13}=\\dfrac{126}{13}=9.69\\ldots$ s."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2023_Oct_Q04","year":2023,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2023","qNo":4,"marks":10,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["05_ConstantAcceleration2D"],"secondaryTopicNames":["Constant Acceleration in 2D"],"topics":["02_WorkingWithVectors","05_ConstantAcceleration2D"],"topicNames":["Working with Vectors","Constant Acceleration in 2D"],"image":"ial/wme01/questions/WME01-01_Y2023_Oct_Q04_M10_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2023_Oct_Q04_M10_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ \\mathbf{v}=(5-5\\lambda)\\mathbf{i}+(-8+10\\lambda)\\mathbf{j}$. $(b)\\ 25\\lambda^2-42\\lambda-16=0$. $(c)\\ \\text{bearing}=339^\\circ$.","steps":[{"title":"Use v = u + at","body":"The initial velocity is $(5\\mathbf{i}-8\\mathbf{j})$ and the acceleration is $(-\\lambda\\mathbf{i}+2\\lambda\\mathbf{j})$. At $t=5$, $\\mathbf{v}=(5\\mathbf{i}-8\\mathbf{j})+5(-\\lambda\\mathbf{i}+2\\lambda\\mathbf{j})$."},{"title":"Write the velocity at t = 5","body":"So $\\mathbf{v}=(5-5\\lambda)\\mathbf{i}+(-8+10\\lambda)\\mathbf{j}$."},{"title":"Use the speed at t = 5","body":"The speed is $13$, so $(5-5\\lambda)^2+(-8+10\\lambda)^2=13^2$."},{"title":"Simplify to the printed equation","body":"Expanding gives $25-50\\lambda+25\\lambda^2+64-160\\lambda+100\\lambda^2=169$. Therefore $125\\lambda^2-210\\lambda-80=0$, and dividing by $5$ gives $25\\lambda^2-42\\lambda-16=0$."},{"title":"Find lambda","body":"Solving $25\\lambda^2-42\\lambda-16=0$ gives $\\lambda=2$ or $\\lambda=-\\dfrac{8}{25}$. Since $\\lambda$ is positive, $\\lambda=2$."},{"title":"Find the velocity at t = 4","body":"$\\mathbf{v}(4)=(5\\mathbf{i}-8\\mathbf{j})+4(-2\\mathbf{i}+4\\mathbf{j})=-3\\mathbf{i}+8\\mathbf{j}$."},{"title":"Convert to a bearing","body":"The motion is north-west. The angle west of north satisfies $\\tan\\alpha=\\dfrac{3}{8}$, so $\\alpha=20.6^\\circ$. The bearing is $360^\\circ-20.6^\\circ=339.4^\\circ$, so $339^\\circ$ to the nearest degree."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2023_Oct_Q06","year":2023,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2023","qNo":6,"marks":15,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["05_ConstantAcceleration2D"],"secondaryTopicNames":["Constant Acceleration in 2D"],"topics":["02_WorkingWithVectors","05_ConstantAcceleration2D"],"topicNames":["Working with Vectors","Constant Acceleration in 2D"],"image":"ial/wme01/questions/WME01-01_Y2023_Oct_Q06_M15_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2023_Oct_Q06_M15_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ \\mathbf{v}_P=10\\mathbf{i}-4\\mathbf{j}\\ \\mathrm{km\\,h^{-1}}.\\quad (b)\\ \\mathbf{p}=(15+10t)\\mathbf{i}+(36-4t)\\mathbf{j}.\\quad (c)(ii)\\ 30\\mathbf{i}+30\\mathbf{j}.\\quad (d)\\ 2\\sqrt{101}\\ \\mathrm{km}$.","steps":[{"title":"Find the velocity of P","body":"From 12:00 to 12:30, the displacement of P is $(20\\mathbf{i}+34\\mathbf{j})-(15\\mathbf{i}+36\\mathbf{j})=5\\mathbf{i}-2\\mathbf{j}$ km. The time is $0.5$ hours, so $\\mathbf{v}_P=\\dfrac{5\\mathbf{i}-2\\mathbf{j}}{0.5}=10\\mathbf{i}-4\\mathbf{j}$."},{"title":"Write the position of P","body":"At $t$ hours after 12:00, $\\mathbf{p}=(15\\mathbf{i}+36\\mathbf{j})+t(10\\mathbf{i}-4\\mathbf{j})=(15+10t)\\mathbf{i}+(36-4t)\\mathbf{j}$."},{"title":"Verify the collision time","body":"At 13:30, $t=1.5$. Then $\\mathbf{p}=(15+15)\\mathbf{i}+(36-6)\\mathbf{j}=30\\mathbf{i}+30\\mathbf{j}$. Also $\\mathbf{q}=(42-8(1.5))\\mathbf{i}+(9+14(1.5))\\mathbf{j}=30\\mathbf{i}+30\\mathbf{j}$."},{"title":"State the collision position","body":"Since both position vectors are the same, the collision point has position vector $30\\mathbf{i}+30\\mathbf{j}$ km."},{"title":"Find P at 14:30","body":"At 14:30, $t=2.5$, so $\\mathbf{p}=(15+25)\\mathbf{i}+(36-10)\\mathbf{j}=40\\mathbf{i}+26\\mathbf{j}$."},{"title":"Find Q after changing course","body":"At 12:30, $t=0.5$, so $\\mathbf{q}=38\\mathbf{i}+16\\mathbf{j}$. From 12:30 to 14:30 is $2$ hours due north at $15\\ \\mathrm{km\\,h^{-1}}$, so the extra displacement is $30\\mathbf{j}$. Thus Q is at $38\\mathbf{i}+46\\mathbf{j}$."},{"title":"Find the distance","body":"The separation vector is $(40-38)\\mathbf{i}+(26-46)\\mathbf{j}=2\\mathbf{i}-20\\mathbf{j}$. The distance is $\\sqrt{2^2+20^2}=\\sqrt{404}=2\\sqrt{101}\\ \\mathrm{km}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2024_Jan_Q07","year":2024,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2024","qNo":7,"marks":11,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["05_ConstantAcceleration2D"],"secondaryTopicNames":["Constant Acceleration in 2D"],"topics":["02_WorkingWithVectors","05_ConstantAcceleration2D"],"topicNames":["Working with Vectors","Constant Acceleration in 2D"],"image":"ial/wme01/questions/WME01-01_Y2024_Jan_Q07_M11_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2024_Jan_Q07_M11_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ 20\\ \\mathrm{km\\,h^{-1}}.\\quad (b)\\ \\mathbf{s}=(19+12t)\\mathbf{i}+(22-16t)\\mathbf{j}.\\quad (c)(i)\\ t=0.49.\\quad (c)(ii)\\ \\text{minimum distance}=1.4\\ \\mathrm{km},\\ \\text{so it is safe}$.","steps":[{"title":"Find the speed","body":"The velocity is $12\\mathbf{i}-16\\mathbf{j}$, so the speed is $\\sqrt{12^2+(-16)^2}=20\\ \\mathrm{km\\,h^{-1}}$."},{"title":"Write the ship position vector","body":"At time $t$ hours after midnight, $\\mathbf{s}=(19\\mathbf{i}+22\\mathbf{j})+t(12\\mathbf{i}-16\\mathbf{j})=(19+12t)\\mathbf{i}+(22-16t)\\mathbf{j}$."},{"title":"Form the vector from lighthouse to ship","body":"The lighthouse is at $26\\mathbf{i}+15\\mathbf{j}$. Therefore $\\overrightarrow{LS}=\\mathbf{s}-\\mathbf{l}=(12t-7)\\mathbf{i}+(7-16t)\\mathbf{j}$."},{"title":"Use distance squared","body":"The square of the distance is $d^2=(12t-7)^2+(7-16t)^2=400t^2-392t+98$."},{"title":"Find the time of closest approach","body":"This quadratic is minimum when $t=\\dfrac{392}{2\\cdot400}=0.49$."},{"title":"Find the minimum distance","body":"At $t=0.49$, $d^2=1.96$, so $d=1.4\\ \\mathrm{km}$."},{"title":"Decide if the course is safe","body":"The unsafe distance is $1.3$ km. Since $1.4>1.3$, it is safe for the ship to continue its course."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2024_MayJune_Q07","year":2024,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2024","qNo":7,"marks":13,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["05_ConstantAcceleration2D"],"secondaryTopicNames":["Constant Acceleration in 2D"],"topics":["02_WorkingWithVectors","05_ConstantAcceleration2D"],"topicNames":["Working with Vectors","Constant Acceleration in 2D"],"image":"ial/wme01/questions/WME01-01_Y2024_MayJune_Q07_M13_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2024_MayJune_Q07_M13_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ \\mathbf{v}_B=16\\mathbf{i}+12\\mathbf{j}\\ \\mathrm{km\\,h^{-1}}.\\quad (b)\\ \\mathbf{s}=(10+16t)\\mathbf{i}+(5+12t)\\mathbf{j}.\\quad (c)\\ \\overrightarrow{AB}=(10-24t)\\mathbf{i}+(12t-15)\\mathbf{j}.\\quad (d)\\ \\text{no collision}.\\quad (e)\\ \\dfrac{20\\sqrt2}{3}\\ \\mathrm{km}\\approx9.4\\ \\mathrm{km}$.","steps":[{"title":"Resolve the velocity of B","body":"For a bearing angle $\\alpha$ with $\\tan\\alpha=\\dfrac43$, use $\\sin\\alpha=\\dfrac45$ and $\\cos\\alpha=\\dfrac35$. Therefore $\\mathbf{v}_B=20\\sin\\alpha\\mathbf{i}+20\\cos\\alpha\\mathbf{j}=16\\mathbf{i}+12\\mathbf{j}$."},{"title":"Write the position of B","body":"At noon, B is at $10\\mathbf{i}+5\\mathbf{j}$. With constant velocity $16\\mathbf{i}+12\\mathbf{j}$, $\\mathbf{s}=(10+16t)\\mathbf{i}+(5+12t)\\mathbf{j}$."},{"title":"Find AB vector","body":"A has position vector $\\mathbf{r}=40t\\mathbf{i}+20\\mathbf{j}$. Hence $\\overrightarrow{AB}=\\mathbf{s}-\\mathbf{r}=(10+16t-40t)\\mathbf{i}+(5+12t-20)\\mathbf{j}$."},{"title":"Show the printed expression","body":"This simplifies to $\\overrightarrow{AB}=(10-24t)\\mathbf{i}+(12t-15)\\mathbf{j}$ km."},{"title":"Show the boats do not collide","body":"For collision, both components must be zero. From $10-24t=0$, $t=\\dfrac{5}{12}$. From $12t-15=0$, $t=\\dfrac54$. These times are different, so the boats never collide."},{"title":"Use the bearing 225 degrees condition","body":"A bearing of $225^\\circ$ means B is south-west of A, so the i and j components of $\\overrightarrow{AB}$ are equal and negative. Set $10-24t=12t-15$."},{"title":"Find the distance","body":"The equation gives $t=\\dfrac{25}{36}$. Then each component is $-\\dfrac{20}{3}$, so the distance is $\\sqrt{\\left(\\dfrac{20}{3}\\right)^2+\\left(\\dfrac{20}{3}\\right)^2}=\\dfrac{20\\sqrt2}{3}\\ \\mathrm{km}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2024_Oct_Q03","year":2024,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2024","qNo":3,"marks":11,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["05_ConstantAcceleration2D"],"secondaryTopicNames":["Constant Acceleration in 2D"],"topics":["02_WorkingWithVectors","05_ConstantAcceleration2D"],"topicNames":["Working with Vectors","Constant Acceleration in 2D"],"image":"ial/wme01/questions/WME01-01_Y2024_Oct_Q03_M11_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2024_Oct_Q03_M11_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ \\mathbf{r}_A=(25+15t)\\mathbf{i}+(10+12t)\\mathbf{j}.\\quad (b)\\ V=\\dfrac{5\\sqrt{41}}{6}\\ \\mathrm{m\\,s^{-1}}\\approx5.3\\ \\mathrm{m\\,s^{-1}}.\\quad (c)\\ A\\ \\text{also passes through }P$.","steps":[{"title":"Find the velocity of A","body":"From 1 pm to 3 pm is 2 hours. The displacement of A is $(55\\mathbf{i}+34\\mathbf{j})-(25\\mathbf{i}+10\\mathbf{j})=30\\mathbf{i}+24\\mathbf{j}$ km, so $\\mathbf{v}_A=15\\mathbf{i}+12\\mathbf{j}\\ \\mathrm{km\\,h^{-1}}$."},{"title":"Write the position vector of A","body":"At time $t$ hours after 1 pm, $\\mathbf{r}_A=(25\\mathbf{i}+10\\mathbf{j})+t(15\\mathbf{i}+12\\mathbf{j})=(25+15t)\\mathbf{i}+(10+12t)\\mathbf{j}$."},{"title":"Convert the speed to metres per second","body":"The speed of A is $\\sqrt{15^2+12^2}=\\sqrt{369}\\ \\mathrm{km\\,h^{-1}}$. Converting to $\\mathrm{m\\,s^{-1}}$, $V=\\sqrt{369}\\times\\dfrac{1000}{3600}=\\dfrac{5\\sqrt{41}}{6}\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Find the point P reached by B","body":"At 2:30 pm, $t=1.5$ hours after 1 pm. For B, $\\mathbf{r}_B=(35\\mathbf{i}+51\\mathbf{j})+1.5(20\\mathbf{i}-6\\mathbf{j})=65\\mathbf{i}+42\\mathbf{j}$."},{"title":"Check whether A reaches P","body":"Set $\\mathbf{r}_A=65\\mathbf{i}+42\\mathbf{j}$. From the i-component, $25+15t=65$, so $t=\\dfrac{8}{3}$."},{"title":"Confirm with the j-component","body":"When $t=\\dfrac{8}{3}$, $10+12t=10+32=42$. Both components match, so A also passes through P."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2025_Jan_Q05","year":2025,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2025","qNo":5,"marks":7,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["01_QuantitiesUnitsModelling","05_ConstantAcceleration2D","04_ConstantAcceleration1D"],"secondaryTopicNames":["Quantities, Units & Modelling","Constant Acceleration in 2D","Constant Acceleration in 1D"],"topics":["02_WorkingWithVectors","01_QuantitiesUnitsModelling","05_ConstantAcceleration2D","04_ConstantAcceleration1D"],"topicNames":["Working with Vectors","Quantities, Units & Modelling","Constant Acceleration in 2D","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2025_Jan_Q05_M07_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2025_Jan_Q05_M07_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ \\mathbf{v}=1.5\\mathbf{i}-\\mathbf{j}\\ \\mathrm{m\\,s^{-1}}.\\quad (b)\\ \\text{distance}=2\\sqrt{13}\\ \\mathrm{m}\\approx7.2\\ \\mathrm{m}$.","steps":[{"title":"Find the displacement over 8 seconds","body":"From $t=1$ to $t=9$, the displacement is $(10\\mathbf{i}-3\\mathbf{j})-(-2\\mathbf{i}+5\\mathbf{j})=12\\mathbf{i}-8\\mathbf{j}$."},{"title":"Find the velocity","body":"The time interval is $8$ seconds, so $\\mathbf{v}=\\dfrac{12\\mathbf{i}-8\\mathbf{j}}{8}=1.5\\mathbf{i}-\\mathbf{j}\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Find the position at t=7","body":"Time $t=7$ is 6 seconds after $t=1$. Therefore $\\mathbf{r}_B(7)=(-2\\mathbf{i}+5\\mathbf{j})+6(1.5\\mathbf{i}-\\mathbf{j})=7\\mathbf{i}-\\mathbf{j}$."},{"title":"Find the vector from B to the target","body":"The target has position vector $13\\mathbf{i}-5\\mathbf{j}$. The vector from the ball to the target is $(13\\mathbf{i}-5\\mathbf{j})-(7\\mathbf{i}-\\mathbf{j})=6\\mathbf{i}-4\\mathbf{j}$."},{"title":"Find the distance","body":"The distance is $\\sqrt{6^2+(-4)^2}=\\sqrt{52}=2\\sqrt{13}\\ \\mathrm{m}$, which is about $7.2\\ \\mathrm{m}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2025_MayJune_Q02","year":2025,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2025","qNo":2,"marks":7,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["05_ConstantAcceleration2D"],"secondaryTopicNames":["Constant Acceleration in 2D"],"topics":["02_WorkingWithVectors","05_ConstantAcceleration2D"],"topicNames":["Working with Vectors","Constant Acceleration in 2D"],"image":"ial/wme01/questions/WME01-01_Y2025_MayJune_Q02_M07_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2025_MayJune_Q02_M07_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ \\mathbf{v}_A=5\\mathbf{i}-4\\mathbf{j}\\ \\mathrm{m\\,s^{-1}}.\\quad (b)\\ \\mathbf{r}=(5t-15)\\mathbf{i}+(24-4t)\\mathbf{j}.\\quad (c)\\ \\text{bearing}=203^\\circ$.","steps":[{"title":"Part (a): Find velocity of A - Find change in position","body":"Given positions for particle A:\n \n ; At $t = 2$: $\\mathbf{r} = -5\\mathbf{i} + 16\\mathbf{j}$\n ; At $t = 5$: $\\mathbf{r} = 10\\mathbf{i} + 4\\mathbf{j}$\n \n \n $\\mathbf{v} = \\frac{\\Delta \\mathbf{r}}{\\Delta t}$\n \n $\\mathbf{v}_A = \\frac{(10\\mathbf{i} + 4\\mathbf{j}) - (-5\\mathbf{i} + 16\\mathbf{j})}{5 - 2}$ $= \\frac{(10 + 5)\\mathbf{i} + (4 - 16)\\mathbf{j}}{3}$ $= \\frac{15\\mathbf{i} - 12\\mathbf{j}}{3}$ $= 5\\mathbf{i} - 4\\mathbf{j} \\text{ m s}^{-1}$"},{"title":"Part (b): Find expression for r at time t - Use position-velocity relationship","body":"$\\mathbf{r}(t) = \\mathbf{r}(t_0) + \\mathbf{v}(t - t_0)$\n \n Using $t_0 = 2$ with $\\mathbf{r}(2) = -5\\mathbf{i} + 16\\mathbf{j}$:\n \n $\\mathbf{r}(t) = (-5\\mathbf{i} + 16\\mathbf{j}) + (5\\mathbf{i} - 4\\mathbf{j})(t - 2)$ $= -5\\mathbf{i} + 16\\mathbf{j} + 5(t-2)\\mathbf{i} - 4(t-2)\\mathbf{j}$ $= -5\\mathbf{i} + 16\\mathbf{j} + (5t - 10)\\mathbf{i} + (-4t + 8)\\mathbf{j}$ $= (-5 + 5t - 10)\\mathbf{i} + (16 - 4t + 8)\\mathbf{j}$ $= (5t - 15)\\mathbf{i} + (24 - 4t)\\mathbf{j}$"},{"title":"Part (c): Find bearing of B from A when t = 5 - Find positions at t = 5","body":"For A at $t = 5$: $\\mathbf{r}_A = 10\\mathbf{i} + 4\\mathbf{j}$ (given)\n \n For B at $t = 5$:\n $\\mathbf{s}_B = -5\\mathbf{i} + 7\\mathbf{j} + 5(2\\mathbf{i} - 3\\mathbf{j})$ $= -5\\mathbf{i} + 7\\mathbf{j} + 10\\mathbf{i} - 15\\mathbf{j}$ $= 5\\mathbf{i} - 8\\mathbf{j}$"},{"title":"Part (c): Find bearing of B from A when t = 5 - Find vector from A to B","body":"$\\overrightarrow{AB} = \\mathbf{s}_B - \\mathbf{r}_A$ $= (5\\mathbf{i} - 8\\mathbf{j}) - (10\\mathbf{i} + 4\\mathbf{j})$ $= -5\\mathbf{i} - 12\\mathbf{j}$"},{"title":"Part (c): Find bearing of B from A when t = 5 - Find angle and bearing","body":"Angle from South (negative j direction):\n $\\tan \\alpha = \\frac{5}{12}$ $\\alpha = \\tan^{-1}\\left(\\frac{5}{12}\\right)$ $\\alpha = 22.619...°$\n \n Bearing = $180° + \\alpha = 180° + 22.619...° = 202.619...°$"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2025_MayJune_Q07","year":2025,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2025","qNo":7,"marks":13,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["05_ConstantAcceleration2D"],"secondaryTopicNames":["Constant Acceleration in 2D"],"topics":["02_WorkingWithVectors","05_ConstantAcceleration2D"],"topicNames":["Working with Vectors","Constant Acceleration in 2D"],"image":"ial/wme01/questions/WME01-01_Y2025_MayJune_Q07_M13_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2025_MayJune_Q07_M13_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ |\\mathbf{a}_A|=\\sqrt{17}\\ \\mathrm{km\\,h^{-2}}\\approx4.1\\ \\mathrm{km\\,h^{-2}}.\\quad (b)\\ \\mathbf{a}_B=-\\mathbf{i}-2\\mathbf{j}\\ \\mathrm{km\\,h^{-2}}.\\quad (c)\\ \\mathbf{v}_B(0)=6\\mathbf{i}+5\\mathbf{j}\\ \\mathrm{km\\,h^{-1}}.\\quad (d)\\ T_1=\\dfrac{-1+\\sqrt{17}}{2}\\ \\text{hours}.\\quad (e)\\ 3T_2^2-14T_2+4=0,\\ p=-14,\\ q=4$.","steps":[{"title":"Part (a): Find magnitude of acceleration of A - Identify acceleration from velocity function","body":"Given: $\\mathbf{v}_A = 2\\mathbf{i} + 3\\mathbf{j} + (\\mathbf{i} - 4\\mathbf{j})t$\n \n This is in form: $\\mathbf{v} = \\mathbf{u} + \\mathbf{a}t$\n \n Therefore:\n \n ; Initial velocity: $\\mathbf{u}_A = 2\\mathbf{i} + 3\\mathbf{j}$\n ; Acceleration: $\\mathbf{a}_A = \\mathbf{i} - 4\\mathbf{j}$ km h$^{-2}$"},{"title":"Part (a): Find magnitude of acceleration of A - Find magnitude","body":"$|\\mathbf{a}| = \\sqrt{a_x^2 + a_y^2}$\n \n $|\\mathbf{a}_A| = \\sqrt{1^2 + (-4)^2}$ $= \\sqrt{1 + 16}$ $= \\sqrt{17}$ $= 4.123...$ $= 4.1 \\text{ km h}^{-2} \\text{ (2 sf)}$"},{"title":"Part (b): Find acceleration of B - Use two velocity points to find acceleration","body":"Given:\n \n ; At $t = 2$: $\\mathbf{v}_B = 4\\mathbf{i} + \\mathbf{j}$\n ; At $t = 5$: $\\mathbf{v}_B = \\mathbf{i} - 5\\mathbf{j}$\n \n \n $\\mathbf{a} = \\frac{\\Delta \\mathbf{v}}{\\Delta t}$\n \n $\\mathbf{a}_B = \\frac{(\\mathbf{i} - 5\\mathbf{j}) - (4\\mathbf{i} + \\mathbf{j})}{5 - 2}$ $= \\frac{(1-4)\\mathbf{i} + (-5-1)\\mathbf{j}}{3}$ $= \\frac{-3\\mathbf{i} - 6\\mathbf{j}}{3}$ $= -\\mathbf{i} - 2\\mathbf{j} \\text{ km h}^{-2}$"},{"title":"Part (c): Find velocity of B at t = 0 - Use velocity equation backward","body":"$\\mathbf{v}(t) = \\mathbf{v}(t_0) + \\mathbf{a}(t - t_0)$\n \n From $t = 2$ back to $t = 0$:\n \n $\\mathbf{v}_B(0) = \\mathbf{v}_B(2) + \\mathbf{a}_B(0 - 2)$ $= (4\\mathbf{i} + \\mathbf{j}) + (-\\mathbf{i} - 2\\mathbf{j})(-2)$ $= 4\\mathbf{i} + \\mathbf{j} + 2\\mathbf{i} + 4\\mathbf{j}$ $= 6\\mathbf{i} + 5\\mathbf{j} \\text{ km h}^{-1}$"},{"title":"Part (d): Find exact value of $T_1$ when both have same speed - Express velocities at time t","body":"For boat A:\n $\\mathbf{v}_A(t) = 2\\mathbf{i} + 3\\mathbf{j} + (\\mathbf{i} - 4\\mathbf{j})t = (2+t)\\mathbf{i} + (3-4t)\\mathbf{j}$\n \n For boat B:\n $\\mathbf{v}_B(t) = (6\\mathbf{i} + 5\\mathbf{j}) + (-\\mathbf{i} - 2\\mathbf{j})t$ $= (6-t)\\mathbf{i} + (5-2t)\\mathbf{j}$"},{"title":"Part (d): Find exact value of $T_1$ when both have same speed - Find magnitudes","body":"$|\\mathbf{v}_A|^2 = (2+t)^2 + (3-4t)^2$ $= 4 + 4t + t^2 + 9 - 24t + 16t^2$ $= 17t^2 - 20t + 13$\n \n $|\\mathbf{v}_B|^2 = (6-t)^2 + (5-2t)^2$ $= 36 - 12t + t^2 + 25 - 20t + 4t^2$ $= 5t^2 - 32t + 61$"},{"title":"Part (d): Find exact value of $T_1$ when both have same speed - Set magnitudes equal","body":"$17t^2 - 20t + 13 = 5t^2 - 32t + 61$ $12t^2 + 12t - 48 = 0$ $t^2 + t - 4 = 0$"},{"title":"Part (d): Find exact value of $T_1$ when both have same speed - Solve using quadratic formula","body":"$t = \\frac{-1 \\pm \\sqrt{1 + 16}}{2}$ $= \\frac{-1 \\pm \\sqrt{17}}{2}$\n \n Taking positive value:\n $T_1 = \\frac{-1 + \\sqrt{17}}{2}$"},{"title":"Part (e): Show $3T_2^2 + pT_2 + q = 0$ - Condition for same direction","body":"Velocities parallel when:\n $\\frac{2 + T_2}{6 - T_2} = \\frac{3 - 4T_2}{5 - 2T_2}$"},{"title":"Part (e): Show $3T_2^2 + pT_2 + q = 0$ - Cross-multiply","body":"$(2 + T_2)(5 - 2T_2) = (3 - 4T_2)(6 - T_2)$ $10 - 4T_2 + 5T_2 - 2T_2^2 = 18 - 3T_2 - 24T_2 + 4T_2^2$ $10 + T_2 - 2T_2^2 = 18 - 27T_2 + 4T_2^2$ $0 = 4T_2^2 + 2T_2^2 - 27T_2 - T_2 + 18 - 10$ $0 = 6T_2^2 - 28T_2 + 8$"},{"title":"Part (e): Show $3T_2^2 + pT_2 + q = 0$ - Divide by 2 to get required form","body":"$0 = 3T_2^2 - 14T_2 + 4$\n \n Therefore: $p = -14$ and $q = 4$"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2026_Jan_Q06","year":2026,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2026","qNo":6,"marks":16,"topic":"02_WorkingWithVectors","topicName":"Working with Vectors","primaryTopic":"02_WorkingWithVectors","primaryTopicName":"Working with Vectors","secondaryTopics":["05_ConstantAcceleration2D"],"secondaryTopicNames":["Constant Acceleration in 2D"],"topics":["02_WorkingWithVectors","05_ConstantAcceleration2D"],"topicNames":["Working with Vectors","Constant Acceleration in 2D"],"image":"ial/wme01/questions/WME01-01_Y2026_Jan_Q06_M16_02_WorkingWithVectors.png","downloadName":"WME01-01_Y2026_Jan_Q06_M16_02_WorkingWithVectors.png","finalAnswer":"$(a)\\ 5\\sqrt{13}\\ \\mathrm{km\\,h^{-1}}.\\quad (b)\\ 321^\\circ.\\quad (c)\\ \\overrightarrow{SB}=(50-18t)\\mathbf{i}+(10-5t)\\mathbf{j}.\\quad (d)\\ \\text{no collision}.\\quad (e)\\ d=\\dfrac{70\\sqrt2}{13}\\ \\mathrm{km}\\approx7.6\\ \\mathrm{km}$.","steps":[{"title":"Find the speed of S","body":"The velocity of S is $10\\mathbf{i}+15\\mathbf{j}$. Its speed is the magnitude: $\\sqrt{10^2+15^2}=\\sqrt{325}=5\\sqrt{13}\\ \\mathrm{km\\,h^{-1}}$."},{"title":"Find the bearing of B","body":"B has velocity $-8\\mathbf{i}+10\\mathbf{j}$, so it moves west and north. The angle west of north satisfies $\\tan\\theta=\\dfrac{8}{10}$, giving $\\theta=38.66^\\circ$. The bearing is $360^\\circ-38.66^\\circ=321^\\circ$ to the nearest degree."},{"title":"Write both position vectors","body":"At time $t$ hours after 9 am, $\\mathbf{r}_S=(10t)\\mathbf{i}+(15t)\\mathbf{j}$. Also $\\mathbf{r}_B=(50\\mathbf{i}+10\\mathbf{j})+t(-8\\mathbf{i}+10\\mathbf{j})=(50-8t)\\mathbf{i}+(10+10t)\\mathbf{j}$."},{"title":"Find the relative position vector","body":"$\\overrightarrow{SB}=\\mathbf{r}_B-\\mathbf{r}_S=[(50-8t)-10t]\\mathbf{i}+[(10+10t)-15t]\\mathbf{j}=(50-18t)\\mathbf{i}+(10-5t)\\mathbf{j}$."},{"title":"Show they do not collide","body":"For a collision, both components of $\\overrightarrow{SB}$ must be zero at the same time. From $50-18t=0$, $t=\\dfrac{25}{9}$. From $10-5t=0$, $t=2$. These are different, so B and S do not collide."},{"title":"Find the north-east or south-west instant","body":"When the separation is along a $45^\\circ$ diagonal, the two components have equal magnitude. Using the given condition, set $50-18t=10-5t$, so $40=13t$ and $t=\\dfrac{40}{13}$."},{"title":"Find the distance d","body":"At $t=\\dfrac{40}{13}$, both components are $-\\dfrac{70}{13}$. Therefore $d=\\sqrt{\\left(\\dfrac{70}{13}\\right)^2+\\left(\\dfrac{70}{13}\\right)^2}=\\dfrac{70\\sqrt2}{13}=7.6\\ \\mathrm{km}$ to 2 significant figures."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2019_Oct_Q06","year":2019,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2019","qNo":6,"marks":12,"topic":"03_KinematicsGraphs","topicName":"Kinematics Graphs","primaryTopic":"03_KinematicsGraphs","primaryTopicName":"Kinematics Graphs","secondaryTopics":["01_QuantitiesUnitsModelling","07_NewtonsSecondLaw","02_WorkingWithVectors"],"secondaryTopicNames":["Quantities, Units & Modelling","Newton's Second Law","Working with Vectors"],"topics":["03_KinematicsGraphs","01_QuantitiesUnitsModelling","07_NewtonsSecondLaw","02_WorkingWithVectors"],"topicNames":["Kinematics Graphs","Quantities, Units & Modelling","Newton's Second Law","Working with Vectors"],"image":"ial/wme01/questions/WME01-01_Y2019_Oct_Q06_M12_03_KinematicsGraphs.png","downloadName":"WME01-01_Y2019_Oct_Q06_M12_03_KinematicsGraphs.png","finalAnswer":"$(a)$ Speed-time graph rises linearly to $V$ at $t=T$, then is horizontal until $t=30$. $(b)\\ V=0.8T.\\quad (c)\\ T^2-60T+500=0$, so $k=60$. $(d)\\ T=10$. $(e)$ For example, include reaction time at the start and avoid the instantaneous change to constant speed.","steps":[{"title":"Describe the speed-time graph","body":"The graph starts at $(0,0)$, rises in a straight line with gradient $0.8$ until time $T$ and speed $V$, then stays horizontal at speed $V$ until $t=30$."},{"title":"Write V in terms of T","body":"Uniform acceleration gives $V=0.8T$."},{"title":"Use area for the distance","body":"The distance is the area under the speed-time graph: $\\dfrac12TV+V(30-T)=200$."},{"title":"Substitute V","body":"Using $V=0.8T$: $\\dfrac12T(0.8T)+(0.8T)(30-T)=200$."},{"title":"Form the quadratic","body":"$0.4T^2+24T-0.8T^2=200$, so $-0.4T^2+24T-200=0$. Multiplying by $-2.5$ gives $T^2-60T+500=0$, so $k=60$."},{"title":"Solve and choose the valid root","body":"$T^2-60T+500=(T-10)(T-50)=0$, so $T=10$ or $50$. Since the whole race lasts $30$ s, $T=10$."},{"title":"Give two model improvements","body":"A more realistic model could include reaction time at the start, and could replace the instantaneous change from acceleration to constant speed with a smoother transition."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2020_Jan_Q05","year":2020,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2020","qNo":5,"marks":10,"topic":"03_KinematicsGraphs","topicName":"Kinematics Graphs","primaryTopic":"03_KinematicsGraphs","primaryTopicName":"Kinematics Graphs","secondaryTopics":["02_WorkingWithVectors","04_ConstantAcceleration1D"],"secondaryTopicNames":["Working with Vectors","Constant Acceleration in 1D"],"topics":["03_KinematicsGraphs","02_WorkingWithVectors","04_ConstantAcceleration1D"],"topicNames":["Kinematics Graphs","Working with Vectors","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2020_Jan_Q05_M10_03_KinematicsGraphs.png","downloadName":"WME01-01_Y2020_Jan_Q05_M10_03_KinematicsGraphs.png","finalAnswer":"$(a)$ Car: horizontal line at $40$; motorcyclist: two rising straight-line sections ending at the catch-up time. $(b)\\ t_1=10\\ \\mathrm{s}.\\quad (c)\\ T^2+40T-300=0$, so $k=40$.","steps":[{"title":"Describe the graph","body":"The car's graph is a horizontal line at $40\\ \\mathrm{m\\,s^{-1}}$. The motorcyclist's graph starts at zero, rises with gradient $4$ until $t=15$, then rises with smaller gradient $1$ for a further $T$ seconds."},{"title":"Find the equal-speed time","body":"Before $t=15$, the motorcyclist's speed is $4t$. Set this equal to the car's speed: $4t_1=40$, so $t_1=10$ s."},{"title":"Find the motorcyclist's speed at 15 seconds","body":"After the first $15$ seconds, the motorcyclist's speed is $4(15)=60\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Find the final speed at catch-up","body":"During the next $T$ seconds the acceleration is $1\\ \\mathrm{m\\,s^{-2}}$, so the speed at catch-up is $60+T$."},{"title":"Equate distances","body":"Motorcyclist distance $=\\dfrac12(15)(60)+\\dfrac12[60+(60+T)]T$. Car distance $=40(15+T)$."},{"title":"Simplify the equation","body":"$450+60T+\\dfrac12T^2=600+40T$. Hence $\\dfrac12T^2+20T-150=0$, so $T^2+40T-300=0$ and $k=40$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_Jan_Q07","year":2021,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2021","qNo":7,"marks":12,"topic":"03_KinematicsGraphs","topicName":"Kinematics Graphs","primaryTopic":"03_KinematicsGraphs","primaryTopicName":"Kinematics Graphs","secondaryTopics":["04_ConstantAcceleration1D"],"secondaryTopicNames":["Constant Acceleration in 1D"],"topics":["03_KinematicsGraphs","04_ConstantAcceleration1D"],"topicNames":["Kinematics Graphs","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2021_Jan_Q07_M12_03_KinematicsGraphs.png","downloadName":"WME01-01_Y2021_Jan_Q07_M12_03_KinematicsGraphs.png","finalAnswer":"$(a)\\ 24.5\\ \\mathrm{m\\,s^{-1}}.\\quad (b)$ Speed-time graph rises to $24.5$ at $t=2.5$, falls to $V$ at $t=2.5+T$, then is horizontal to $t=20$. $(c)\\ T=5.\\quad (d)\\ H=167\\ \\mathrm{m}$ to the nearest metre.","steps":[{"title":"Find speed when parachute opens","body":"The parachutist falls freely from rest for $2.5$ s, so $v=gt=9.8(2.5)=24.5\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Describe the graph","body":"The speed-time graph starts at $0$, rises linearly to $24.5$ at $t=2.5$, then decreases linearly with smaller gradient for $T$ seconds, then stays horizontal at speed $V$ until $t=20$."},{"title":"Use the deceleration distance","body":"During the deceleration phase, initial speed is $24.5$, acceleration is $-3.9$, time is $T$, and distance is $73.75$."},{"title":"Form the equation for T","body":"$73.75=24.5T+\\dfrac12(-3.9)T^2=24.5T-1.95T^2$."},{"title":"Choose the valid T","body":"Solving gives $T=5$ or $T=7.56\\ldots$. Since $T<6$, take $T=5$."},{"title":"Find V","body":"$V=24.5-3.9(5)=5\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Find the total height","body":"Height is the total area under the speed-time graph: first triangle $\\dfrac12(2.5)(24.5)=30.625$, deceleration distance $73.75$, and final rectangle $(20-2.5-5)(5)=62.5$."},{"title":"Round the height","body":"Total height $=30.625+73.75+62.5=166.875$ m, which rounds to $167$ m."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_MayJune_Q08","year":2021,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2021","qNo":8,"marks":13,"topic":"03_KinematicsGraphs","topicName":"Kinematics Graphs","primaryTopic":"03_KinematicsGraphs","primaryTopicName":"Kinematics Graphs","secondaryTopics":["04_ConstantAcceleration1D"],"secondaryTopicNames":["Constant Acceleration in 1D"],"topics":["03_KinematicsGraphs","04_ConstantAcceleration1D"],"topicNames":["Kinematics Graphs","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2021_MayJune_Q08_M13_03_KinematicsGraphs.png","downloadName":"WME01-01_Y2021_MayJune_Q08_M13_03_KinematicsGraphs.png","finalAnswer":"$(a)$ Tram A reaches speed $10$ at $t=5$; tram B starts at $t=20$, reaches speed $12$ at $t=24$, then later overtakes A. $(b)\\ d=\\dfrac{575}{3}\\ \\mathrm{m}\\approx192\\ \\mathrm{m}.\\quad (c)\\ 1170\\ \\mathrm{m}$.","steps":[{"title":"Describe tram A graph","body":"Tram A starts at $t=0$, accelerates at $2\\ \\mathrm{m\\,s^{-2}}$ for $5$ s, reaching speed $10\\ \\mathrm{m\\,s^{-1}}$, then continues at this constant speed."},{"title":"Describe tram B graph","body":"Tram B starts at $t=20$, accelerates at $3\\ \\mathrm{m\\,s^{-2}}$ for $4$ s, reaching speed $12\\ \\mathrm{m\\,s^{-1}}$, then continues at this constant speed. Its graph crosses A's distance later."},{"title":"Find when speeds are equal","body":"Tram A's constant speed is $10$. Tram B reaches speed $10$ after $\\dfrac{10}{3}$ s of acceleration, so the time from $t=0$ is $20+\\dfrac{10}{3}=\\dfrac{70}{3}$ s."},{"title":"Distance of A then","body":"A travels $\\dfrac12(5)(10)=25$ m in its acceleration phase, then $10\\left(\\dfrac{70}{3}-5\\right)=\\dfrac{550}{3}$ m. Total $=\\dfrac{625}{3}$ m."},{"title":"Distance of B then","body":"B is still accelerating from rest, so its distance is $\\dfrac12\\left(\\dfrac{10}{3}\\right)(10)=\\dfrac{50}{3}$ m."},{"title":"Find d","body":"$d=\\dfrac{625}{3}-\\dfrac{50}{3}=\\dfrac{575}{3}$ m."},{"title":"Set overtake distances equal","body":"For $t>24$, A's distance is $25+10(t-5)=10t-25$. B's distance is $\\dfrac12(4)(12)+12(t-24)=12t-264$."},{"title":"Find the overtake time","body":"Set $10t-25=12t-264$. Then $2t=239$ and $t=119.5$ s."},{"title":"Find the distance from the depot","body":"Using A's distance, $10(119.5)-25=1170$ m."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_MayJune_Q07","year":2022,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2022","qNo":7,"marks":13,"topic":"03_KinematicsGraphs","topicName":"Kinematics Graphs","primaryTopic":"03_KinematicsGraphs","primaryTopicName":"Kinematics Graphs","secondaryTopics":["04_ConstantAcceleration1D"],"secondaryTopicNames":["Constant Acceleration in 1D"],"topics":["03_KinematicsGraphs","04_ConstantAcceleration1D"],"topicNames":["Kinematics Graphs","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2022_MayJune_Q07_M13_03_KinematicsGraphs.png","downloadName":"WME01-01_Y2022_MayJune_Q07_M13_03_KinematicsGraphs.png","finalAnswer":"$(a)$ Ajaz reaches speed $4$ then runs horizontally; Beth has a steeper initial line to speed $T$, then horizontal, both ending at the same time. $(b)\\ 27.5\\ \\mathrm{s}.\\quad (c)\\ T=3.92\\ \\mathrm{s}\\ \\text{approximately}.\\quad (d)\\ 0.085\\ \\mathrm{m\\,s^{-1}}\\ \\text{approximately}$.","steps":[{"title":"Describe Ajaz graph","body":"Ajaz starts from rest, accelerates linearly to speed $4\\ \\mathrm{m\\,s^{-1}}$, then continues with a horizontal speed-time line at speed $4$."},{"title":"Describe Beth graph","body":"Beth starts from rest, has a steeper straight acceleration line for $T$ seconds, then a horizontal line. Both graphs finish at the same final time."},{"title":"Find Ajaz acceleration time","body":"Ajaz reaches speed $4$ with acceleration $0.8$, so the time is $\\dfrac{4}{0.8}=5$ s."},{"title":"Find Ajaz total time","body":"Distance during acceleration is $\\dfrac12(5)(4)=10$ m. The remaining $90$ m at speed $4$ takes $22.5$ s, so Ajaz's total time is $27.5$ s."},{"title":"Set Beth distance equation","body":"Beth accelerates for $T$ seconds to speed $T$, then runs at speed $T$ until time $27.5$. Her distance is $\\dfrac12T^2+T(27.5-T)$."},{"title":"Solve for T","body":"$100=\\dfrac12T^2+27.5T-T^2=27.5T-\\dfrac12T^2$. Thus $T^2-55T+200=0$. The valid root is $T=3.915\\ldots$ s."},{"title":"Find the finish speeds","body":"Ajaz finishes at $4\\ \\mathrm{m\\,s^{-1}}$. Beth's constant speed is $T=3.915\\ldots\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Find the difference","body":"Difference $=4-3.915\\ldots=0.085\\ \\mathrm{m\\,s^{-1}}$ approximately."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2023_Jan_Q01","year":2023,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2023","qNo":1,"marks":10,"topic":"03_KinematicsGraphs","topicName":"Kinematics Graphs","primaryTopic":"03_KinematicsGraphs","primaryTopicName":"Kinematics Graphs","secondaryTopics":["04_ConstantAcceleration1D"],"secondaryTopicNames":["Constant Acceleration in 1D"],"topics":["03_KinematicsGraphs","04_ConstantAcceleration1D"],"topicNames":["Kinematics Graphs","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2023_Jan_Q01_M10_03_KinematicsGraphs.png","downloadName":"WME01-01_Y2023_Jan_Q01_M10_03_KinematicsGraphs.png","finalAnswer":"$(a)$ Speed-time graph with times $T$, $T+180$, $3T+180$ and top speed $20$. $(b)\\ T=40\\ \\mathrm{s}.\\quad (c)\\ a=0.5\\ \\mathrm{m\\,s^{-2}}$.","steps":[{"title":"Relate the acceleration and deceleration times","body":"The train reaches $20\\ \\mathrm{m\\,s^{-1}}$ in $T$ seconds. Since the acceleration magnitude is twice the deceleration magnitude, the time needed to decelerate from $20$ to $0$ is $2T$."},{"title":"Describe the graph","body":"The speed-time graph rises linearly from $(0,0)$ to $(T,20)$, stays horizontal at speed $20$ from $T$ to $T+180$, then falls linearly to zero at $3T+180$."},{"title":"Use area under the graph","body":"The distance from A to B is $4.8\\ \\mathrm{km}=4800\\ \\mathrm{m}$. The area is $\\dfrac12(T)(20)+20(180)+\\dfrac12(2T)(20)$."},{"title":"Solve for T","body":"$4800=10T+3600+20T$, so $1200=30T$ and $T=40\\ \\mathrm{s}$."},{"title":"Find the acceleration","body":"During the first $T$ seconds, $20=aT$. With $T=40$, $a=\\dfrac{20}{40}=0.5\\ \\mathrm{m\\,s^{-2}}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2023_MayJune_Q05","year":2023,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2023","qNo":5,"marks":11,"topic":"03_KinematicsGraphs","topicName":"Kinematics Graphs","primaryTopic":"03_KinematicsGraphs","primaryTopicName":"Kinematics Graphs","secondaryTopics":["07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"secondaryTopicNames":["Newton's Second Law","Constant Acceleration in 1D"],"topics":["03_KinematicsGraphs","07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"topicNames":["Kinematics Graphs","Newton's Second Law","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2023_MayJune_Q05_M11_03_KinematicsGraphs.png","downloadName":"WME01-01_Y2023_MayJune_Q05_M11_03_KinematicsGraphs.png","finalAnswer":"$(a)\\ \\text{car distance}=V(T-15)$. $(b)$ Motorbike graph starts at $t=10$, reaches $\\dfrac{4V}{3}$ at $t=50$, stays constant to $t=60$, then falls to $V$ at $t=T$. $(c)\\ \\text{constant speed}=\\dfrac{4V}{3}.\\quad (d)\\ T=90$.","steps":[{"title":"Find the car distance","body":"The car graph is a triangle from $0$ to $30$ plus a rectangle from $30$ to $T$. Distance $=\\dfrac12(30)V+V(T-30)$."},{"title":"Simplify the car distance","body":"$\\dfrac12(30)V+V(T-30)=15V+VT-30V=V(T-15)$, as required."},{"title":"Describe the motorbike graph","body":"The motorbike starts at $(10,0)$, accelerates with the same gradient as the car until $t=50$, then travels at constant speed until $t=60$, then decelerates linearly to $(T,V)$."},{"title":"Find the motorbike constant speed","body":"The car acceleration is $\\dfrac{V}{30}$. The motorbike accelerates for $40$ s, so its speed is $40\\cdot\\dfrac{V}{30}=\\dfrac{4V}{3}$."},{"title":"Find the motorbike distance","body":"Its distance is $\\dfrac12(40)\\left(\\dfrac{4V}{3}\\right)+10\\left(\\dfrac{4V}{3}\\right)+\\dfrac12\\left(\\dfrac{4V}{3}+V\\right)(T-60)$."},{"title":"Simplify the motorbike distance","body":"This becomes $\\dfrac{80V}{3}+\\dfrac{40V}{3}+\\dfrac{7V}{6}(T-60)=40V+\\dfrac{7V}{6}(T-60)=\\dfrac{7VT}{6}-30V$."},{"title":"Equate the two distances","body":"At time $T$, the distances are equal: $V(T-15)=\\dfrac{7VT}{6}-30V$. Divide by $V$ to get $T-15=\\dfrac{7T}{6}-30$."},{"title":"Find T","body":"Multiplying by $6$ gives $6T-90=7T-180$, so $T=90$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2023_Oct_Q02","year":2023,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2023","qNo":2,"marks":10,"topic":"03_KinematicsGraphs","topicName":"Kinematics Graphs","primaryTopic":"03_KinematicsGraphs","primaryTopicName":"Kinematics Graphs","secondaryTopics":["04_ConstantAcceleration1D"],"secondaryTopicNames":["Constant Acceleration in 1D"],"topics":["03_KinematicsGraphs","04_ConstantAcceleration1D"],"topicNames":["Kinematics Graphs","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2023_Oct_Q02_M10_03_KinematicsGraphs.png","downloadName":"WME01-01_Y2023_Oct_Q02_M10_03_KinematicsGraphs.png","finalAnswer":"$(a)\\ v=18\\ \\mathrm{m\\,s^{-1}}$. $(b)$ Speed-time graph through $(0,8),(4,6),(10,6),(20,18)$. $(c)\\ AB=184\\ \\mathrm{m}$.","steps":[{"title":"Find the speed at t = 4","body":"From $0$ to $4$ s the acceleration is $-0.5\\ \\mathrm{m\\,s^{-2}}$. Therefore $w=8+(-0.5)(4)=6\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Find the final speed","body":"From $10$ to $20$ s the acceleration is $1.2\\ \\mathrm{m\\,s^{-2}}$, while the speed at $t=10$ is still $6$. Hence $v=6+1.2(10)=18\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Describe the speed-time graph","body":"The graph starts at $(0,8)$, falls linearly to $(4,6)$, stays horizontal to $(10,6)$, then rises linearly to $(20,18)$."},{"title":"Use area under the speed-time graph","body":"The distance is the area under the graph. From $0$ to $4$: $\\dfrac{8+6}{2}\\cdot4=28$. From $4$ to $10$: $6\\cdot6=36$. From $10$ to $20$: $\\dfrac{6+18}{2}\\cdot10=120$."},{"title":"Add the distances","body":"$AB=28+36+120=184\\ \\mathrm{m}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2024_Oct_Q04","year":2024,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2024","qNo":4,"marks":13,"topic":"03_KinematicsGraphs","topicName":"Kinematics Graphs","primaryTopic":"03_KinematicsGraphs","primaryTopicName":"Kinematics Graphs","secondaryTopics":["04_ConstantAcceleration1D"],"secondaryTopicNames":["Constant Acceleration in 1D"],"topics":["03_KinematicsGraphs","04_ConstantAcceleration1D"],"topicNames":["Kinematics Graphs","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2024_Oct_Q04_M13_03_KinematicsGraphs.png","downloadName":"WME01-01_Y2024_Oct_Q04_M13_03_KinematicsGraphs.png","finalAnswer":"$(a)\\ V=3.2.\\quad (b)\\ a=\\dfrac{16}{45}\\ \\mathrm{m\\,s^{-2}}\\approx0.36\\ \\mathrm{m\\,s^{-2}}.\\quad (d)\\ T=8\\ \\mathrm{s}$.","steps":[{"title":"Use the area under P graph","body":"For cyclist P, the distance from A to B is the area under the speed-time graph from $0$ to $42$. This is $\\dfrac12(9)V+33V=120$."},{"title":"Show V is 3.2","body":"$4.5V+33V=37.5V=120$, so $V=3.2\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Find P acceleration","body":"Between $t=0$ and $t=9$, P accelerates from $0$ to $3.2$. Hence $a=\\dfrac{3.2}{9}=\\dfrac{16}{45}=0.356\\ldots\\ \\mathrm{m\\,s^{-2}}$."},{"title":"Describe Q graph","body":"Cyclist Q starts at $t=6$ from rest, accelerates in a straight line for $T$ seconds to speed $3.6\\ \\mathrm{m\\,s^{-1}}$, then continues horizontally at $3.6\\ \\mathrm{m\\,s^{-1}}$ until $t=54$."},{"title":"Find P distance by t equals 54","body":"By $t=54$, P has travelled $\\dfrac12(9)(3.2)+45(3.2)=14.4+144=158.4\\ \\mathrm{m}$."},{"title":"Form Q distance in terms of T","body":"Q travels for $48$ seconds after starting at $t=6$. Her distance is $\\dfrac12T(3.6)+(48-T)(3.6)=172.8-1.8T$."},{"title":"Solve for T","body":"Q catches P at $t=54$, so $172.8-1.8T=158.4$. Thus $1.8T=14.4$ and $T=8$ s."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2025_Jan_Q02","year":2025,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2025","qNo":2,"marks":11,"topic":"03_KinematicsGraphs","topicName":"Kinematics Graphs","primaryTopic":"03_KinematicsGraphs","primaryTopicName":"Kinematics Graphs","secondaryTopics":["04_ConstantAcceleration1D"],"secondaryTopicNames":["Constant Acceleration in 1D"],"topics":["03_KinematicsGraphs","04_ConstantAcceleration1D"],"topicNames":["Kinematics Graphs","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2025_Jan_Q02_M11_03_KinematicsGraphs.png","downloadName":"WME01-01_Y2025_Jan_Q02_M11_03_KinematicsGraphs.png","finalAnswer":"$(b)(i)\\ T_1=\\dfrac{264}{V+5}.\\quad (b)(ii)\\ T_2=\\dfrac{272}{V}.\\quad (c)\\ V=17.\\quad (d)\\ \\text{deceleration}=\\dfrac{17}{16}=1.0625\\ \\mathrm{m\\,s^{-2}}$.","steps":[{"title":"Sketch the speed-time graph","body":"The graph starts at speed $5$ when $t=0$, rises linearly to speed $V$ at time $T_1$, then falls linearly to speed $0$ at time $T_1+T_2$."},{"title":"Use area from A to B","body":"The area under the first section is the distance $AB=132$. Thus $\\dfrac12(5+V)T_1=132$, so $T_1=\\dfrac{264}{V+5}$."},{"title":"Use area from B to C","body":"The second section is a triangle of height $V$ and base $T_2$. Since $BC=136$, $\\dfrac12VT_2=136$, so $T_2=\\dfrac{272}{V}$."},{"title":"Use the total time","body":"The whole journey takes $28$ s, so $\\dfrac{264}{V+5}+\\dfrac{272}{V}=28$."},{"title":"Solve for V","body":"Multiplying by $V(V+5)$ gives $264V+272(V+5)=28V(V+5)$. This simplifies to $7V^2-99V-340=0$, so $(V-17)(7V+20)=0$. Since speed is positive, $V=17$."},{"title":"Find the deceleration","body":"For the final section, $T_2=\\dfrac{272}{17}=16$ s. The speed falls from $17$ to $0$, so the deceleration is $\\dfrac{17}{16}=1.0625\\ \\mathrm{m\\,s^{-2}}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2025_Oct_Q06","year":2025,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2025","qNo":6,"marks":10,"topic":"03_KinematicsGraphs","topicName":"Kinematics Graphs","primaryTopic":"03_KinematicsGraphs","primaryTopicName":"Kinematics Graphs","secondaryTopics":["04_ConstantAcceleration1D"],"secondaryTopicNames":["Constant Acceleration in 1D"],"topics":["03_KinematicsGraphs","04_ConstantAcceleration1D"],"topicNames":["Kinematics Graphs","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2025_Oct_Q06_M10_03_KinematicsGraphs.png","downloadName":"WME01-01_Y2025_Oct_Q06_M10_03_KinematicsGraphs.png","finalAnswer":"$(a)(i)\\ a=3\\ \\mathrm{m\\,s^{-2}},\\ (ii)\\ \\text{deceleration}=6\\ \\mathrm{m\\,s^{-2}}.\\quad (b)\\ \\text{correct acceleration-time graph with levels }3,0,-6.\\quad (c)\\ \\text{distance}=825\\ \\mathrm{m}.\\quad (d)\\ A=4\\ \\mathrm{m\\,s^{-2}}$.","steps":[{"title":"Part (a): Find accelerations","body":"(i) Acceleration for $0 \\leq t \\leq 10$\n \n $\\text{Acceleration} = \\frac{\\Delta v}{\\Delta t} = \\text{gradient of v-t graph}$\n \n $a = \\frac{30 - 0}{10 - 0}$ $a = 3 \\text{ m s}^{-2}$\n \n \n \n \n \n (ii) Deceleration for $30 \\leq t \\leq 35$\n \n $a = \\frac{0 - 30}{35 - 30}$ $a = \\frac{-30}{5}$ $a = -6 \\text{ m s}^{-2}$\n \n Deceleration = $|-6| = 6$ m s$^{-2}$"},{"title":"Part (b): Sketch acceleration-time graph","body":"Analysis of each section:\n \n \n ; $0 \\leq t \\leq 10$: Constant acceleration = 3 m s$^{-2}$\n ; $10 < t \\leq 30$: Constant velocity, so acceleration = 0 m s$^{-2}$\n ; $30 < t \\leq 35$: Constant deceleration = $-6$ m s$^{-2}$"},{"title":"Part (c): Find distance travelled for $0 \\leq t \\leq 35$ - Calculate area under v-t graph","body":"$\\text{Distance} = \\text{Area under v-t graph}$\n \n The shape is a trapezium. We can split it into regions:\n \n \n Method 1: Trapezium formula\n \n $\\text{Area} = \\frac{1}{2}(a + b)h$\n \n Where the parallel sides are the time intervals and height is velocity.\n \n Better to calculate as sum of shapes:\n \n \n Method 2: Sum of triangle + rectangle + triangle\n \n $\\text{Area}_1 = \\frac{1}{2} \\times 10 \\times 30 = 150 \\text{ m}$ $\\text{Area}_2 = 20 \\times 30 = 600 \\text{ m}$ $\\text{Area}_3 = \\frac{1}{2} \\times 5 \\times 30 = 75 \\text{ m}$\n \n $\\text{Total distance} = 150 + 600 + 75$ $= 825 \\text{ m}$"},{"title":"Part (d): Find value of A - Distance travelled by car (0 to 20 seconds)","body":"Area under v-t graph from $t = 0$ to $t = 20$:\n \n $\\text{Distance}_{\\text{car}} = \\text{Triangle} + \\text{Rectangle}$ $= \\frac{1}{2}(10)(30) + (10)(30)$ $= 150 + 300$ $= 450 \\text{ m}$"},{"title":"Part (d): Find value of A - Distance travelled by motorcycle (5 to 20 seconds)","body":"Motorcycle starts at $t = 5$ with constant acceleration $A$.\n \n Time of travel: $20 - 5 = 15$ seconds\n \n $s = ut + \\frac{1}{2}at^2$\n \n $\\text{Distance}_{\\text{motorcycle}} = 0 + \\frac{1}{2}A(15)^2$ $= \\frac{225A}{2}$ $= 112.5A \\text{ m}$"},{"title":"Part (d): Find value of A - Set distances equal","body":"Motorcycle catches up with car when $t = 20$:\n \n $112.5A = 450$ $A = \\frac{450}{112.5}$ $A = 4 \\text{ m s}^{-2}$"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2026_Jan_Q02","year":2026,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2026","qNo":2,"marks":10,"topic":"03_KinematicsGraphs","topicName":"Kinematics Graphs","primaryTopic":"03_KinematicsGraphs","primaryTopicName":"Kinematics Graphs","secondaryTopics":["04_ConstantAcceleration1D"],"secondaryTopicNames":["Constant Acceleration in 1D"],"topics":["03_KinematicsGraphs","04_ConstantAcceleration1D"],"topicNames":["Kinematics Graphs","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2026_Jan_Q02_M10_03_KinematicsGraphs.png","downloadName":"WME01-01_Y2026_Jan_Q02_M10_03_KinematicsGraphs.png","finalAnswer":"$(a)\\ U=6.\\quad (b)\\ 12\\ \\mathrm{m}.\\quad (c)\\ 1.5\\ \\mathrm{m\\,s^{-2}}.\\quad (d)\\ 0.6\\ \\mathrm{m\\,s^{-2}}.\\quad (e)\\ a(t)=1.5,0,-0.6$ on the three intervals.","steps":[{"title":"Use area under the speed-time graph","body":"Distance is the area under a speed-time graph. The three areas are a triangle from $0$ to $12$, a rectangle from $12$ to $31$, and a trapezium from $31$ to $41$."},{"title":"Show that U is 6","body":"$\\dfrac12(12)(3U)+19(3U)+\\dfrac12(3U+2U)(10)=600$. This gives $18U+57U+25U=600$, so $100U=600$ and $U=6$."},{"title":"Find the distance to speed 6","body":"Since $U=6$, the final speed $6\\ \\mathrm{m\\,s^{-1}}$ occurs during the first section. The acceleration there is $\\dfrac{18-0}{12}=1.5\\ \\mathrm{m\\,s^{-2}}$, so the time to reach $6$ is $4$ s. The distance is $\\dfrac12(4)(6)=12\\ \\mathrm{m}$."},{"title":"Find the acceleration and deceleration","body":"From $0$ to $12$, $a=\\dfrac{18}{12}=1.5\\ \\mathrm{m\\,s^{-2}}$. From $31$ to $41$, the speed falls from $18$ to $12$, so the deceleration is $\\dfrac{18-12}{10}=0.6\\ \\mathrm{m\\,s^{-2}}$."},{"title":"Describe the acceleration-time graph","body":"The acceleration-time graph has three horizontal sections: $1.5$ from $0\\leq t\\leq 12$, $0$ from $12<t\\leq31$, and $-0.6$ from $31<t\\leq41$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2019_Oct_Q02","year":2019,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2019","qNo":2,"marks":9,"topic":"04_ConstantAcceleration1D","topicName":"Constant Acceleration in 1D","primaryTopic":"04_ConstantAcceleration1D","primaryTopicName":"Constant Acceleration in 1D","secondaryTopics":["09_MomentumImpulseCollisions","01_QuantitiesUnitsModelling"],"secondaryTopicNames":["Momentum, Impulse & Collisions","Quantities, Units & Modelling"],"topics":["04_ConstantAcceleration1D","09_MomentumImpulseCollisions","01_QuantitiesUnitsModelling"],"topicNames":["Constant Acceleration in 1D","Momentum, Impulse & Collisions","Quantities, Units & Modelling"],"image":"ial/wme01/questions/WME01-01_Y2019_Oct_Q02_M09_04_ConstantAcceleration1D.png","downloadName":"WME01-01_Y2019_Oct_Q02_M09_04_ConstantAcceleration1D.png","finalAnswer":"$(a)\\ 5.71\\ \\mathrm{s}\\text{ approximately}.\\quad (b)\\ 0.625\\ \\mathrm{m}$.","steps":[{"title":"Find the time to the first hit","body":"The ball is released from rest and falls $40$ m. Use $s=ut+\\dfrac12gt^2$: $40=\\dfrac12gt_1^2$. Thus $t_1=\\sqrt{\\dfrac{80}{g}}=\\dfrac{20}{7}$ s."},{"title":"Find the speed just before the first bounce","body":"Using $v^2=u^2+2gs$, $v_1^2=2g(40)$, so $v_1=28\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Use the rebound speed","body":"After the first bounce the speed is reduced by $50\\%$, so the upward speed is $14\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Find the time until the second hit","body":"The time to go up and return to the ground is $\\dfrac{2(14)}{g}=\\dfrac{20}{7}$ s."},{"title":"Find the total time","body":"Total time to the second hit is $\\dfrac{20}{7}+\\dfrac{20}{7}=\\dfrac{40}{7}=5.71$ s approximately."},{"title":"Find the speed after the third bounce","body":"After each bounce, the speed is halved. The upward speeds after the first, second and third bounces are $14$, $7$ and $3.5\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Find the height after the third bounce","body":"At the top after the third bounce, $0=(3.5)^2-2gh$. Therefore $h=\\dfrac{(3.5)^2}{2g}=0.625$ m."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2020_Jan_Q03","year":2020,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2020","qNo":3,"marks":11,"topic":"04_ConstantAcceleration1D","topicName":"Constant Acceleration in 1D","primaryTopic":"04_ConstantAcceleration1D","primaryTopicName":"Constant Acceleration in 1D","secondaryTopics":[],"secondaryTopicNames":[],"topics":["04_ConstantAcceleration1D"],"topicNames":["Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2020_Jan_Q03_M11_04_ConstantAcceleration1D.png","downloadName":"WME01-01_Y2020_Jan_Q03_M11_04_ConstantAcceleration1D.png","finalAnswer":"$(a)\\ H=\\dfrac{U^2}{2g}.\\quad (b)\\ t=\\dfrac{U}{g}.\\quad (c)$ The particles collide at $O$.","steps":[{"title":"Find the greatest height","body":"For P, at greatest height the speed is zero. Use $v^2=u^2+2as$ with $u=U$, $v=0$, $a=-g$ and $s=H$: $0=U^2-2gH$. Hence $H=\\dfrac{U^2}{2g}$."},{"title":"Start timing when Q is projected","body":"At this instant P is at height $H$ and has zero velocity. After $t$ seconds, P has fallen $\\dfrac12gt^2$, so its height above O is $H-\\dfrac12gt^2$."},{"title":"Write Q's height","body":"Q is projected upwards from O with speed $\\dfrac12U$, so its height after $t$ seconds is $\\dfrac12Ut-\\dfrac12gt^2$."},{"title":"Equate the heights","body":"At collision, $H-\\dfrac12gt^2=\\dfrac12Ut-\\dfrac12gt^2$. The gravity terms cancel, so $H=\\dfrac12Ut$."},{"title":"Find the time","body":"Substitute $H=\\dfrac{U^2}{2g}$: $\\dfrac{U^2}{2g}=\\dfrac12Ut$. Therefore $t=\\dfrac{U}{g}$."},{"title":"Find the collision position","body":"Substitute $t=\\dfrac{U}{g}$ into P's height: $H-\\dfrac12g\\left(\\dfrac{U}{g}\\right)^2=\\dfrac{U^2}{2g}-\\dfrac{U^2}{2g}=0$. Thus they collide at O."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_Jan_Q01","year":2021,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2021","qNo":1,"marks":6,"topic":"04_ConstantAcceleration1D","topicName":"Constant Acceleration in 1D","primaryTopic":"04_ConstantAcceleration1D","primaryTopicName":"Constant Acceleration in 1D","secondaryTopics":["01_QuantitiesUnitsModelling"],"secondaryTopicNames":["Quantities, Units & Modelling"],"topics":["04_ConstantAcceleration1D","01_QuantitiesUnitsModelling"],"topicNames":["Constant Acceleration in 1D","Quantities, Units & Modelling"],"image":"ial/wme01/questions/WME01-01_Y2021_Jan_Q01_M06_04_ConstantAcceleration1D.png","downloadName":"WME01-01_Y2021_Jan_Q01_M06_04_ConstantAcceleration1D.png","finalAnswer":"$(a)\\ 21.4\\ \\mathrm{m\\,s^{-1}}.\\quad (b)\\ 4.32\\ \\mathrm{s}\\ \\text{approximately}$.","steps":[{"title":"Find displacement for part a","body":"The stone starts $5$ m above the ground. When it is $2$ m above the ground, its displacement from O is $-3$ m."},{"title":"Use SUVAT for speed","body":"Taking upward as positive, $u=20$, $a=-9.8$ and $s=-3$. Use $v^2=u^2+2as$: $v^2=20^2+2(-9.8)(-3)=458.8$."},{"title":"State the speed","body":"$v=21.4\\ \\mathrm{m\\,s^{-1}}$ to 3 significant figures."},{"title":"Set up the ground equation","body":"At the ground, displacement from O is $-5$ m. Use $s=ut+\\dfrac12at^2$: $-5=20t-4.9t^2$."},{"title":"Solve for time","body":"$4.9t^2-20t-5=0$. The positive root is $t=4.3179\\ldots$, so the total time is $4.32\\ \\mathrm{s}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_MayJune_Q02","year":2021,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2021","qNo":2,"marks":8,"topic":"04_ConstantAcceleration1D","topicName":"Constant Acceleration in 1D","primaryTopic":"04_ConstantAcceleration1D","primaryTopicName":"Constant Acceleration in 1D","secondaryTopics":["01_QuantitiesUnitsModelling","07_NewtonsSecondLaw"],"secondaryTopicNames":["Quantities, Units & Modelling","Newton's Second Law"],"topics":["04_ConstantAcceleration1D","01_QuantitiesUnitsModelling","07_NewtonsSecondLaw"],"topicNames":["Constant Acceleration in 1D","Quantities, Units & Modelling","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2021_MayJune_Q02_M08_04_ConstantAcceleration1D.png","downloadName":"WME01-01_Y2021_MayJune_Q02_M08_04_ConstantAcceleration1D.png","finalAnswer":"$t=9.5\\ \\mathrm{s}$.","steps":[{"title":"Use the first three seconds","body":"Using $s=ut+\\dfrac12at^2$, the first $3$ seconds give $20=3u+\\dfrac12a(3^2)=3u+\\dfrac92a$."},{"title":"Use the fourth second","body":"The distance in the fourth second is $u+a(4-\\dfrac12)=u+\\dfrac72a$. Hence $10=u+\\dfrac72a$."},{"title":"Solve for a and u","body":"From $10=u+\\dfrac72a$, $u=10-\\dfrac72a$. Substitute into $20=3u+\\dfrac92a$: $20=30-\\dfrac{21}{2}a+\\dfrac92a=30-6a$. Thus $a=\\dfrac53$."},{"title":"Find u","body":"$u=10-\\dfrac72\\cdot\\dfrac53=10-\\dfrac{35}{6}=\\dfrac{25}{6}$."},{"title":"Use the speed at B","body":"At B, speed is $20$. Use $v=u+at$: $20=\\dfrac{25}{6}+\\dfrac53t$."},{"title":"Find the time","body":"$\\dfrac53t=20-\\dfrac{25}{6}=\\dfrac{95}{6}$, so $t=\\dfrac{95}{10}=9.5\\ \\mathrm{s}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_Oct_Q03","year":2021,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2021","qNo":3,"marks":10,"topic":"04_ConstantAcceleration1D","topicName":"Constant Acceleration in 1D","primaryTopic":"04_ConstantAcceleration1D","primaryTopicName":"Constant Acceleration in 1D","secondaryTopics":[],"secondaryTopicNames":[],"topics":["04_ConstantAcceleration1D"],"topicNames":["Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2021_Oct_Q03_M10_04_ConstantAcceleration1D.png","downloadName":"WME01-01_Y2021_Oct_Q03_M10_04_ConstantAcceleration1D.png","finalAnswer":"$(a)\\ 7\\ \\mathrm{m\\,s^{-1}}.\\quad (b)\\ t=\\dfrac{36}{13}\\ \\mathrm{s}\\approx2.77\\ \\mathrm{s}.\\quad (c)\\ t=\\dfrac{168}{65}\\ \\mathrm{s}\\approx2.58\\ \\mathrm{s}$.","steps":[{"title":"Use the first model","body":"From A to the sign, $u=25$, $a=-6$ and $s=48$. Use $v^2=u^2+2as$."},{"title":"Find the speed at the sign","body":"$v^2=25^2+2(-6)(48)=625-576=49$, so $v=7\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Second model: time to reach 13","body":"Use $v=u+at$: $13=25-6t$, so $t=2$ s to slow to $13\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Second model: distance while slowing","body":"Distance while slowing is $\\dfrac{25+13}{2}\\cdot2=38$ m."},{"title":"Second model: finish time","body":"The remaining distance is $48-38=10$ m at speed $13$. Total time $=2+\\dfrac{10}{13}=\\dfrac{36}{13}$ s."},{"title":"Third model: first 0.2 seconds","body":"The car first travels at $25\\ \\mathrm{m\\,s^{-1}}$ for $0.2$ s, covering $5$ m."},{"title":"Third model: slowing distance","body":"It then takes another $2$ s to slow from $25$ to $13$, covering $38$ m as before. Total covered before constant-speed part is $5+38=43$ m."},{"title":"Third model: finish time","body":"The remaining distance is $48-43=5$ m at speed $13$. Total time $=0.2+2+\\dfrac{5}{13}=\\dfrac{168}{65}$ s."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_Oct_Q06","year":2021,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2021","qNo":6,"marks":5,"topic":"04_ConstantAcceleration1D","topicName":"Constant Acceleration in 1D","primaryTopic":"04_ConstantAcceleration1D","primaryTopicName":"Constant Acceleration in 1D","secondaryTopics":["03_KinematicsGraphs"],"secondaryTopicNames":["Kinematics Graphs"],"topics":["04_ConstantAcceleration1D","03_KinematicsGraphs"],"topicNames":["Constant Acceleration in 1D","Kinematics Graphs"],"image":"ial/wme01/questions/WME01-01_Y2021_Oct_Q06_M05_04_ConstantAcceleration1D.png","downloadName":"WME01-01_Y2021_Oct_Q06_M05_04_ConstantAcceleration1D.png","finalAnswer":"$(a)\\ 24.5\\ \\mathrm{m\\,s^{-1}}.\\quad (b)\\ 68.6\\ \\mathrm{m}\\ \\text{approximately}$.","steps":[{"title":"Use the velocity-time graph","body":"The velocity becomes zero at $t=2.5$ s. Since acceleration is $-g=-9.8\\ \\mathrm{m\\,s^{-2}}$, the initial velocity is $u=9.8(2.5)$."},{"title":"Find the initial speed","body":"$u=24.5\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Use displacement to the ground","body":"From launch to $t=7$, the displacement is the area under the velocity-time graph. Algebraically, $s=ut-\\dfrac12gt^2$ with $t=7$."},{"title":"Calculate displacement","body":"$s=24.5(7)-\\dfrac12(9.8)(7^2)=171.5-240.1=-68.6$ m."},{"title":"State the height","body":"The negative sign shows the ground is below A, so the height of A above the ground is $68.6\\ \\mathrm{m}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_Jan_Q04","year":2022,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2022","qNo":4,"marks":8,"topic":"04_ConstantAcceleration1D","topicName":"Constant Acceleration in 1D","primaryTopic":"04_ConstantAcceleration1D","primaryTopicName":"Constant Acceleration in 1D","secondaryTopics":["03_KinematicsGraphs"],"secondaryTopicNames":["Kinematics Graphs"],"topics":["04_ConstantAcceleration1D","03_KinematicsGraphs"],"topicNames":["Constant Acceleration in 1D","Kinematics Graphs"],"image":"ial/wme01/questions/WME01-01_Y2022_Jan_Q04_M08_04_ConstantAcceleration1D.png","downloadName":"WME01-01_Y2022_Jan_Q04_M08_04_ConstantAcceleration1D.png","finalAnswer":"$(a)\\ T=5\\ \\mathrm{s}.\\quad (b)$ Speed-time graph is V-shaped, from speed $19.6$ at $t=0$ to $0$ at $t=2$, then to speed $29.4$ at $t=5$.","steps":[{"title":"Find the initial speed","body":"At the highest point B, the velocity is $0$ and $AB=19.6$ m. Use $v^2=u^2+2as$ upward: $0=u^2-2g(19.6)$."},{"title":"Calculate u","body":"$u^2=2(9.8)(19.6)=384.16$, so $u=19.6\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Use displacement to the ground","body":"From A to the ground, taking upward as positive, displacement is $-24.5$ m. Use $s=ut+\\dfrac12at^2$: $-24.5=19.6T-4.9T^2$."},{"title":"Solve for T","body":"$4.9T^2-19.6T-24.5=0$. Divide by $4.9$: $T^2-4T-5=0$, so $(T-5)(T+1)=0$. The positive time is $T=5$ s."},{"title":"Describe the speed-time graph","body":"The speed starts at $19.6$, decreases linearly to $0$ at $t=2$, then increases linearly until the ball hits the ground at $t=5$. The final speed is $29.4$, so the second line is longer than the first."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_MayJune_Q02","year":2022,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2022","qNo":2,"marks":7,"topic":"04_ConstantAcceleration1D","topicName":"Constant Acceleration in 1D","primaryTopic":"04_ConstantAcceleration1D","primaryTopicName":"Constant Acceleration in 1D","secondaryTopics":[],"secondaryTopicNames":[],"topics":["04_ConstantAcceleration1D"],"topicNames":["Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2022_MayJune_Q02_M07_04_ConstantAcceleration1D.png","downloadName":"WME01-01_Y2022_MayJune_Q02_M07_04_ConstantAcceleration1D.png","finalAnswer":"$(a)\\ a=1.2\\ \\mathrm{m\\,s^{-2}}.\\quad (b)\\ 21.4\\ \\mathrm{m}$.","steps":[{"title":"Find the speed at P","body":"Let the speed at P be $u$. Over the $10$ seconds from P to Q, the speed changes uniformly from $u$ to $28$, and the distance is $220$ m."},{"title":"Use average speed","body":"$220=\\dfrac{u+28}{2}\\cdot10=5(u+28)$. Hence $u+28=44$ and $u=16\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Find the acceleration","body":"Use $v=u+at$: $28=16+10a$, so $a=1.2\\ \\mathrm{m\\,s^{-2}}$."},{"title":"Write the distance from P after t seconds","body":"$s=16t+\\dfrac12(1.2)t^2=16t+0.6t^2$."},{"title":"Find the distance in the fifth second","body":"The fifth second is from $t=4$ to $t=5$. $s(5)=16(5)+0.6(25)=95$ and $s(4)=16(4)+0.6(16)=73.6$."},{"title":"Subtract","body":"Distance in the fifth second $=95-73.6=21.4\\ \\mathrm{m}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_Oct_Q05","year":2022,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2022","qNo":5,"marks":9,"topic":"04_ConstantAcceleration1D","topicName":"Constant Acceleration in 1D","primaryTopic":"04_ConstantAcceleration1D","primaryTopicName":"Constant Acceleration in 1D","secondaryTopics":["03_KinematicsGraphs"],"secondaryTopicNames":["Kinematics Graphs"],"topics":["04_ConstantAcceleration1D","03_KinematicsGraphs"],"topicNames":["Constant Acceleration in 1D","Kinematics Graphs"],"image":"ial/wme01/questions/WME01-01_Y2022_Oct_Q05_M09_04_ConstantAcceleration1D.png","downloadName":"WME01-01_Y2022_Oct_Q05_M09_04_ConstantAcceleration1D.png","finalAnswer":"$(a)\\ 22.1\\ \\mathrm{m}\\ \\text{approximately}.\\quad (b)\\ 0.606\\ \\mathrm{s}\\ \\text{approximately}.\\quad (c)$ V-shaped speed-time graph through $(0,29.4)$ and $(3,0)$, ending above $29.4$.","steps":[{"title":"Find one side of the slow-speed interval","body":"The speed is less than $14.7\\ \\mathrm{m\\,s^{-1}}$ near the highest point. From speed $14.7$ to speed $0$, use $v^2=u^2+2as$: $0=14.7^2-2gs$."},{"title":"Find the total distance","body":"This gives $s=11.025$ m on the way up. The same distance occurs on the way down before the speed reaches $14.7$ again, so the total distance is $2s=22.05\\ \\mathrm{m}$, about $22.1\\ \\mathrm{m}$."},{"title":"Interpret speed greater than 29.4","body":"The ball has speed $29.4$ again when it passes A on the way down. It is faster than $29.4$ only after passing A downward until it hits the ground."},{"title":"Find that time","body":"From A to the ground, taking downward as positive, $19.6=29.4t+\\dfrac12gt^2$."},{"title":"Solve the time equation","body":"$19.6=29.4t+4.9t^2$, giving the positive root $t=0.606\\ldots\\ \\mathrm{s}$."},{"title":"Describe the speed-time graph","body":"The graph starts at speed $29.4$ when $t=0$, decreases linearly to speed $0$ at $t=3$, then increases linearly until the ball hits the ground. The final speed is greater than $29.4$, so the right-hand arm ends above the starting height on the speed axis."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2023_Jan_Q05","year":2023,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2023","qNo":5,"marks":9,"topic":"04_ConstantAcceleration1D","topicName":"Constant Acceleration in 1D","primaryTopic":"04_ConstantAcceleration1D","primaryTopicName":"Constant Acceleration in 1D","secondaryTopics":["01_QuantitiesUnitsModelling","07_NewtonsSecondLaw"],"secondaryTopicNames":["Quantities, Units & Modelling","Newton's Second Law"],"topics":["04_ConstantAcceleration1D","01_QuantitiesUnitsModelling","07_NewtonsSecondLaw"],"topicNames":["Constant Acceleration in 1D","Quantities, Units & Modelling","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2023_Jan_Q05_M09_04_ConstantAcceleration1D.png","downloadName":"WME01-01_Y2023_Jan_Q05_M09_04_ConstantAcceleration1D.png","finalAnswer":"$(a)\\ x=3u.\\quad (b)\\ u=9.\\quad (c)\\ 201\\ \\mathrm{m}$.","steps":[{"title":"Use average speed from P to Q","body":"From P to Q, the speed changes uniformly from $u$ to $2u$ over $12$ s. The average speed is $\\dfrac{u+2u}{2}=\\dfrac{3u}{2}$."},{"title":"Show x = 3u","body":"Distance $PQ=6x$, so $6x=\\dfrac{3u}{2}\\cdot12=18u$. Hence $x=3u$."},{"title":"Use Q to R","body":"The distance $QR=5x=15u$. The speed changes from $2u$ to $3u$ with acceleration $1.5\\ \\mathrm{m\\,s^{-2}}$."},{"title":"Find u","body":"Use $v^2=u^2+2as$: $(3u)^2=(2u)^2+2(1.5)(15u)$. Thus $9u^2=4u^2+45u$, so $5u^2=45u$ and $u=9$."},{"title":"Find the first 12 seconds distance","body":"In the first $12$ seconds, the distance is $PQ=6x=18u=18(9)=162$ m."},{"title":"Find the next 2 seconds distance","body":"From $t=12$ to $t=14$, the vehicle starts this part at speed $2u=18$ and accelerates at $1.5$. Distance $=18(2)+\\dfrac12(1.5)(2^2)=36+3=39$ m."},{"title":"Add the distances","body":"Total distance in the first $14$ seconds is $162+39=201\\ \\mathrm{m}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2023_MayJune_Q03","year":2023,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2023","qNo":3,"marks":8,"topic":"04_ConstantAcceleration1D","topicName":"Constant Acceleration in 1D","primaryTopic":"04_ConstantAcceleration1D","primaryTopicName":"Constant Acceleration in 1D","secondaryTopics":["07_NewtonsSecondLaw"],"secondaryTopicNames":["Newton's Second Law"],"topics":["04_ConstantAcceleration1D","07_NewtonsSecondLaw"],"topicNames":["Constant Acceleration in 1D","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2023_MayJune_Q03_M08_04_ConstantAcceleration1D.png","downloadName":"WME01-01_Y2023_MayJune_Q03_M08_04_ConstantAcceleration1D.png","finalAnswer":"$(a)\\ t=0.553\\ \\mathrm{s}\\ \\text{approximately}.\\quad (b)\\ R=0.293\\ \\mathrm{N}$.","steps":[{"title":"Use free fall for student A","body":"From rest, with downward displacement $1.5$ m and acceleration $g$, use $s=ut+\\dfrac12at^2$."},{"title":"Find the time","body":"$1.5=0+\\dfrac12(9.8)t^2$, so $t^2=\\dfrac{3}{9.8}$ and $t=0.553\\ldots\\ \\mathrm{s}$."},{"title":"Find the acceleration in student B's model","body":"Now the time is $0.6$ s. Again starting from rest, $1.5=\\dfrac12a(0.6)^2=0.18a$, so $a=8.333\\ldots\\ \\mathrm{m\\,s^{-2}}$ downward."},{"title":"Apply Newtons second law","body":"Taking downward as positive, weight is $0.2g$ and resistance $R$ acts upward. Therefore $0.2g-R=0.2a$."},{"title":"Find R","body":"$1.96-R=0.2(8.333\\ldots)=1.666\\ldots$, so $R=0.293\\ldots\\ \\mathrm{N}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2024_Jan_Q03","year":2024,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2024","qNo":3,"marks":10,"topic":"04_ConstantAcceleration1D","topicName":"Constant Acceleration in 1D","primaryTopic":"04_ConstantAcceleration1D","primaryTopicName":"Constant Acceleration in 1D","secondaryTopics":["07_NewtonsSecondLaw"],"secondaryTopicNames":["Newton's Second Law"],"topics":["04_ConstantAcceleration1D","07_NewtonsSecondLaw"],"topicNames":["Constant Acceleration in 1D","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2024_Jan_Q03_M10_04_ConstantAcceleration1D.png","downloadName":"WME01-01_Y2024_Jan_Q03_M10_04_ConstantAcceleration1D.png","finalAnswer":"$(a)\\ u=12.\\quad (b)\\ t=5\\sqrt{29}-15\\approx11.9\\ \\mathrm{s}.\\quad (c)\\ \\text{driving force}=1220\\ \\mathrm{N}$.","steps":[{"title":"Use average speed from A to B","body":"With constant acceleration, distance equals average speed times time. So $400=\\dfrac{u+28}{2}\\cdot20$."},{"title":"Show u is 12","body":"$400=10(u+28)$, so $u+28=40$ and $u=12$."},{"title":"Find the acceleration","body":"Use $v=u+at$: $28=12+20a$, hence $a=0.8\\ \\mathrm{m\\,s^{-2}}$."},{"title":"Use the midpoint distance","body":"The midpoint of AB is $200$ m from A. Use $s=ut+\\dfrac12at^2$: $200=12t+\\dfrac12(0.8)t^2$."},{"title":"Solve for the time to the midpoint","body":"$200=12t+0.4t^2$. The positive solution is $t=5\\sqrt{29}-15=11.9258\\ldots\\ \\mathrm{s}$."},{"title":"Use Newtons second law for the van","body":"Let the driving force be $D$. The resultant forward force is $D-260$. Since $ma=1200(0.8)=960$, $D-260=960$."},{"title":"Find the driving force","body":"$D=1220\\ \\mathrm{N}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2024_Jan_Q06","year":2024,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2024","qNo":6,"marks":12,"topic":"04_ConstantAcceleration1D","topicName":"Constant Acceleration in 1D","primaryTopic":"04_ConstantAcceleration1D","primaryTopicName":"Constant Acceleration in 1D","secondaryTopics":["09_MomentumImpulseCollisions","03_KinematicsGraphs"],"secondaryTopicNames":["Momentum, Impulse & Collisions","Kinematics Graphs"],"topics":["04_ConstantAcceleration1D","09_MomentumImpulseCollisions","03_KinematicsGraphs"],"topicNames":["Constant Acceleration in 1D","Momentum, Impulse & Collisions","Kinematics Graphs"],"image":"ial/wme01/questions/WME01-01_Y2024_Jan_Q06_M12_04_ConstantAcceleration1D.png","downloadName":"WME01-01_Y2024_Jan_Q06_M12_04_ConstantAcceleration1D.png","finalAnswer":"$(a)\\ V=25\\ \\mathrm{m\\,s^{-1}}.\\quad (b)\\ t=5\\ \\mathrm{s}.\\quad (c)\\ 4.0\\ \\mathrm{s}\\ \\text{approximately}$. (d) Speed-time graph is V-shaped, from speed 24 to 0, then to speed 25 at t=5.","steps":[{"title":"Find the impact speed","body":"Take upward as positive from A. At B, the displacement is $-2.5$ m, with $u=24$ and $a=-9.8$. Use $v^2=u^2+2as$: $V^2=24^2+2(-9.8)(-2.5)=625$."},{"title":"State V","body":"$V=25\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Find the time to reach B","body":"The velocity at B is $-25\\ \\mathrm{m\\,s^{-1}}$. Using $v=u+at$, $-25=24-9.8t$, so $t=5\\ \\mathrm{s}$."},{"title":"Set up the height C equation","body":"C is $10$ m above A. The particle is above C between the two times when $s=10$: $10=24t-4.9t^2$."},{"title":"Solve for the two crossing times","body":"$4.9t^2-24t+10=0$, giving $t=0.459\\ldots$ and $t=4.438\\ldots$."},{"title":"Find the time above C","body":"The length of time above C is $4.438\\ldots-0.459\\ldots=3.98\\ldots\\ \\mathrm{s}$, about $4.0\\ \\mathrm{s}$."},{"title":"Describe the speed-time graph","body":"The graph starts at speed $24$, decreases linearly to $0$ at the highest point, then increases linearly to speed $25$ at $t=5$. It is a V-shaped speed-time graph."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2024_MayJune_Q05","year":2024,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2024","qNo":5,"marks":14,"topic":"04_ConstantAcceleration1D","topicName":"Constant Acceleration in 1D","primaryTopic":"04_ConstantAcceleration1D","primaryTopicName":"Constant Acceleration in 1D","secondaryTopics":["07_NewtonsSecondLaw"],"secondaryTopicNames":["Newton's Second Law"],"topics":["04_ConstantAcceleration1D","07_NewtonsSecondLaw"],"topicNames":["Constant Acceleration in 1D","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2024_MayJune_Q05_M14_04_ConstantAcceleration1D.png","downloadName":"WME01-01_Y2024_MayJune_Q05_M14_04_ConstantAcceleration1D.png","finalAnswer":"$(a)\\ 122.5\\ \\mathrm{m}\\ \\text{or}\\ 123\\ \\mathrm{m}.\\quad (b)\\ 4\\ \\mathrm{m\\,s^{-1}}.\\quad (c)\\ 20\\ \\mathrm{s}$. (d) Speed-time graph: straight line from $(0,0)$ to $(5,49)$ then straight line down to $(20,4)$.","steps":[{"title":"Find the first distance","body":"For the first 5 seconds, P falls freely from rest. Using $s=ut+\\dfrac12at^2$, $s=0+\\dfrac12(9.8)(5^2)=122.5\\ \\mathrm{m}$."},{"title":"Find the speed when the parachute opens","body":"After 5 seconds of free fall, $v=0+9.8(5)=49\\ \\mathrm{m\\,s^{-1}}$ downward."},{"title":"Find the new acceleration","body":"After the parachute opens, weight is $250g=2450$ N downward and resistance is $3200$ N upward. Taking downward as positive, the resultant is $2450-3200=-750$ N, so $a=\\dfrac{-750}{250}=-3\\ \\mathrm{m\\,s^{-2}}$."},{"title":"Use the remaining distance","body":"The remaining distance is $520-122.5=397.5$ m. Using $v^2=u^2+2as$: $v^2=49^2+2(-3)(397.5)=16$."},{"title":"Find the landing speed","body":"$v=4\\ \\mathrm{m\\,s^{-1}}$, so P lands with speed $4\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Find the time after the parachute opens","body":"Using $v=u+at$, $4=49-3t$, so $t=15$ s after the parachute opens."},{"title":"Find the total time and describe the graph","body":"The total time is $5+15=20$ s. The speed-time graph rises linearly from $0$ to $49$ over the first 5 s, then falls linearly to $4$ at $t=20$; it does not meet the time-axis."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2024_Oct_Q07","year":2024,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2024","qNo":7,"marks":11,"topic":"04_ConstantAcceleration1D","topicName":"Constant Acceleration in 1D","primaryTopic":"04_ConstantAcceleration1D","primaryTopicName":"Constant Acceleration in 1D","secondaryTopics":["09_MomentumImpulseCollisions"],"secondaryTopicNames":["Momentum, Impulse & Collisions"],"topics":["04_ConstantAcceleration1D","09_MomentumImpulseCollisions"],"topicNames":["Constant Acceleration in 1D","Momentum, Impulse & Collisions"],"image":"ial/wme01/questions/WME01-01_Y2024_Oct_Q07_M11_04_ConstantAcceleration1D.png","downloadName":"WME01-01_Y2024_Oct_Q07_M11_04_ConstantAcceleration1D.png","finalAnswer":"$(a)\\ T_1=1.63\\ \\mathrm{s}.\\quad (b)\\ I=1.43\\ \\mathrm{N\\,s}.\\quad (c)\\ T_2=1.46\\ \\mathrm{s}$.","steps":[{"title":"Find the first flight time","body":"For ball A, take upward as positive. Returning to the ground gives $0=8T_1-4.9T_1^2$. The non-zero solution is $T_1=\\dfrac{8}{4.9}=1.63\\ \\mathrm{s}$ to 3 significant figures."},{"title":"Find the rebound speed","body":"After impact, A rebounds to a maximum height of $2$ m. At the top, $v=0$, so $0=u^2-2g(2)$. Hence $u=\\sqrt{4g}=6.261\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Use impulse as change in momentum","body":"Just before the first impact, A has velocity $-8\\ \\mathrm{m\\,s^{-1}}$. Just after impact, it has velocity $+6.261\\ \\mathrm{m\\,s^{-1}}$. With mass $0.1$ kg, $I=0.1[6.261-(-8)]$."},{"title":"Calculate the impulse","body":"$I=1.426\\ldots\\ \\mathrm{N\\,s}$, so the impulse is $1.43\\ \\mathrm{N\\,s}$ to 3 significant figures."},{"title":"Write the height of A before first impact","body":"For the first meeting with B, A is still in its first flight. Its height at time $T_2$ is $h_A=8T_2-4.9T_2^2$."},{"title":"Write the height of B","body":"B starts at time $t=1$, so at time $T_2$ it has been moving for $T_2-1$ seconds. Its height is $h_B=5(T_2-1)-4.9(T_2-1)^2$."},{"title":"Set the heights equal","body":"$8T_2-4.9T_2^2=5(T_2-1)-4.9(T_2-1)^2$. Expanding and simplifying gives $6.8T_2=9.9$."},{"title":"Find T2","body":"$T_2=\\dfrac{9.9}{6.8}=1.456\\ldots$, so $T_2=1.46\\ \\mathrm{s}$ to 3 significant figures."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2025_MayJune_Q03","year":2025,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2025","qNo":3,"marks":8,"topic":"04_ConstantAcceleration1D","topicName":"Constant Acceleration in 1D","primaryTopic":"04_ConstantAcceleration1D","primaryTopicName":"Constant Acceleration in 1D","secondaryTopics":[],"secondaryTopicNames":[],"topics":["04_ConstantAcceleration1D"],"topicNames":["Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2025_MayJune_Q03_M08_04_ConstantAcceleration1D.png","downloadName":"WME01-01_Y2025_MayJune_Q03_M08_04_ConstantAcceleration1D.png","finalAnswer":"$(a)\\ U=16.6\\ \\mathrm{m\\,s^{-1}}$ (about $17\\ \\mathrm{m\\,s^{-1}}$ to 2 s.f.). $(b)\\ \\text{speed}=22.6\\ \\mathrm{m\\,s^{-1}}$. (c) Correct V-shaped velocity-time graph with the labelled values from the working.","steps":[{"title":"Part (a): Find the value of U - Identify SUVAT variables","body":"Taking upward as positive:\n \n ; $u = U$ m s$^{-1}$ (unknown, upward)\n ; $s = -12$ m (displacement from A to B, downward)\n ; $t = 4$ seconds\n ; $a = -9.8$ m s$^{-2}$ (gravity, downward)"},{"title":"Part (a): Find the value of U - Apply $s = ut + \\frac{1}{2}at^2$","body":"$s = ut + \\frac{1}{2}at^2$\n \n $-12 = U(4) + \\frac{1}{2}(-9.8)(4)^2$ $-12 = 4U + \\frac{1}{2}(-9.8)(16)$ $-12 = 4U - 78.4$ $4U = -12 + 78.4$ $4U = 66.4$ $U = 16.6 \\text{ m s}^{-1}$"},{"title":"Part (b): Find speed as particle hits ground - Use SUVAT to find velocity at B","body":"$v^2 = u^2 + 2as$\n \n $v^2 = (16.6)^2 + 2(-9.8)(-12)$ $v^2 = 275.56 + 235.2$ $v^2 = 510.76$ $v = \\pm 22.6$\n \n Since particle is moving downward at B, $v = -22.6$ m s$^{-1}$ (negative)"},{"title":"Part (b): Find speed as particle hits ground - Find speed","body":"Speed $=|v|=22.6\\ \\mathrm{m\\,s^{-1}}$, or about $23\\ \\mathrm{m\\,s^{-1}}$ to 2 significant figures."},{"title":"Part (c): Sketch speed-time graph - Analyze the motion","body":"The particle:\n \n ; Starts at A with speed $U = 16.6$ m s$^{-1}$ upward\n ; Decelerates (speed decreases) as it goes up\n ; Reaches maximum height when speed = 0\n ; Accelerates (speed increases) as it falls down\n ; Hits ground at B with speed 22.6 m s$^{-1}$\n \n \n Time to reach maximum height:\n $v = u + at$ $0 = 16.6 - 9.8t$ $t = \\frac{16.6}{9.8} = 1.69 \\text{ seconds}$"},{"title":"Part (c): Sketch speed-time graph - Sketch the graph","body":"Key Features:\n \n ; V-shaped graph (straight lines due to constant acceleration)\n ; First line: negative gradient (speed decreasing)\n ; Second line: positive gradient (speed increasing)\n ; Vertex on horizontal axis (speed = 0 at max height)\n ; Second line is longer and steeper (falls from greater height)"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2025_Oct_Q04","year":2025,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2025","qNo":4,"marks":9,"topic":"05_ConstantAcceleration2D","topicName":"Constant Acceleration in 2D","primaryTopic":"05_ConstantAcceleration2D","primaryTopicName":"Constant Acceleration in 2D","secondaryTopics":["04_ConstantAcceleration1D"],"secondaryTopicNames":["Constant Acceleration in 1D"],"topics":["05_ConstantAcceleration2D","04_ConstantAcceleration1D"],"topicNames":["Constant Acceleration in 2D","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2025_Oct_Q04_M09_05_ConstantAcceleration2D.png","downloadName":"WME01-01_Y2025_Oct_Q04_M09_05_ConstantAcceleration2D.png","finalAnswer":"$(a)\\ \\text{maximum height above A}=1.28\\ \\mathrm{m}.\\quad (b)\\ T=1.86\\ \\mathrm{s}.\\quad (c)\\ \\text{speed of P}=13.2\\ \\mathrm{m\\,s^{-1}}$.","steps":[{"title":"Part (a): Find the greatest height above A reached by P - Identify the SUVAT variables","body":"At maximum height, velocity = 0\n \n \n ; $u = 5$ m s$^{-1}$ (initial velocity)\n ; $v = 0$ m s$^{-1}$ (at maximum height)\n ; $a = -9.8$ m s$^{-2}$ (gravity, downward)\n ; $s = ?$ (displacement above A)"},{"title":"Part (a): Find the greatest height above A reached by P - Apply $v^2 = u^2 + 2as$","body":"$v^2 = u^2 + 2as$\n \n $0^2 = 5^2 + 2(-9.8)s$ $0 = 25 - 19.6s$ $19.6s = 25$ $s = \\frac{25}{19.6}$ $s = 1.276...$ $s = 1.28 \\text{ m (3 s.f.)}$"},{"title":"Part (b): Find the value of T - Position of P at time $t$","body":"Taking upward as positive, with origin at ground level:\n \n $s = s_0 + ut + \\frac{1}{2}at^2$\n \n For P (starting at A, 10 m above ground):\n $s_P = 10 + 5t + \\frac{1}{2}(-9.8)t^2$ $s_P = 10 + 5t - 4.9t^2$"},{"title":"Part (b): Find the value of T - Position of Q at time $t$","body":"Q starts at $t = 1$, so Q has been moving for $(t-1)$ seconds:\n \n For Q (starting at B, ground level):\n $s_Q = 0 + 7(t-1) + \\frac{1}{2}(-9.8)(t-1)^2$ $s_Q = 7(t-1) - 4.9(t-1)^2$ $s_Q = 7t - 7 - 4.9(t^2 - 2t + 1)$ $s_Q = 7t - 7 - 4.9t^2 + 9.8t - 4.9$ $s_Q = -4.9t^2 + 16.8t - 11.9$"},{"title":"Part (b): Find the value of T - Set $s_P = s_Q$ at collision (when $t = T$)","body":"$10 + 5T - 4.9T^2 = -4.9T^2 + 16.8T - 11.9$ $10 + 5T = 16.8T - 11.9$ $10 + 11.9 = 16.8T - 5T$ $21.9 = 11.8T$ $T = \\frac{21.9}{11.8}$ $T = 1.855...$ $T = 1.86 \\text{ s (3 s.f.)}$"},{"title":"Part (c): Find the speed of P immediately before collision - Find velocity of P at time $T = 1.86$ s","body":"$v = u + at$\n \n For particle P:\n \n ; $u = 5$ m s$^{-1}$\n ; $a = -9.8$ m s$^{-2}$\n ; $t = 1.86$ s\n \n \n $v_P = 5 + (-9.8)(1.86)$ $= 5 - 18.228$ $= -13.228...$ $= -13.2 \\text{ m s}^{-1}$\n \n The negative sign indicates P is moving downward."},{"title":"Part (c): Find the speed of P immediately before collision - Find speed","body":"Speed = $|v|$\n \n $\\text{Speed} = |-13.2|$ $= 13.2 \\text{ m s}^{-1}$"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2020_Jan_Q04","year":2020,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2020","qNo":4,"marks":10,"topic":"06_Forces","topicName":"Forces","primaryTopic":"06_Forces","primaryTopicName":"Forces","secondaryTopics":["07_NewtonsSecondLaw","01_QuantitiesUnitsModelling"],"secondaryTopicNames":["Newton's Second Law","Quantities, Units & Modelling"],"topics":["06_Forces","07_NewtonsSecondLaw","01_QuantitiesUnitsModelling"],"topicNames":["Forces","Newton's Second Law","Quantities, Units & Modelling"],"image":"ial/wme01/questions/WME01-01_Y2020_Jan_Q04_M10_06_Forces.png","downloadName":"WME01-01_Y2020_Jan_Q04_M10_06_Forces.png","finalAnswer":"$(a)\\ T=\\dfrac{3mg}{2\\sin\\beta}.\\quad (b)\\ R=\\dfrac52mg.\\quad (c)\\ \\tan\\beta=\\dfrac34$.","steps":[{"title":"Resolve forces on C","body":"The two tensions are equal and symmetric. Their vertical components support the weight of C, so $2T\\sin\\beta=3mg$. Hence $T=\\dfrac{3mg}{2\\sin\\beta}$."},{"title":"Resolve vertically for ring A","body":"For ring A, the normal reaction balances its own weight and the downward vertical component of the string tension: $R=mg+T\\sin\\beta$."},{"title":"Find the normal reaction","body":"From $2T\\sin\\beta=3mg$, we have $T\\sin\\beta=\\dfrac32mg$. Therefore $R=mg+\\dfrac32mg=\\dfrac52mg$."},{"title":"Use limiting friction","body":"The rings are just about to slide towards each other, so friction is limiting. With $\\mu=\\dfrac45$, $F=\\mu R=\\dfrac45\\cdot\\dfrac52mg=2mg$."},{"title":"Resolve horizontally for a ring","body":"The horizontal component of the tension is balanced by friction: $T\\cos\\beta=F=2mg$."},{"title":"Find tan beta","body":"Substitute $T=\\dfrac{3mg}{2\\sin\\beta}$: $\\dfrac{3mg}{2\\sin\\beta}\\cos\\beta=2mg$. Hence $\\dfrac32\\cot\\beta=2$, so $\\cot\\beta=\\dfrac43$ and $\\tan\\beta=\\dfrac34$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_Jan_Q03","year":2021,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2021","qNo":3,"marks":9,"topic":"06_Forces","topicName":"Forces","primaryTopic":"06_Forces","primaryTopicName":"Forces","secondaryTopics":["01_QuantitiesUnitsModelling","04_ConstantAcceleration1D"],"secondaryTopicNames":["Quantities, Units & Modelling","Constant Acceleration in 1D"],"topics":["06_Forces","01_QuantitiesUnitsModelling","04_ConstantAcceleration1D"],"topicNames":["Forces","Quantities, Units & Modelling","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2021_Jan_Q03_M09_06_Forces.png","downloadName":"WME01-01_Y2021_Jan_Q03_M09_06_Forces.png","finalAnswer":"$T=192\\ \\mathrm{N}\\ \\text{approximately}$.","steps":[{"title":"Resolve vertically","body":"For vertical equilibrium, $R+200\\sin15^\\circ+T\\sin25^\\circ=20g$."},{"title":"Resolve horizontally","body":"For the smallest $T$, friction is limiting and balances the remaining horizontal tendency. Horizontally, $200\\cos15^\\circ-T\\cos25^\\circ-F=0$."},{"title":"Use limiting friction","body":"$F=0.3R$."},{"title":"Eliminate R and F","body":"From the vertical equation, $R=20g-200\\sin15^\\circ-T\\sin25^\\circ$. Substitute into $F=0.3R$ and then into the horizontal equation."},{"title":"Solve for T","body":"$200\\cos15^\\circ-T\\cos25^\\circ-0.3(20g-200\\sin15^\\circ-T\\sin25^\\circ)=0$. Solving gives $T=192.3\\ldots\\ \\mathrm{N}$, so the smallest value is about $192\\ \\mathrm{N}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_Oct_Q05","year":2021,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2021","qNo":5,"marks":10,"topic":"06_Forces","topicName":"Forces","primaryTopic":"06_Forces","primaryTopicName":"Forces","secondaryTopics":["07_NewtonsSecondLaw","01_QuantitiesUnitsModelling","04_ConstantAcceleration1D"],"secondaryTopicNames":["Newton's Second Law","Quantities, Units & Modelling","Constant Acceleration in 1D"],"topics":["06_Forces","07_NewtonsSecondLaw","01_QuantitiesUnitsModelling","04_ConstantAcceleration1D"],"topicNames":["Forces","Newton's Second Law","Quantities, Units & Modelling","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2021_Oct_Q05_M10_06_Forces.png","downloadName":"WME01-01_Y2021_Oct_Q05_M10_06_Forces.png","finalAnswer":"$(a)\\ F=0.46\\ \\mathrm{N}\\ \\text{upwards}.\\quad (b)\\ \\mu=0.35$.","steps":[{"title":"Use the trig ratios","body":"Since $\\tan\\alpha=\\dfrac43$, $\\sin\\alpha=\\dfrac45$ and $\\cos\\alpha=\\dfrac35$."},{"title":"Resolve vertically when T = 2.5","body":"The vertical component of the thrust is $2.5\\cos\\alpha=2.5\\cdot\\dfrac35=1.5$ N upward. The weight is $0.2g=1.96$ N downward."},{"title":"Find friction and direction","body":"For equilibrium, friction must supply the missing upward force: $F=1.96-1.5=0.46\\ \\mathrm{N}$. So friction acts upwards."},{"title":"Use greatest T","body":"When $T=6.125$, the vertical component of the thrust is larger than the weight, so friction acts downward at the limiting value."},{"title":"Find normal reaction","body":"The normal reaction is the horizontal component of the thrust: $R=6.125\\sin\\alpha=6.125\\cdot\\dfrac45=4.9\\ \\mathrm{N}$."},{"title":"Find limiting friction","body":"Vertical equilibrium gives $0.2g+F=6.125\\cos\\alpha$. Thus $1.96+F=6.125\\cdot\\dfrac35=3.675$, so $F=1.715$ N."},{"title":"Find mu","body":"$F=\\mu R$, so $\\mu=\\dfrac{1.715}{4.9}=0.35$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_Jan_Q01","year":2022,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2022","qNo":1,"marks":6,"topic":"06_Forces","topicName":"Forces","primaryTopic":"06_Forces","primaryTopicName":"Forces","secondaryTopics":["01_QuantitiesUnitsModelling","04_ConstantAcceleration1D"],"secondaryTopicNames":["Quantities, Units & Modelling","Constant Acceleration in 1D"],"topics":["06_Forces","01_QuantitiesUnitsModelling","04_ConstantAcceleration1D"],"topicNames":["Forces","Quantities, Units & Modelling","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2022_Jan_Q01_M06_06_Forces.png","downloadName":"WME01-01_Y2022_Jan_Q01_M06_06_Forces.png","finalAnswer":"$(a)\\ F=\\dfrac{5\\sqrt3}{2}\\ \\mathrm{N}\\approx4.3\\ \\mathrm{N}.\\quad (b)\\ T=\\dfrac52\\ \\mathrm{N}$.","steps":[{"title":"Resolve perpendicular to the string","body":"The force $F$ is perpendicular to the string. The weight is $5$ N vertically downward, and the string makes $60^\\circ$ with the vertical."},{"title":"Find F","body":"The component of the weight perpendicular to the string is $5\\cos30^\\circ$, so $F=5\\cos30^\\circ=\\dfrac{5\\sqrt3}{2}\\ \\mathrm{N}$."},{"title":"Resolve along the string","body":"The tension balances the component of the weight along the string. This component is $5\\sin30^\\circ$."},{"title":"Find T","body":"$T=5\\sin30^\\circ=\\dfrac52\\ \\mathrm{N}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_MayJune_Q04","year":2022,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2022","qNo":4,"marks":12,"topic":"06_Forces","topicName":"Forces","primaryTopic":"06_Forces","primaryTopicName":"Forces","secondaryTopics":["01_QuantitiesUnitsModelling","07_NewtonsSecondLaw"],"secondaryTopicNames":["Quantities, Units & Modelling","Newton's Second Law"],"topics":["06_Forces","01_QuantitiesUnitsModelling","07_NewtonsSecondLaw"],"topicNames":["Forces","Quantities, Units & Modelling","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2022_MayJune_Q04_M12_06_Forces.png","downloadName":"WME01-01_Y2022_MayJune_Q04_M12_06_Forces.png","finalAnswer":"$(a)\\ F=12.1\\ \\mathrm{N}\\ \\text{approximately, and the block does not move}.\\quad (b)\\ P=19.4\\ \\mathrm{N}\\ \\text{approximately}$.","steps":[{"title":"Find the normal reaction when P = 14","body":"Resolve vertically. The upward component of the applied force is $14\\sin30^\\circ$, so $R+14\\sin30^\\circ=5g$."},{"title":"Calculate R","body":"$R+7=49$, so $R=42\\ \\mathrm{N}$."},{"title":"Find the maximum friction","body":"$F_{\\max}=\\mu R=\\dfrac37(42)=18\\ \\mathrm{N}$."},{"title":"Compare with the horizontal pull","body":"The horizontal component of the applied force is $14\\cos30^\\circ=12.1\\ldots\\ \\mathrm{N}$. Since this is less than the maximum possible friction, the block does not move."},{"title":"State the actual friction","body":"For equilibrium, the actual friction equals the horizontal pull, so $F=12.1\\ \\mathrm{N}$ approximately."},{"title":"Set up the limiting case","body":"When the block is on the point of slipping, friction is limiting. Resolve vertically: $R+P\\sin30^\\circ=5g$, so $R=5g-P\\sin30^\\circ$."},{"title":"Resolve horizontally","body":"At the limiting case, $P\\cos30^\\circ=\\dfrac37R=\\dfrac37(5g-P\\sin30^\\circ)$."},{"title":"Find P","body":"Substitute $g=9.8$, $\\sin30^\\circ=\\dfrac12$: $P\\cos30^\\circ=\\dfrac37(49-\\dfrac12P)$. Solving gives $P=19.4\\ldots\\ \\mathrm{N}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2023_Jan_Q06","year":2023,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2023","qNo":6,"marks":8,"topic":"06_Forces","topicName":"Forces","primaryTopic":"06_Forces","primaryTopicName":"Forces","secondaryTopics":["02_WorkingWithVectors","01_QuantitiesUnitsModelling"],"secondaryTopicNames":["Working with Vectors","Quantities, Units & Modelling"],"topics":["06_Forces","02_WorkingWithVectors","01_QuantitiesUnitsModelling"],"topicNames":["Forces","Working with Vectors","Quantities, Units & Modelling"],"image":"ial/wme01/questions/WME01-01_Y2023_Jan_Q06_M08_06_Forces.png","downloadName":"WME01-01_Y2023_Jan_Q06_M08_06_Forces.png","finalAnswer":"$(i)\\ \\alpha=32^\\circ\\ \\text{approximately}.\\quad (ii)\\ P=610\\ \\mathrm{N}\\ \\text{approximately}$.","steps":[{"title":"Resolve perpendicular to the motion","body":"The boat travels straight, so the sideways components balance: $500\\sin40^\\circ=P\\sin\\alpha$."},{"title":"Resolve along the motion","body":"The speed is constant, so the forward components balance the resistance: $500\\cos40^\\circ+P\\cos\\alpha=900$."},{"title":"Eliminate P","body":"From the two equations, $P\\sin\\alpha=500\\sin40^\\circ$ and $P\\cos\\alpha=900-500\\cos40^\\circ$."},{"title":"Find alpha","body":"Divide the sine equation by the cosine equation: $\\tan\\alpha=\\dfrac{500\\sin40^\\circ}{900-500\\cos40^\\circ}$. This gives $\\alpha=31.9^\\circ$, so $\\alpha=32^\\circ$ approximately."},{"title":"Find P","body":"Use $P\\sin\\alpha=500\\sin40^\\circ$: $P=\\dfrac{500\\sin40^\\circ}{\\sin31.9^\\circ}=608.7\\ldots\\ \\mathrm{N}$. Hence $P\\approx610\\ \\mathrm{N}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2023_MayJune_Q06","year":2023,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2023","qNo":6,"marks":7,"topic":"06_Forces","topicName":"Forces","primaryTopic":"06_Forces","primaryTopicName":"Forces","secondaryTopics":["07_NewtonsSecondLaw"],"secondaryTopicNames":["Newton's Second Law"],"topics":["06_Forces","07_NewtonsSecondLaw"],"topicNames":["Forces","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2023_MayJune_Q06_M07_06_Forces.png","downloadName":"WME01-01_Y2023_MayJune_Q06_M07_06_Forces.png","finalAnswer":"$P\\le\\dfrac{5}{8}W$.","steps":[{"title":"Use the trig ratios","body":"Given $\\tan\\alpha=\\dfrac43$, use $\\sin\\alpha=\\dfrac45$ and $\\cos\\alpha=\\dfrac35$."},{"title":"Resolve vertically","body":"The applied force increases the normal reaction in this model, so $R=W+P\\sin\\alpha$."},{"title":"Resolve horizontally","body":"For the particle not to move, friction must be able to balance the horizontal component of the applied force, so $P\\cos\\alpha\\le F_{\\max}$."},{"title":"Use limiting friction","body":"Since $\\mu=\\dfrac14$, $F_{\\max}=\\dfrac14R=\\dfrac14(W+P\\sin\\alpha)$."},{"title":"Substitute the exact trig values","body":"Thus $P\\cdot\\dfrac35\\le\\dfrac14\\left(W+P\\cdot\\dfrac45\\right)$."},{"title":"Rearrange the inequality","body":"Multiplying by $20$ gives $12P\\le5W+4P$. Hence $8P\\le5W$, so $P\\le\\dfrac58W$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2023_Oct_Q05","year":2023,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2023","qNo":5,"marks":12,"topic":"06_Forces","topicName":"Forces","primaryTopic":"06_Forces","primaryTopicName":"Forces","secondaryTopics":["08_ResolvingForcesInclinedPlanes"],"secondaryTopicNames":["Resolving Forces, Inclined Planes"],"topics":["06_Forces","08_ResolvingForcesInclinedPlanes"],"topicNames":["Forces","Resolving Forces, Inclined Planes"],"image":"ial/wme01/questions/WME01-01_Y2023_Oct_Q05_M12_06_Forces.png","downloadName":"WME01-01_Y2023_Oct_Q05_M12_06_Forces.png","finalAnswer":"$(a)\\ F=1.9\\ \\mathrm{N}$. $(b)$ Friction acts downwards. $(c)(i)\\ T_{\\min}=3.2\\ \\mathrm{N}.\\quad (c)(ii)\\ T_{\\max}=13\\ \\mathrm{N}$.","steps":[{"title":"Use the trig ratios","body":"The string makes angle $\\theta$ with the vertical rod and $\\tan\\theta=\\dfrac{12}{5}$. Hence $\\sin\\theta=\\dfrac{12}{13}$ and $\\cos\\theta=\\dfrac{5}{13}$."},{"title":"Find the friction for T = 10","body":"The upward component of the tension is $10\\cos\\theta=10\\cdot\\dfrac{5}{13}=\\dfrac{50}{13}$ N. The weight is $0.2g=1.96$ N."},{"title":"Balance vertical forces","body":"Since the upward component of tension is larger than the weight, friction must act downwards. Its magnitude is $\\dfrac{50}{13}-1.96=1.89\\ldots\\ \\mathrm{N}$, so $F=1.9\\ \\mathrm{N}$."},{"title":"Write the normal reaction","body":"For variable tension $T$, the normal reaction from the rod is produced by the horizontal component of tension: $R=T\\sin\\theta=\\dfrac{12T}{13}$."},{"title":"Use limiting friction","body":"Since $\\mu=\\dfrac14$, limiting friction is $F=\\mu R=\\dfrac14\\cdot\\dfrac{12T}{13}=\\dfrac{3T}{13}$."},{"title":"Find the minimum tension","body":"For the minimum tension, the ring would tend to slide down, so friction acts upwards. Vertical equilibrium gives $T\\cos\\theta+F=0.2g$, hence $\\dfrac{5T}{13}+\\dfrac{3T}{13}=1.96$. Thus $T=3.185\\ldots\\ \\mathrm{N}$, so $T_{\\min}=3.2\\ \\mathrm{N}$."},{"title":"Find the maximum tension","body":"For the maximum tension, the ring would tend to move up, so friction acts downwards. Vertical equilibrium gives $T\\cos\\theta=0.2g+F$, hence $\\dfrac{5T}{13}=1.96+\\dfrac{3T}{13}$. Thus $T=12.74\\ldots\\ \\mathrm{N}$, so $T_{\\max}=13\\ \\mathrm{N}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2024_Jan_Q01","year":2024,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2024","qNo":1,"marks":6,"topic":"06_Forces","topicName":"Forces","primaryTopic":"06_Forces","primaryTopicName":"Forces","secondaryTopics":["01_QuantitiesUnitsModelling","04_ConstantAcceleration1D"],"secondaryTopicNames":["Quantities, Units & Modelling","Constant Acceleration in 1D"],"topics":["06_Forces","01_QuantitiesUnitsModelling","04_ConstantAcceleration1D"],"topicNames":["Forces","Quantities, Units & Modelling","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2024_Jan_Q01_M06_06_Forces.png","downloadName":"WME01-01_Y2024_Jan_Q01_M06_06_Forces.png","finalAnswer":"$(a)\\ T=2.5\\ \\mathrm{N}.\\quad (b)\\ M=0.408\\ \\mathrm{kg}\\ \\text{approximately}$.","steps":[{"title":"Use the trig ratios","body":"Given $\\tan\\theta=\\dfrac34$, use $\\sin\\theta=\\dfrac35$ and $\\cos\\theta=\\dfrac45$."},{"title":"Resolve horizontally","body":"The horizontal force of $2$ N is balanced by the horizontal component of the tension in the sloping part of the string: $T\\cos\\theta=2$."},{"title":"Find the tension","body":"$T\\cdot\\dfrac45=2$, so $T=2.5\\ \\mathrm{N}$."},{"title":"Resolve vertically","body":"The ring is smooth, so the tension is the same in both parts of the string. Upward components are $T$ from the vertical part and $T\\sin\\theta$ from the sloping part. Therefore $T+T\\sin\\theta=Mg$."},{"title":"Find the mass","body":"$Mg=2.5+2.5\\cdot\\dfrac35=4.0$, so $M=\\dfrac{4.0}{9.8}=0.408\\ \\mathrm{kg}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2024_Jan_Q04","year":2024,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2024","qNo":4,"marks":8,"topic":"06_Forces","topicName":"Forces","primaryTopic":"06_Forces","primaryTopicName":"Forces","secondaryTopics":["02_WorkingWithVectors"],"secondaryTopicNames":["Working with Vectors"],"topics":["06_Forces","02_WorkingWithVectors"],"topicNames":["Forces","Working with Vectors"],"image":"ial/wme01/questions/WME01-01_Y2024_Jan_Q04_M08_06_Forces.png","downloadName":"WME01-01_Y2024_Jan_Q04_M08_06_Forces.png","finalAnswer":"$(i)\\ X=18\\ \\mathrm{N}.\\quad (ii)\\ \\text{angle}=128^\\circ\\ \\text{to the nearest degree}$.","steps":[{"title":"Use the included angle in the force triangle","body":"The two given forces have angle $150^\\circ$ between them, so the triangle used for adding them has the supplementary angle $30^\\circ$ between the side of length $X$ and the side of length $5\\sqrt3$."},{"title":"Use the cosine rule to find X","body":"The resultant has magnitude $\\sqrt{129}$. Therefore $129=X^2+(5\\sqrt3)^2-2X(5\\sqrt3)\\cos30^\\circ$."},{"title":"Solve for X","body":"Since $(5\\sqrt3)^2=75$ and $2(5\\sqrt3)\\cos30^\\circ=15$, the equation becomes $129=X^2+75-15X$. Thus $X^2-15X-54=0$, giving $X=18$."},{"title":"Find the angle with Q","body":"Let $\\beta$ be the angle between Q and the resultant. Using the cosine rule in the same triangle, $\\dfrac{18}{\\sin\\beta}=\\dfrac{\\sqrt{129}}{\\sin30^\\circ}$."},{"title":"Choose the correct angle","body":"This gives an obtuse angle for $\\beta$. Equivalently, $\\cos\\beta=\\dfrac{(5\\sqrt3)^2+129-18^2}{2(5\\sqrt3)\\sqrt{129}}$, so $\\beta=127.6\\ldots^\\circ$."},{"title":"Round the angle","body":"To the nearest degree, the angle between Q and the resultant is $128^\\circ$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2024_MayJune_Q02","year":2024,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2024","qNo":2,"marks":4,"topic":"06_Forces","topicName":"Forces","primaryTopic":"06_Forces","primaryTopicName":"Forces","secondaryTopics":["02_WorkingWithVectors"],"secondaryTopicNames":["Working with Vectors"],"topics":["06_Forces","02_WorkingWithVectors"],"topicNames":["Forces","Working with Vectors"],"image":"ial/wme01/questions/WME01-01_Y2024_MayJune_Q02_M04_06_Forces.png","downloadName":"WME01-01_Y2024_MayJune_Q02_M04_06_Forces.png","finalAnswer":"$|\\mathbf{F}|=2\\sqrt{61}\\ \\mathrm{N}\\approx15.6\\ \\mathrm{N}$.","steps":[{"title":"Resolve the two forces","body":"Take east as $\\mathbf{i}$ and north as $\\mathbf{j}$. The force due west is $-10\\mathbf{i}$. A bearing of $330^\\circ$ is $30^\\circ$ west of north, so the 8 N force has components $-8\\sin30^\\circ\\mathbf{i}+8\\cos30^\\circ\\mathbf{j}$."},{"title":"Add the components","body":"$\\mathbf{F}=(-10-4)\\mathbf{i}+4\\sqrt3\\mathbf{j}=-14\\mathbf{i}+4\\sqrt3\\mathbf{j}$."},{"title":"Find the magnitude","body":"$|\\mathbf{F}|=\\sqrt{(-14)^2+(4\\sqrt3)^2}=\\sqrt{196+48}=\\sqrt{244}=2\\sqrt{61}\\ \\mathrm{N}$."},{"title":"Give a decimal value","body":"$2\\sqrt{61}=15.620\\ldots$, so the magnitude is about $16\\ \\mathrm{N}$ to 2 significant figures."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2025_Jan_Q01","year":2025,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2025","qNo":1,"marks":8,"topic":"06_Forces","topicName":"Forces","primaryTopic":"06_Forces","primaryTopicName":"Forces","secondaryTopics":["02_WorkingWithVectors","07_NewtonsSecondLaw"],"secondaryTopicNames":["Working with Vectors","Newton's Second Law"],"topics":["06_Forces","02_WorkingWithVectors","07_NewtonsSecondLaw"],"topicNames":["Forces","Working with Vectors","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2025_Jan_Q01_M08_06_Forces.png","downloadName":"WME01-01_Y2025_Jan_Q01_M08_06_Forces.png","finalAnswer":"$(a)\\ |\\mathbf{a}|=\\dfrac{12\\sqrt{13}}{5}\\ \\mathrm{m\\,s^{-2}}\\approx8.7\\ \\mathrm{m\\,s^{-2}}.\\quad (b)\\ p=-30$.","steps":[{"title":"Find the resultant of the first three forces","body":"$\\mathbf{F}_1+\\mathbf{F}_2+\\mathbf{F}_3=(6\\mathbf{i}+8\\mathbf{j})+(-16\\mathbf{i}+2\\mathbf{j})+(-2\\mathbf{i}+8\\mathbf{j})=-12\\mathbf{i}+18\\mathbf{j}$."},{"title":"Apply Newtons second law","body":"The mass is $2.5$ kg, so $-12\\mathbf{i}+18\\mathbf{j}=2.5\\mathbf{a}$. Hence $\\mathbf{a}=-4.8\\mathbf{i}+7.2\\mathbf{j}\\ \\mathrm{m\\,s^{-2}}$."},{"title":"Find the magnitude of the acceleration","body":"$|\\mathbf{a}|=\\sqrt{(-4.8)^2+7.2^2}=8.653\\ldots$, so the magnitude is $8.7\\ \\mathrm{m\\,s^{-2}}$ to 2 significant figures. Exactly, $|\\mathbf{a}|=\\dfrac{12\\sqrt{13}}{5}$."},{"title":"Add the fourth force","body":"With $\\mathbf{F}_4=p\\mathbf{i}+p\\mathbf{j}$, the new resultant is $(p-12)\\mathbf{i}+(p+18)\\mathbf{j}$."},{"title":"Use the given direction","body":"The resultant acts in the direction $7\\mathbf{i}+2\\mathbf{j}$, so $\\dfrac{p-12}{p+18}=\\dfrac{7}{2}$."},{"title":"Solve for p","body":"$2(p-12)=7(p+18)$, so $2p-24=7p+126$. Therefore $-150=5p$ and $p=-30$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2025_MayJune_Q04","year":2025,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2025","qNo":4,"marks":7,"topic":"06_Forces","topicName":"Forces","primaryTopic":"06_Forces","primaryTopicName":"Forces","secondaryTopics":["07_NewtonsSecondLaw"],"secondaryTopicNames":["Newton's Second Law"],"topics":["06_Forces","07_NewtonsSecondLaw"],"topicNames":["Forces","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2025_MayJune_Q04_M07_06_Forces.png","downloadName":"WME01-01_Y2025_MayJune_Q04_M07_06_Forces.png","finalAnswer":"$(a)\\ \\alpha=43^\\circ$ to the nearest degree. $(b)\\ a=0.023\\ \\mathrm{m\\,s^{-2}}$.","steps":[{"title":"Part (a): Find the value of $\\alpha$ - Resolve perpendicular to direction of motion","body":"$\\sum F_{\\perp} = 0 \\text{ (no sideways motion)}$\n \n Perpendicular component of 800 N rope:\n $800 \\sin 25° = 800 \\times 0.4226 = 338.1 \\text{ N}$\n \n Perpendicular component of 500 N rope:\n $500 \\sin \\alpha$"},{"title":"Part (a): Find the value of $\\alpha$ - Set components equal","body":"$800 \\sin 25° = 500 \\sin \\alpha$ $338.1 = 500 \\sin \\alpha$ $\\sin \\alpha = \\frac{338.1}{500}$ $\\sin \\alpha = 0.6762$ $\\alpha = \\sin^{-1}(0.6762)$ $\\alpha = 42.5°$"},{"title":"Part (b): Find acceleration of barge - Resolve parallel to direction of motion","body":"$\\sum F_{\\parallel} = ma$\n \n Parallel component of 800 N rope:\n $800 \\cos 25° = 800 \\times 0.9063 = 725.0 \\text{ N}$\n \n Parallel component of 500 N rope:\n $500 \\cos 42.5° = 500 \\times 0.7373 = 368.7 \\text{ N}$\n \n Resistance force: $750$ N (opposes motion)\n \n Mass: $15$ tonnes $= 15000$ kg"},{"title":"Part (b): Find acceleration of barge - Apply Newton's Second Law","body":"$725.0 + 368.7 - 750 = 15000 \\times a$ $343.7 = 15000a$ $a = \\frac{343.7}{15000}$ $a = 0.02291...$ $a = 0.023 \\text{ m s}^{-2} \\text{ (2 sf)}$"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2025_Oct_Q03","year":2025,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2025","qNo":3,"marks":14,"topic":"06_Forces","topicName":"Forces","primaryTopic":"06_Forces","primaryTopicName":"Forces","secondaryTopics":["02_WorkingWithVectors","07_NewtonsSecondLaw"],"secondaryTopicNames":["Working with Vectors","Newton's Second Law"],"topics":["06_Forces","02_WorkingWithVectors","07_NewtonsSecondLaw"],"topicNames":["Forces","Working with Vectors","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2025_Oct_Q03_M14_06_Forces.png","downloadName":"WME01-01_Y2025_Oct_Q03_M14_06_Forces.png","finalAnswer":"$(a)\\ \\mathbf{a}=\\mathbf{i}+2.5\\mathbf{j}\\ \\mathrm{m\\,s^{-2}}.\\quad (b)\\ \\text{speed}=6.95\\ \\mathrm{m\\,s^{-1}}.\\quad (c)\\ b-c=3.\\quad (d)\\ \\mathbf{F}_3=(8\\mathbf{i}+5\\mathbf{j})\\ \\mathrm{N}\\ \\text{or}\\ (-12\\mathbf{i}-15\\mathbf{j})\\ \\mathrm{N}$.","steps":[{"title":"Part (a): Find the acceleration of P - Find resultant force","body":"$\\mathbf{F}_{\\text{resultant}} = \\mathbf{F}_1 + \\mathbf{F}_2$\n \n $\\mathbf{F}_{\\text{resultant}} = (-2\\mathbf{i} + 3\\mathbf{j}) + (4\\mathbf{i} + 2\\mathbf{j})$ $= (-2 + 4)\\mathbf{i} + (3 + 2)\\mathbf{j}$ $= 2\\mathbf{i} + 5\\mathbf{j} \\text{ N}$"},{"title":"Part (a): Find the acceleration of P - Apply Newton's Second Law","body":"$\\mathbf{F} = m\\mathbf{a}$\n \n $2\\mathbf{i} + 5\\mathbf{j} = 2 \\times \\mathbf{a}$ $\\mathbf{a} = \\frac{2\\mathbf{i} + 5\\mathbf{j}}{2}$ $\\mathbf{a} = \\mathbf{i} + 2.5\\mathbf{j} \\text{ m s}^{-2}$\n \n Or: $\\mathbf{a} = \\mathbf{i} + \\frac{5}{2}\\mathbf{j}$ m s$^{-2}$"},{"title":"Part (b): Find the speed of P when t = 3 seconds - Find velocity at t = 3","body":"$\\mathbf{v} = \\mathbf{u} + \\mathbf{a}t$\n \n Given:\n \n ; $\\mathbf{u} = 3\\mathbf{i} - 4\\mathbf{j}$ m s$^{-1}$\n ; $\\mathbf{a} = \\mathbf{i} + 2.5\\mathbf{j}$ m s$^{-2}$\n ; $t = 3$ seconds\n \n \n $\\mathbf{v} = (3\\mathbf{i} - 4\\mathbf{j}) + (\\mathbf{i} + 2.5\\mathbf{j}) \\times 3$ $= 3\\mathbf{i} - 4\\mathbf{j} + 3\\mathbf{i} + 7.5\\mathbf{j}$ $= 6\\mathbf{i} + 3.5\\mathbf{j} \\text{ m s}^{-1}$"},{"title":"Part (b): Find the speed of P when t = 3 seconds - Find the speed (magnitude of velocity)","body":"$|\\mathbf{v}| = \\sqrt{v_x^2 + v_y^2}$\n \n $\\text{Speed} = \\sqrt{6^2 + 3.5^2}$ $= \\sqrt{36 + 12.25}$ $= \\sqrt{48.25}$ $= 6.946...$ $= 6.95 \\text{ m s}^{-1} \\text{ (3 s.f.)}$"},{"title":"Part (c): Show that b - c = 3 - Find resultant of $\\mathbf{F}_1$, $\\mathbf{F}_2$, and $\\mathbf{F}_3$","body":"$\\mathbf{F}_{\\text{resultant}} = \\mathbf{F}_1 + \\mathbf{F}_2 + \\mathbf{F}_3$ $= (-2\\mathbf{i} + 3\\mathbf{j}) + (4\\mathbf{i} + 2\\mathbf{j}) + (b\\mathbf{i} + c\\mathbf{j})$ $= (-2 + 4 + b)\\mathbf{i} + (3 + 2 + c)\\mathbf{j}$ $= (2 + b)\\mathbf{i} + (5 + c)\\mathbf{j}$"},{"title":"Part (c): Show that b - c = 3 - Apply the condition","body":"Given that resultant = $\\lambda(\\mathbf{i} + \\mathbf{j})$, we can write:\n \n $(2 + b)\\mathbf{i} + (5 + c)\\mathbf{j} = \\lambda\\mathbf{i} + \\lambda\\mathbf{j}$"},{"title":"Part (c): Show that b - c = 3 - Compare coefficients","body":"For this to be in the form $\\lambda(\\mathbf{i} + \\mathbf{j})$, the coefficients must be equal:\n \n $2 + b = \\lambda$ $5 + c = \\lambda$\n \n Therefore:\n $2 + b = 5 + c$ $b = 5 + c - 2$ $b = 3 + c$ $b - c = 3$"},{"title":"Part (d): Find the two possible $\\mathbf{F}_3$ forces - Use the magnitude condition","body":"Resultant = $(2 + b)\\mathbf{i} + (5 + c)\\mathbf{j}$\n \n Since resultant = $\\lambda(\\mathbf{i} + \\mathbf{j})$, we have $2 + b = 5 + c = \\lambda$\n \n $|\\mathbf{F}_{\\text{resultant}}| = \\lambda\\sqrt{1^2 + 1^2} = \\lambda\\sqrt{2}$\n \n Given: $|\\mathbf{F}_{\\text{resultant}}| = 10\\sqrt{2}$\n \n $\\lambda\\sqrt{2} = 10\\sqrt{2}$ $\\lambda = 10 \\quad \\text{or} \\quad \\lambda = -10$\n \n (The negative value comes from considering the opposite direction)"},{"title":"Part (d): Find the two possible $\\mathbf{F}_3$ forces - Find b and c for each value of $\\lambda$","body":"Case 1: $\\lambda = 10$\n \n $2 + b = 10 \\quad \\Rightarrow \\quad b = 8$ $5 + c = 10 \\quad \\Rightarrow \\quad c = 5$\n \n Check: $b - c = 8 - 5 = 3$ ✓\n \n Therefore: $\\mathbf{F}_3 = 8\\mathbf{i} + 5\\mathbf{j}$ N\n \n \n Case 2: $\\lambda = -10$\n \n $2 + b = -10 \\quad \\Rightarrow \\quad b = -12$ $5 + c = -10 \\quad \\Rightarrow \\quad c = -15$\n \n Check: $b - c = -12 - (-15) = 3$ ✓\n \n Therefore: $\\mathbf{F}_3 = -12\\mathbf{i} - 15\\mathbf{j}$ N"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2026_Jan_Q03","year":2026,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2026","qNo":3,"marks":8,"topic":"06_Forces","topicName":"Forces","primaryTopic":"06_Forces","primaryTopicName":"Forces","secondaryTopics":["02_WorkingWithVectors","07_NewtonsSecondLaw"],"secondaryTopicNames":["Working with Vectors","Newton's Second Law"],"topics":["06_Forces","02_WorkingWithVectors","07_NewtonsSecondLaw"],"topicNames":["Forces","Working with Vectors","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2026_Jan_Q03_M08_06_Forces.png","downloadName":"WME01-01_Y2026_Jan_Q03_M08_06_Forces.png","finalAnswer":"$(a)\\ 2p-q=19.\\quad (b)\\ \\mathbf{a}=24\\mathbf{i}-30\\mathbf{j}\\ \\mathrm{m\\,s^{-2}}$.","steps":[{"title":"Add the three forces","body":"The resultant force is $(2p\\mathbf{i}-3p\\mathbf{j})+(q\\mathbf{i}+\\mathbf{j})+(3\\mathbf{i}-q\\mathbf{j})=(2p+q+3)\\mathbf{i}+(-3p+1-q)\\mathbf{j}$."},{"title":"Use the direction vector","body":"The resultant acts in the direction $4\\mathbf{i}-5\\mathbf{j}$, so the ratio of the components is the same: $\\dfrac{-3p+1-q}{2p+q+3}=\\dfrac{-5}{4}$."},{"title":"Show the required relation","body":"Cross-multiplying gives $4(-3p+1-q)=-5(2p+q+3)$. Therefore $-12p+4-4q=-10p-5q-15$, so $2p-q=19$."},{"title":"Find q when p is 7","body":"With $p=7$, the relation gives $14-q=19$, hence $q=-5$."},{"title":"Apply Newtons second law","body":"Substitute $p=7$ and $q=-5$ into the resultant: $\\mathbf{F}=12\\mathbf{i}-15\\mathbf{j}$. Since the mass is $0.5$ kg, $\\mathbf{F}=m\\mathbf{a}$ gives $12\\mathbf{i}-15\\mathbf{j}=0.5\\mathbf{a}$."},{"title":"Find the acceleration","body":"Dividing by $0.5$ gives $\\mathbf{a}=24\\mathbf{i}-30\\mathbf{j}\\ \\mathrm{m\\,s^{-2}}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2019_Oct_Q03","year":2019,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2019","qNo":3,"marks":7,"topic":"07_NewtonsSecondLaw","topicName":"Newton's Second Law","primaryTopic":"07_NewtonsSecondLaw","primaryTopicName":"Newton's Second Law","secondaryTopics":["08_ResolvingForcesInclinedPlanes"],"secondaryTopicNames":["Resolving Forces, Inclined Planes"],"topics":["07_NewtonsSecondLaw","08_ResolvingForcesInclinedPlanes"],"topicNames":["Newton's Second Law","Resolving Forces, Inclined Planes"],"image":"ial/wme01/questions/WME01-01_Y2019_Oct_Q03_M07_07_NewtonsSecondLaw.png","downloadName":"WME01-01_Y2019_Oct_Q03_M07_07_NewtonsSecondLaw.png","finalAnswer":"$D=6000\\ \\mathrm{N}$.","steps":[{"title":"Use the trailer to find acceleration","body":"For the trailer, take up the road as positive. The forces along the road are tension $2060$ N up the road, resistance $300$ N down the road, and weight component $400g\\sin\\alpha$ down the road."},{"title":"Form the trailer equation","body":"$2060-300-400g\\sin\\alpha=400a$. Since $\\sin\\alpha=\\dfrac17$, this becomes $2060-300-400g\\cdot\\dfrac17=400a$."},{"title":"Find the acceleration","body":"Using $g=9.8$, $400g\\cdot\\dfrac17=560$. Hence $1200=400a$ and $a=3\\ \\mathrm{m\\,s^{-2}}$."},{"title":"Apply Newton's second law to the car","body":"For the car: $D-420-800g\\sin\\alpha-2060=800a$."},{"title":"Find the driving force","body":"$D-420-800g\\cdot\\dfrac17-2060=800(3)$. Since $800g\\cdot\\dfrac17=1120$, $D=420+1120+2060+2400=6000$ N."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2020_Jan_Q07","year":2020,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2020","qNo":7,"marks":18,"topic":"07_NewtonsSecondLaw","topicName":"Newton's Second Law","primaryTopic":"07_NewtonsSecondLaw","primaryTopicName":"Newton's Second Law","secondaryTopics":["06_Forces","04_ConstantAcceleration1D"],"secondaryTopicNames":["Forces","Constant Acceleration in 1D"],"topics":["07_NewtonsSecondLaw","06_Forces","04_ConstantAcceleration1D"],"topicNames":["Newton's Second Law","Forces","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2020_Jan_Q07_M18_07_NewtonsSecondLaw.png","downloadName":"WME01-01_Y2020_Jan_Q07_M18_07_NewtonsSecondLaw.png","finalAnswer":"$(a)\\ a=0.7\\ \\mathrm{m\\,s^{-2}}.\\quad (b)$ Inextensibility of the string. $(c)\\ 38.6\\ \\mathrm{N}.\\quad (d)\\ \\mu=0.625.\\quad (e)$ A does not reach the pulley.","steps":[{"title":"Use B's descent","body":"Before B hits the floor, it descends $1.4$ m from rest in $2$ s. Use $s=ut+\\dfrac12at^2$: $1.4=\\dfrac12a(2)^2$. Hence $a=0.7\\ \\mathrm{m\\,s^{-2}}$."},{"title":"Name the modelling assumption","body":"The string is inextensible, so A and B have the same magnitude of acceleration while the string is taut."},{"title":"Find the tension","body":"For B, taking downward as positive: $3g-T=3(0.7)$. Thus $T=3g-2.1=27.3$ N."},{"title":"Find the resultant force on the pulley","body":"The pulley is pulled by two perpendicular tensions of magnitude $T$. Therefore the resultant is $\\sqrt{T^2+T^2}=T\\sqrt2=27.3\\sqrt2=38.6$ N approximately."},{"title":"Find the friction on A","body":"For A before B hits the floor, $T-F=4(0.7)$. Hence $F=27.3-2.8=24.5$ N."},{"title":"Find mu","body":"On the horizontal table, $R=4g=39.2$ N and $F=\\mu R$. So $\\mu=\\dfrac{24.5}{39.2}=0.625$."},{"title":"Find A's speed when B hits the floor","body":"At this instant, $v=at=0.7(2)=1.4\\ \\mathrm{m\\,s^{-1}}$. A has also moved $1.4$ m towards the pulley."},{"title":"Find the extra stopping distance","body":"After B hits the floor, A is slowed only by friction. Its deceleration is $\\mu g=0.625(9.8)=6.125\\ \\mathrm{m\\,s^{-2}}$. Use $0=(1.4)^2-2(6.125)s$, giving $s=0.16$ m."},{"title":"Compare with the distance to the pulley","body":"A's total distance is $1.4+0.16=1.56$ m, which is less than $2$ m. Therefore A does not reach the pulley."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_MayJune_Q04","year":2021,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2021","qNo":4,"marks":6,"topic":"07_NewtonsSecondLaw","topicName":"Newton's Second Law","primaryTopic":"07_NewtonsSecondLaw","primaryTopicName":"Newton's Second Law","secondaryTopics":["04_ConstantAcceleration1D","01_QuantitiesUnitsModelling","08_ResolvingForcesInclinedPlanes"],"secondaryTopicNames":["Constant Acceleration in 1D","Quantities, Units & Modelling","Resolving Forces, Inclined Planes"],"topics":["07_NewtonsSecondLaw","04_ConstantAcceleration1D","01_QuantitiesUnitsModelling","08_ResolvingForcesInclinedPlanes"],"topicNames":["Newton's Second Law","Constant Acceleration in 1D","Quantities, Units & Modelling","Resolving Forces, Inclined Planes"],"image":"ial/wme01/questions/WME01-01_Y2021_MayJune_Q04_M06_07_NewtonsSecondLaw.png","downloadName":"WME01-01_Y2021_MayJune_Q04_M06_07_NewtonsSecondLaw.png","finalAnswer":"$(a)\\ T=400\\ \\mathrm{N}.\\quad (b)\\ R=119\\ \\mathrm{N}\\ \\text{approximately}$.","steps":[{"title":"Find total mass going up","body":"The bucket and cement have total mass $15+25=40$ kg and acceleration $0.2\\ \\mathrm{m\\,s^{-2}}$ upward."},{"title":"Apply Newtons second law","body":"Taking upward as positive: $T-40g=40(0.2)$."},{"title":"Find the tension","body":"$T-392=8$, so $T=400\\ \\mathrm{N}$."},{"title":"Interpret the downward deceleration","body":"The bucket and tools are moving downward but decelerating, so their acceleration is upward with magnitude $0.1\\ \\mathrm{m\\,s^{-2}}$."},{"title":"Consider the box of tools","body":"For the $12$ kg box, upward force is the normal reaction $R$, and downward force is weight $12g$."},{"title":"Find R","body":"$R-12g=12(0.1)$. Thus $R=117.6+1.2=118.8\\ \\mathrm{N}$, about $119\\ \\mathrm{N}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_MayJune_Q03","year":2022,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2022","qNo":3,"marks":7,"topic":"07_NewtonsSecondLaw","topicName":"Newton's Second Law","primaryTopic":"07_NewtonsSecondLaw","primaryTopicName":"Newton's Second Law","secondaryTopics":["01_QuantitiesUnitsModelling","02_WorkingWithVectors"],"secondaryTopicNames":["Quantities, Units & Modelling","Working with Vectors"],"topics":["07_NewtonsSecondLaw","01_QuantitiesUnitsModelling","02_WorkingWithVectors"],"topicNames":["Newton's Second Law","Quantities, Units & Modelling","Working with Vectors"],"image":"ial/wme01/questions/WME01-01_Y2022_MayJune_Q03_M07_07_NewtonsSecondLaw.png","downloadName":"WME01-01_Y2022_MayJune_Q03_M07_07_NewtonsSecondLaw.png","finalAnswer":"$(a)\\ R=5600\\ \\mathrm{N}.\\quad (b)$ The tractor and block have the same acceleration.","steps":[{"title":"Apply Newtons second law to the tractor","body":"The tractor has mass $6000$ kg. Its forward driving force is $7400$ N, and the backward forces are $200$ N resistance and $6000$ N tension."},{"title":"Find the acceleration","body":"$7400-200-6000=6000a$, so $1200=6000a$ and $a=0.2\\ \\mathrm{m\\,s^{-2}}$."},{"title":"Apply Newtons second law to the block","body":"The block has mass $2000$ kg. The forward force is the tension $6000$ N and the resistance is $R$ N."},{"title":"Find R","body":"$6000-R=2000(0.2)=400$. Therefore $R=5600\\ \\mathrm{N}$."},{"title":"Use the inextensible cable model","body":"The cable is inextensible, so the tractor and block move together with the same acceleration."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_Oct_Q04","year":2022,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2022","qNo":4,"marks":6,"topic":"07_NewtonsSecondLaw","topicName":"Newton's Second Law","primaryTopic":"07_NewtonsSecondLaw","primaryTopicName":"Newton's Second Law","secondaryTopics":["01_QuantitiesUnitsModelling","04_ConstantAcceleration1D"],"secondaryTopicNames":["Quantities, Units & Modelling","Constant Acceleration in 1D"],"topics":["07_NewtonsSecondLaw","01_QuantitiesUnitsModelling","04_ConstantAcceleration1D"],"topicNames":["Newton's Second Law","Quantities, Units & Modelling","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2022_Oct_Q04_M06_07_NewtonsSecondLaw.png","downloadName":"WME01-01_Y2022_Oct_Q04_M06_07_NewtonsSecondLaw.png","finalAnswer":"$(a)\\ a=1.5\\ \\mathrm{m\\,s^{-2}}.\\quad (b)\\ \\text{mass of Alan}=50\\ \\mathrm{kg}$.","steps":[{"title":"Consider the lift only","body":"For the lift, the upward force is the cable tension $3616$ N. Downward forces on the lift are its own weight $250g$ and the contact forces from Alan and Bhavana, $565$ N and $226$ N."},{"title":"Apply Newtons second law","body":"Taking upward as positive: $3616-250g-565-226=250a$."},{"title":"Find the acceleration","body":"$3616-2450-565-226=250a$, so $375=250a$ and $a=1.5\\ \\mathrm{m\\,s^{-2}}$."},{"title":"Consider Alan","body":"Let Alan's mass be $m_A$. The upward force on Alan is $565$ N and his weight is $m_Ag$."},{"title":"Find Alan's mass","body":"$565-m_Ag=m_A(1.5)$, so $565=m_A(9.8+1.5)=11.3m_A$. Hence $m_A=50\\ \\mathrm{kg}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_Oct_Q07","year":2022,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2022","qNo":7,"marks":13,"topic":"07_NewtonsSecondLaw","topicName":"Newton's Second Law","primaryTopic":"07_NewtonsSecondLaw","primaryTopicName":"Newton's Second Law","secondaryTopics":["08_ResolvingForcesInclinedPlanes"],"secondaryTopicNames":["Resolving Forces, Inclined Planes"],"topics":["07_NewtonsSecondLaw","08_ResolvingForcesInclinedPlanes"],"topicNames":["Newton's Second Law","Resolving Forces, Inclined Planes"],"image":"ial/wme01/questions/WME01-01_Y2022_Oct_Q07_M13_07_NewtonsSecondLaw.png","downloadName":"WME01-01_Y2022_Oct_Q07_M13_07_NewtonsSecondLaw.png","finalAnswer":"$(a)\\ k=\\dfrac{1+\\mu}{2}.\\quad (b)\\ t=\\sqrt{\\dfrac{4d}{g(1-\\mu)}}.\\quad (c)$ If $\\mu\\ge1$, the system would not move because friction can balance the pull from P.","steps":[{"title":"Write the friction on Q","body":"For Q on the horizontal table, $R=mg$, so the friction is $F=\\mu mg$."},{"title":"Apply Newtons second law to P","body":"P moves downward and Q moves towards the pulley. For P, taking downward as positive: $mg-T=ma$."},{"title":"Apply Newtons second law to Q","body":"For Q, taking motion towards the pulley as positive: $T-\\mu mg=ma$."},{"title":"Use T = kmg","body":"From P, $a=g(1-k)$. From Q, $a=g(k-\\mu)$."},{"title":"Find k","body":"Equate the two accelerations: $1-k=k-\\mu$. Hence $2k=1+\\mu$ and $k=\\dfrac{1+\\mu}{2}$."},{"title":"Find the acceleration","body":"$a=g(1-k)=g\\left(1-\\dfrac{1+\\mu}{2}\\right)=\\dfrac{g(1-\\mu)}{2}$."},{"title":"Use motion from rest","body":"Q starts from rest and travels distance $d$, so $d=\\dfrac12at^2=\\dfrac12\\cdot\\dfrac{g(1-\\mu)}{2}t^2$."},{"title":"Find the time","body":"$d=\\dfrac{g(1-\\mu)t^2}{4}$, so $t=\\sqrt{\\dfrac{4d}{g(1-\\mu)}}$."},{"title":"Consider mu at least 1","body":"If $\\mu\\ge1$, the maximum available friction on Q is at least $mg$, so it can balance the pull caused by the hanging particle. The system would not start moving."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2023_Jan_Q07","year":2023,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2023","qNo":7,"marks":7,"topic":"07_NewtonsSecondLaw","topicName":"Newton's Second Law","primaryTopic":"07_NewtonsSecondLaw","primaryTopicName":"Newton's Second Law","secondaryTopics":["01_QuantitiesUnitsModelling","04_ConstantAcceleration1D"],"secondaryTopicNames":["Quantities, Units & Modelling","Constant Acceleration in 1D"],"topics":["07_NewtonsSecondLaw","01_QuantitiesUnitsModelling","04_ConstantAcceleration1D"],"topicNames":["Newton's Second Law","Quantities, Units & Modelling","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2023_Jan_Q07_M07_07_NewtonsSecondLaw.png","downloadName":"WME01-01_Y2023_Jan_Q07_M07_07_NewtonsSecondLaw.png","finalAnswer":"$(a)\\ \\text{combined mass of P and Q}=5m.\\quad (b)\\ \\text{mass of P}=2m$.","steps":[{"title":"Define the box mass","body":"Let the combined mass of boxes P and Q be $M$. The lift itself has mass $m$, so the total moving mass is $m+M$."},{"title":"Apply Newtons second law to the whole system","body":"Taking upward as positive, $\\dfrac{42}{5}mg-(m+M)g=(m+M)\\dfrac{2g}{5}$."},{"title":"Find M","body":"Move the weight term to the right: $\\dfrac{42}{5}mg=(m+M)\\left(g+\\dfrac{2g}{5}\\right)=\\dfrac{7g}{5}(m+M)$. Hence $42m=7(m+M)$ and $M=5m$."},{"title":"Let the mass of P be p","body":"For box P alone, the upward force from Q is $\\dfrac{14}{5}mg$, while its weight is $pg$. The acceleration is still $\\dfrac{2g}{5}$ upward."},{"title":"Apply Newtons second law to P","body":"$\\dfrac{14}{5}mg-pg=p\\dfrac{2g}{5}$."},{"title":"Find p","body":"Divide by $g$: $\\dfrac{14}{5}m=p+\\dfrac{2p}{5}=\\dfrac{7p}{5}$. Therefore $p=2m$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2023_MayJune_Q07","year":2023,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2023","qNo":7,"marks":11,"topic":"07_NewtonsSecondLaw","topicName":"Newton's Second Law","primaryTopic":"07_NewtonsSecondLaw","primaryTopicName":"Newton's Second Law","secondaryTopics":["08_ResolvingForcesInclinedPlanes","04_ConstantAcceleration1D"],"secondaryTopicNames":["Resolving Forces, Inclined Planes","Constant Acceleration in 1D"],"topics":["07_NewtonsSecondLaw","08_ResolvingForcesInclinedPlanes","04_ConstantAcceleration1D"],"topicNames":["Newton's Second Law","Resolving Forces, Inclined Planes","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2023_MayJune_Q07_M11_07_NewtonsSecondLaw.png","downloadName":"WME01-01_Y2023_MayJune_Q07_M11_07_NewtonsSecondLaw.png","finalAnswer":"$(a)\\ R=60\\ \\mathrm{N}.\\quad (b)\\ T=1000\\ \\mathrm{N}.\\quad (c)\\ d=78.5\\ \\mathrm{m}\\ \\text{approximately}$.","steps":[{"title":"Use the whole system","body":"For car plus trailer, the total mass is $1800$ kg and the total resistance is $2R+R=3R$. Taking up the slope as positive: $3000-1800g\\sin\\alpha-3R=1800(0.75)$."},{"title":"Show R is 60","body":"Since $\\sin\\alpha=\\dfrac1{12}$, $1800g\\sin\\alpha=1800\\cdot9.8\\cdot\\dfrac1{12}=1470$. So $3000-1470-3R=1350$, giving $180=3R$ and $R=60\\ \\mathrm{N}$."},{"title":"Apply Newtons second law to the trailer","body":"For the trailer while it is being towed, $T-600g\\sin\\alpha-R=600(0.75)$."},{"title":"Find the tow-bar tension","body":"$T-600\\cdot9.8\\cdot\\dfrac1{12}-60=450$, so $T-490-60=450$ and $T=1000\\ \\mathrm{N}$."},{"title":"Find the trailer acceleration after the break","body":"After the tow bar breaks, the trailer is still moving up the slope, but the component of weight and resistance act down the slope. Taking up the slope as positive: $-600g\\sin\\alpha-60=600a$."},{"title":"Simplify the acceleration","body":"$-490-60=600a$, so $a=-\\dfrac{550}{600}=-\\dfrac{11}{12}\\ \\mathrm{m\\,s^{-2}}$."},{"title":"Find the stopping distance","body":"With initial speed $12\\ \\mathrm{m\\,s^{-1}}$ and final speed $0$, use $v^2=u^2+2as$: $0=12^2+2\\left(-\\dfrac{11}{12}\\right)d$. Hence $d=\\dfrac{864}{11}=78.5\\ldots\\ \\mathrm{m}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2024_MayJune_Q03","year":2024,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2024","qNo":3,"marks":6,"topic":"07_NewtonsSecondLaw","topicName":"Newton's Second Law","primaryTopic":"07_NewtonsSecondLaw","primaryTopicName":"Newton's Second Law","secondaryTopics":["01_QuantitiesUnitsModelling","04_ConstantAcceleration1D"],"secondaryTopicNames":["Quantities, Units & Modelling","Constant Acceleration in 1D"],"topics":["07_NewtonsSecondLaw","01_QuantitiesUnitsModelling","04_ConstantAcceleration1D"],"topicNames":["Newton's Second Law","Quantities, Units & Modelling","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2024_MayJune_Q03_M06_07_NewtonsSecondLaw.png","downloadName":"WME01-01_Y2024_MayJune_Q03_M06_07_NewtonsSecondLaw.png","finalAnswer":"$T=\\dfrac{9mg}{2}=4.5mg$.","steps":[{"title":"Use the lower particle to find acceleration","body":"For P, take downward as positive. Its weight is $4mg$ and the tension in the string between P and Q is $3mg$ upward, so $4mg-3mg=4ma$."},{"title":"Find the acceleration","body":"The equation gives $mg=4ma$, hence $a=\\dfrac{g}{4}$ downward."},{"title":"Write the equation for Q","body":"For Q, downward forces are its weight $2mg$ and the lower string tension $3mg$. The upper string tension $T$ acts upward. Taking downward as positive: $2mg+3mg-T=2ma$."},{"title":"Substitute acceleration","body":"$5mg-T=2m\\left(\\dfrac{g}{4}\\right)=\\dfrac{mg}{2}$."},{"title":"Find the upper tension","body":"$T=5mg-\\dfrac{mg}{2}=\\dfrac{9mg}{2}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2024_Oct_Q05","year":2024,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2024","qNo":5,"marks":13,"topic":"07_NewtonsSecondLaw","topicName":"Newton's Second Law","primaryTopic":"07_NewtonsSecondLaw","primaryTopicName":"Newton's Second Law","secondaryTopics":["04_ConstantAcceleration1D"],"secondaryTopicNames":["Constant Acceleration in 1D"],"topics":["07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"topicNames":["Newton's Second Law","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2024_Oct_Q05_M13_07_NewtonsSecondLaw.png","downloadName":"WME01-01_Y2024_Oct_Q05_M13_07_NewtonsSecondLaw.png","finalAnswer":"$(a)\\ T-3g=3a.\\quad (b)\\ T=36.8\\ \\mathrm{N}.\\quad (c)\\ F=73.5\\ \\mathrm{N}.\\quad (d)\\ \\text{speed}=12.9\\ \\mathrm{m\\,s^{-1}}$.","steps":[{"title":"Write the equation for P","body":"P has mass $3$ kg and moves upwards, so taking upwards as positive gives $T-3g=3a$."},{"title":"Write the equation for Q","body":"Q has mass $5$ kg and moves downwards, so taking downwards as positive for Q gives $5g-T=5a$."},{"title":"Find acceleration and tension","body":"Adding the two equations gives $2g=8a$, so $a=\\dfrac{g}{4}$. Substitute into $T-3g=3a$: $T=3g+3\\left(\\dfrac{g}{4}\\right)=\\dfrac{15g}{4}=36.8\\ \\mathrm{N}$."},{"title":"Find the force on the pulley","body":"The pulley is pulled by two vertical tensions, each of magnitude $T$. Hence $F=2T=\\dfrac{15g}{2}=73.5\\ \\mathrm{N}$."},{"title":"Find Q speed when the string breaks","body":"Before the string breaks, Q descends $2$ m from rest with acceleration $g/4$. Thus $v^2=2\\left(\\dfrac{g}{4}\\right)(2)=g$, so $v=\\sqrt{g}$."},{"title":"Find the remaining fall","body":"After the string breaks, Q is still $8$ m above the ground and accelerates freely under gravity. Let the impact speed be $w$. Then $w^2=v^2+2g(8)=g+16g=17g$."},{"title":"Calculate the impact speed","body":"$w=\\sqrt{17g}=\\sqrt{166.6}=12.9\\ \\mathrm{m\\,s^{-1}}$ to 3 significant figures."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2025_Jan_Q07","year":2025,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2025","qNo":7,"marks":15,"topic":"07_NewtonsSecondLaw","topicName":"Newton's Second Law","primaryTopic":"07_NewtonsSecondLaw","primaryTopicName":"Newton's Second Law","secondaryTopics":["04_ConstantAcceleration1D"],"secondaryTopicNames":["Constant Acceleration in 1D"],"topics":["07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"topicNames":["Newton's Second Law","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2025_Jan_Q07_M15_07_NewtonsSecondLaw.png","downloadName":"WME01-01_Y2025_Jan_Q07_M15_07_NewtonsSecondLaw.png","finalAnswer":"$(a)\\ T=\\dfrac{12mg}{5}.\\quad (b)\\ v=1.4\\ \\mathrm{m\\,s^{-1}}.\\quad (c)\\ t=0.767\\ \\mathrm{s}\\ \\text{approximately}$.","steps":[{"title":"Write the equations of motion","body":"B moves down and A moves up with the same acceleration $a$. For A: $T-2mg=2ma$. For B: $3mg-T=3ma$."},{"title":"Find the acceleration","body":"Adding the two equations gives $mg=5ma$, so $a=\\dfrac{g}{5}$."},{"title":"Find the tension","body":"Use $T-2mg=2ma$: $T=2mg+2m\\left(\\dfrac{g}{5}\\right)=\\dfrac{12mg}{5}$."},{"title":"Find the speed when B hits the surface","body":"B starts from rest and moves $0.5$ m with acceleration $g/5$. Using $v^2=u^2+2as$, $v^2=2\\left(\\dfrac{g}{5}\\right)(0.5)=\\dfrac{g}{5}=1.96$."},{"title":"Calculate the impact speed","body":"$v=\\sqrt{1.96}=1.4\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Find the first time interval","body":"The time until B hits the surface is found from $0.5=\\dfrac12\\left(\\dfrac{g}{5}\\right)t_1^2$. With $g=9.8$, $t_1=\\dfrac{5}{7}=0.714285\\ldots$ s."},{"title":"Find the extra time after B stops","body":"After B hits the surface, A continues upwards freely under gravity. It is then at height $1.00$ m and must rise another $0.06$ m with initial speed $1.4\\ \\mathrm{m\\,s^{-1}}$. So $0.06=1.4t_2-4.9t_2^2$."},{"title":"Find the total time","body":"Solving $0.06=1.4t_2-4.9t_2^2$ gives the first positive time $t_2=0.0525\\ldots$ s. Therefore the total time is $0.714285\\ldots+0.0525\\ldots=0.767\\ \\mathrm{s}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2025_MayJune_Q08","year":2025,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2025","qNo":8,"marks":17,"topic":"07_NewtonsSecondLaw","topicName":"Newton's Second Law","primaryTopic":"07_NewtonsSecondLaw","primaryTopicName":"Newton's Second Law","secondaryTopics":["09_MomentumImpulseCollisions"],"secondaryTopicNames":["Momentum, Impulse & Collisions"],"topics":["07_NewtonsSecondLaw","09_MomentumImpulseCollisions"],"topicNames":["Newton's Second Law","Momentum, Impulse & Collisions"],"image":"ial/wme01/questions/WME01-01_Y2025_MayJune_Q08_M17_07_NewtonsSecondLaw.png","downloadName":"WME01-01_Y2025_MayJune_Q08_M17_07_NewtonsSecondLaw.png","finalAnswer":"$(a)\\ T-kMg=\\dfrac{kMg}{5}.\\quad (b)\\ k=2.\\quad (c)\\ F=\\dfrac{12g}{5}\\ \\mathrm{N}\\approx23.5\\ \\mathrm{N}.\\quad (d)\\ |I|=5.30\\ \\mathrm{N\\,s}.\\quad (e)\\ T=1.92\\ \\mathrm{s}$.","steps":[{"title":"Part (a): Write equation of motion for P - Identify forces on P","body":"Particle P (mass $kM$) moves upward with acceleration $\\frac{g}{5}$:\n \n \n ; Tension T (upward)\n ; Weight $kMg$ (downward)"},{"title":"Part (a): Write equation of motion for P - Apply Newton's Second Law","body":"Taking upward as positive:\n \n $\\sum F = ma$\n \n $T - kMg = kM \\times \\frac{g}{5}$"},{"title":"Part (b): Find value of k - Write equation of motion for Q","body":"Particle Q (mass $3M$) moves downward with acceleration $\\frac{g}{5}$:\n \n Taking downward as positive for Q:\n \n $3Mg - T = 3M \\times \\frac{g}{5}$ $3Mg - T = \\frac{3Mg}{5}$ $T = 3Mg - \\frac{3Mg}{5}$ $T = \\frac{12Mg}{5}$"},{"title":"Part (b): Find value of k - Substitute into equation for P","body":"From part (a): $T - kMg = \\frac{kMg}{5}$\n \n $\\frac{12Mg}{5} - kMg = \\frac{kMg}{5}$ $\\frac{12Mg}{5} = kMg + \\frac{kMg}{5}$ $\\frac{12Mg}{5} = \\frac{5kMg + kMg}{5}$ $\\frac{12Mg}{5} = \\frac{6kMg}{5}$ $12 = 6k$ $k = 2$"},{"title":"Part (c): Find force on pulley while Q moving down - Identify tension in string","body":"From part (b): $T = \\frac{12Mg}{5}$\n \n Given: $M = 0.5$ kg\n \n $T = \\frac{12 \\times 0.5 \\times g}{5}$ $= \\frac{6g}{5}$ $= \\frac{6 \\times 9.8}{5}$ $= 11.76 \\text{ N}$"},{"title":"Part (c): Find force on pulley while Q moving down - Find force on pulley","body":"The pulley experiences two tension forces:\n \n ; Horizontal tension from P: $T = 11.76$ N\n ; Vertical tension from Q: $T = 11.76$ N\n \n \n These are perpendicular, so use Pythagoras:\n \n $F = \\sqrt{T^2 + T^2}$ $= \\sqrt{2T^2}$ $= T\\sqrt{2}$ $= 11.76\\sqrt{2}$ $= 16.63...$ $= 16.6 \\text{ N (3 sf)}$\n \n Or: $F = \\frac{6g\\sqrt{2}}{5} = \\frac{12g}{5} = 2.4g = 23.5$ N\n \n Wait, let me recalculate...\n \n Actually: $F = 2T$ (both tensions pull on pulley)\n \n $F = 2 \\times \\frac{12Mg}{5}$ $= \\frac{24Mg}{5}$ $= \\frac{24 \\times 0.5 \\times 9.8}{5}$ $= \\frac{117.6}{5}$ $= 23.5 \\text{ N (3 sf)}$\n \n Or: $\\frac{12g}{5} = 23.5$ N"},{"title":"Part (d): Find impulse when Q hits ground - Find velocity of Q just before hitting ground","body":"Using SUVAT with:\n \n ; $u = 0$ (starts from rest)\n ; $a = \\frac{g}{5} = \\frac{9.8}{5} = 1.96$ m s$^{-2}$\n ; $s = 2.5$ m\n \n \n $v^2 = u^2 + 2as$ $v^2 = 0 + 2 \\times \\frac{g}{5} \\times 2.5$ $v^2 = \\frac{5g}{5}$ $v^2 = g$ $v = \\sqrt{g} = \\sqrt{9.8} = 3.130... \\text{ m s}^{-1}$\n \n Or exact: $v = \\sqrt{g} = \\sqrt{\\frac{7g}{5}}$ \n \n Actually: $v^2 = 2 \\times 1.96 \\times 2.5 = 9.8$, so $v = \\sqrt{9.8} = 3.13$ m s$^{-1}$"},{"title":"Part (d): Find impulse when Q hits ground - Calculate impulse","body":"$\\text{Impulse} = m(v_{\\text{after}} - v_{\\text{before}})$\n \n Taking downward as positive before impact:\n \n ; Velocity before: $v_{\\text{before}} = +3.13$ m s$^{-1}$ (downward)\n ; Velocity after: $v_{\\text{after}} = -0.4$ m s$^{-1}$ (upward, rebounds)\n ; Mass of Q: $3M = 3 \\times 0.5 = 1.5$ kg\n \n \n $I = 1.5 \\times (-0.4 - 3.13)$ $= 1.5 \\times (-3.53)$ $= -5.295...$ $|I| = 5.3 \\text{ N s (2 sf)}$\n \n Or using exact values: $|I| = 1.5(\\sqrt{g} + 0.4) = 1.5(3.13 + 0.4) = 5.3$ N s"},{"title":"Part (e): Find total time until P first comes to rest - Time for Q to fall ($t_1$)","body":"Using $s = ut + \\frac{1}{2}at^2$ with $u = 0$, $s = 2.5$ m, $a = \\frac{g}{5}$:\n \n $2.5 = 0 + \\frac{1}{2} \\times \\frac{g}{5} \\times t_1^2$ $2.5 = \\frac{g t_1^2}{10}$ $25 = g t_1^2$ $t_1^2 = \\frac{25}{9.8} = 2.551...$ $t_1 = \\sqrt{\\frac{25}{9.8}} = 1.597... \\text{ s}$\n \n Or exact: $t_1 = \\sqrt{\\frac{5 \\times 5}{g}} = \\frac{5}{\\sqrt{g}}$\n \n Better: $t_1 = \\sqrt{\\frac{5}{g/5}} = \\sqrt{\\frac{25}{g}}$\n \n Actually: $2.5 = \\frac{1}{2} \\times 1.96 \\times t_1^2$\n \n $t_1^2 = \\frac{5}{1.96} = 2.551$, so $t_1 = 1.597$ s"},{"title":"Part (e): Find total time until P first comes to rest - Velocity of P when Q hits ground","body":"At time $t_1$, P has velocity:\n $v_P = 0 + \\frac{g}{5} \\times t_1$ $= \\frac{9.8}{5} \\times 1.597$ $= 1.96 \\times 1.597$ $= 3.13 \\text{ m s}^{-1}$\n \n Or: $v_P = \\sqrt{g}$ (same as Q)"},{"title":"Part (e): Find total time until P first comes to rest - Time for P to come to rest ($t_2$)","body":"After Q hits ground, string goes slack. P continues upward under gravity alone.\n \n Using $v = u + at$ with $v = 0$, $u = 3.13$ m s$^{-1}$, $a = -g$:\n \n $0 = 3.13 - 9.8 t_2$ $t_2 = \\frac{3.13}{9.8}$ $= 0.3194... \\text{ s}$\n \n Or: $t_2 = \\frac{\\sqrt{g}}{g} = \\frac{1}{\\sqrt{g}}$"},{"title":"Part (e): Find total time until P first comes to rest - Total time","body":"$T = t_1 + t_2$ $= 1.597 + 0.319$ $= 1.916...$ $= 1.9 \\text{ s (2 sf)} \\text{ or } 1.92 \\text{ s (3 sf)}$"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2019_Oct_Q04","year":2019,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2019","qNo":4,"marks":12,"topic":"08_ResolvingForcesInclinedPlanes","topicName":"Resolving Forces, Inclined Planes","primaryTopic":"08_ResolvingForcesInclinedPlanes","primaryTopicName":"Resolving Forces, Inclined Planes","secondaryTopics":["06_Forces"],"secondaryTopicNames":["Forces"],"topics":["08_ResolvingForcesInclinedPlanes","06_Forces"],"topicNames":["Resolving Forces, Inclined Planes","Forces"],"image":"ial/wme01/questions/WME01-01_Y2019_Oct_Q04_M12_08_ResolvingForcesInclinedPlanes.png","downloadName":"WME01-01_Y2019_Oct_Q04_M12_08_ResolvingForcesInclinedPlanes.png","finalAnswer":"$(a)\\ \\mu=\\dfrac{k\\tan\\theta-1}{k+\\tan\\theta}.\\quad (b)\\ \\theta>45^\\circ$.","steps":[{"title":"Set friction direction","body":"The particle is on the point of sliding down the plane, so friction acts up the plane. Also $X=mg$."},{"title":"Resolve perpendicular to the plane","body":"Both the weight $kmg$ and the horizontal force $mg$ press the particle into the plane. Therefore $R=kmg\\cos\\theta+mg\\sin\\theta$."},{"title":"Resolve parallel to the plane","body":"Down the plane is the component $kmg\\sin\\theta$. Up the plane are friction $F$ and the component $mg\\cos\\theta$. Thus $F+mg\\cos\\theta=kmg\\sin\\theta$."},{"title":"Write friction in terms of theta","body":"So $F=kmg\\sin\\theta-mg\\cos\\theta$."},{"title":"Use limiting friction","body":"$\\mu=\\dfrac{F}{R}=\\dfrac{kmg\\sin\\theta-mg\\cos\\theta}{kmg\\cos\\theta+mg\\sin\\theta}$."},{"title":"Simplify the expression","body":"Cancel $mg$ and divide numerator and denominator by $\\cos\\theta$: $\\mu=\\dfrac{k\\tan\\theta-1}{k+\\tan\\theta}$, as required."},{"title":"Deduce the condition when k is 1","body":"When $k=1$, $\\mu=\\dfrac{\\tan\\theta-1}{1+\\tan\\theta}$. Since $\\mu>0$ and the denominator is positive, $\\tan\\theta-1>0$."},{"title":"Finish the inequality","body":"Therefore $\\tan\\theta>1$, so because $\\theta$ is acute, $\\theta>45^\\circ$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_Jan_Q08","year":2021,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2021","qNo":8,"marks":17,"topic":"08_ResolvingForcesInclinedPlanes","topicName":"Resolving Forces, Inclined Planes","primaryTopic":"08_ResolvingForcesInclinedPlanes","primaryTopicName":"Resolving Forces, Inclined Planes","secondaryTopics":["07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"secondaryTopicNames":["Newton's Second Law","Constant Acceleration in 1D"],"topics":["08_ResolvingForcesInclinedPlanes","07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"topicNames":["Resolving Forces, Inclined Planes","Newton's Second Law","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2021_Jan_Q08_M17_08_ResolvingForcesInclinedPlanes.png","downloadName":"WME01-01_Y2021_Jan_Q08_M17_08_ResolvingForcesInclinedPlanes.png","finalAnswer":"$(a)\\ T=\\dfrac{12g}{5}\\ \\mathrm{N}=23.5\\ \\mathrm{N}.\\quad (b)\\ d>\\dfrac{3h}{2}.\\quad (c)$ A more realistic model could include friction at the pulley.","steps":[{"title":"Use the trig ratios","body":"Since $\\tan\\alpha=\\dfrac34$, $\\sin\\alpha=\\dfrac35$ and $\\cos\\alpha=\\dfrac45$."},{"title":"Find friction on A","body":"For A, $R=2g\\cos\\alpha=\\dfrac{8g}{5}$. With coefficient $\\dfrac14$, friction is $F=\\dfrac14R=\\dfrac{2g}{5}$."},{"title":"Equation for A","body":"A moves up the plane. Taking up the plane as positive: $T-2g\\sin\\alpha-F=2a$."},{"title":"Simplify A's equation","body":"$T-2g\\cdot\\dfrac35-\\dfrac{2g}{5}=2a$, so $T-\\dfrac{8g}{5}=2a$."},{"title":"Equation for B","body":"B descends. Taking downward as positive: $4g-T=4a$."},{"title":"Solve for T","body":"From A, $T=2a+\\dfrac{8g}{5}$. From B, $T=4g-4a$. Equating gives $6a=\\dfrac{12g}{5}$, so $a=\\dfrac{2g}{5}$. Then $T=4g-4\\left(\\dfrac{2g}{5}\\right)=\\dfrac{12g}{5}$ N."},{"title":"Find speed when B reaches the ground","body":"Before B hits the ground, both particles move distance $h$ from rest with acceleration $\\dfrac{2g}{5}$. Thus $v^2=2\\left(\\dfrac{2g}{5}\\right)h=\\dfrac{4gh}{5}$."},{"title":"Find extra distance after B stops","body":"After B hits the ground, A continues up the plane. The forces down the plane on A are $2g\\sin\\alpha+F=\\dfrac{6g}{5}+\\dfrac{2g}{5}=\\dfrac{8g}{5}$, so its deceleration is $\\dfrac{4g}{5}$."},{"title":"Calculate extra distance","body":"Let the extra distance be $s$. Then $0=\\dfrac{4gh}{5}-2\\left(\\dfrac{4g}{5}\\right)s$, so $s=\\dfrac{h}{2}$."},{"title":"Find the range for d","body":"A travels total distance $h+\\dfrac{h}{2}=\\dfrac{3h}{2}$ before stopping. Since it comes to rest before reaching the pulley, $d>\\dfrac{3h}{2}$."},{"title":"Name a more realistic factor","body":"A more realistic model could include friction at the pulley."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_MayJune_Q06","year":2021,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2021","qNo":6,"marks":13,"topic":"08_ResolvingForcesInclinedPlanes","topicName":"Resolving Forces, Inclined Planes","primaryTopic":"08_ResolvingForcesInclinedPlanes","primaryTopicName":"Resolving Forces, Inclined Planes","secondaryTopics":["04_ConstantAcceleration1D"],"secondaryTopicNames":["Constant Acceleration in 1D"],"topics":["08_ResolvingForcesInclinedPlanes","04_ConstantAcceleration1D"],"topicNames":["Resolving Forces, Inclined Planes","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2021_MayJune_Q06_M13_08_ResolvingForcesInclinedPlanes.png","downloadName":"WME01-01_Y2021_MayJune_Q06_M13_08_ResolvingForcesInclinedPlanes.png","finalAnswer":"$(a)\\ F=13.6\\ \\mathrm{N}.\\quad (b)\\ AB=2.07\\ \\mathrm{m}\\approx2.1\\ \\mathrm{m}.\\quad (c)\\ BC=8.29\\ \\mathrm{m}\\approx8.3\\ \\mathrm{m}$.","steps":[{"title":"Use the trig ratios","body":"Since $\\tan\\theta=\\dfrac5{12}$, $\\sin\\theta=\\dfrac5{13}$ and $\\cos\\theta=\\dfrac{12}{13}$."},{"title":"Find the normal reaction","body":"$R=6g\\cos\\theta=6g\\cdot\\dfrac{12}{13}=\\dfrac{72g}{13}$."},{"title":"Find friction","body":"With $\\mu=\\dfrac14$, $F=\\dfrac14R=\\dfrac{18g}{13}=13.6\\ \\mathrm{N}$ approximately."},{"title":"Find acceleration while moving up","body":"While moving up, both friction and the component of weight act down the plane. Taking up the plane as positive: $6a=-6g\\sin\\theta-F$."},{"title":"Simplify the upward acceleration","body":"$6a=-6g\\cdot\\dfrac5{13}-\\dfrac{18g}{13}=-\\dfrac{48g}{13}$, so $a=-\\dfrac{8g}{13}$."},{"title":"Find AB","body":"Use $v^2=u^2+2as$ with $u=5$ and $v=0$: $0=25+2\\left(-\\dfrac{8g}{13}\\right)AB$. Hence $AB=2.07\\ldots\\ \\mathrm{m}$."},{"title":"Find acceleration while sliding down","body":"When sliding down, friction acts up the plane. Taking down the plane as positive: $6a=6g\\sin\\theta-F=\\dfrac{30g}{13}-\\dfrac{18g}{13}=\\dfrac{12g}{13}$. Thus $a=\\dfrac{2g}{13}$."},{"title":"Find BC","body":"Starting from rest at B and reaching speed $5$ at C: $25=2\\left(\\dfrac{2g}{13}\\right)BC$. Hence $BC=8.29\\ldots\\ \\mathrm{m}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_Oct_Q07","year":2021,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2021","qNo":7,"marks":14,"topic":"08_ResolvingForcesInclinedPlanes","topicName":"Resolving Forces, Inclined Planes","primaryTopic":"08_ResolvingForcesInclinedPlanes","primaryTopicName":"Resolving Forces, Inclined Planes","secondaryTopics":["07_NewtonsSecondLaw"],"secondaryTopicNames":["Newton's Second Law"],"topics":["08_ResolvingForcesInclinedPlanes","07_NewtonsSecondLaw"],"topicNames":["Resolving Forces, Inclined Planes","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2021_Oct_Q07_M14_08_ResolvingForcesInclinedPlanes.png","downloadName":"WME01-01_Y2021_Oct_Q07_M14_08_ResolvingForcesInclinedPlanes.png","finalAnswer":"$(a)(i)\\ T-2mg\\sin\\alpha-F=2ma.\\quad (a)(ii)\\ 3mg-T=3ma.\\quad (b)\\ a=\\dfrac{g}{5}.\\quad (c)\\ \\text{resultant}=\\dfrac{48\\sqrt5}{25}mg.\\quad (d)$ The tension is the same on both sides of the pulley.","steps":[{"title":"Equation for A","body":"A moves up the plane, so friction and the component of weight act down the plane. Taking up the plane as positive: $T-2mg\\sin\\alpha-F=2ma$."},{"title":"Equation for B","body":"B moves downward. Taking downward as positive: $3mg-T=3ma$."},{"title":"Find friction on A","body":"Since $\\tan\\alpha=\\dfrac34$, $\\sin\\alpha=\\dfrac35$ and $\\cos\\alpha=\\dfrac45$. The normal reaction on A is $R=2mg\\cos\\alpha=\\dfrac{8mg}{5}$, so $F=\\dfrac12R=\\dfrac{4mg}{5}$."},{"title":"Simplify A's equation","body":"$T-2mg\\cdot\\dfrac35-\\dfrac{4mg}{5}=2ma$, so $T-2mg=2ma$."},{"title":"Solve with B's equation","body":"From B, $T=3mg-3ma$. Substitute into $T-2mg=2ma$: $3mg-3ma-2mg=2ma$. Thus $mg=5ma$ and $a=\\dfrac{g}{5}$."},{"title":"Find the tension","body":"Using $3mg-T=3m\\left(\\dfrac{g}{5}\\right)$ gives $T=3mg-\\dfrac{3mg}{5}=\\dfrac{12mg}{5}$."},{"title":"Find the pulley resultant","body":"The two tensions are one vertical and one along the plane. Components of the resultant are $T\\cos\\alpha$ horizontally and $T+T\\sin\\alpha$ vertically."},{"title":"Calculate the magnitude","body":"Resultant $=T\\sqrt{\\cos^2\\alpha+(1+\\sin\\alpha)^2}=T\\sqrt{(\\tfrac45)^2+(\\tfrac85)^2}=\\dfrac{4\\sqrt5}{5}T$. With $T=\\dfrac{12mg}{5}$, this is $\\dfrac{48\\sqrt5}{25}mg$."},{"title":"Use the smooth pulley information","body":"The pulley is smooth, so the tension is the same on both sides of the pulley."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_Jan_Q05","year":2022,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2022","qNo":5,"marks":8,"topic":"08_ResolvingForcesInclinedPlanes","topicName":"Resolving Forces, Inclined Planes","primaryTopic":"08_ResolvingForcesInclinedPlanes","primaryTopicName":"Resolving Forces, Inclined Planes","secondaryTopics":["06_Forces"],"secondaryTopicNames":["Forces"],"topics":["08_ResolvingForcesInclinedPlanes","06_Forces"],"topicNames":["Resolving Forces, Inclined Planes","Forces"],"image":"ial/wme01/questions/WME01-01_Y2022_Jan_Q05_M08_08_ResolvingForcesInclinedPlanes.png","downloadName":"WME01-01_Y2022_Jan_Q05_M08_08_ResolvingForcesInclinedPlanes.png","finalAnswer":"$\\mu=\\dfrac14$.","steps":[{"title":"Use the trig ratios","body":"Since $\\tan\\alpha=\\dfrac34$, $\\sin\\alpha=\\dfrac35$ and $\\cos\\alpha=\\dfrac45$."},{"title":"Resolve perpendicular to the plane","body":"The force $X$ acts along the plane, so the normal reaction is $R=mg\\cos\\alpha=\\dfrac45mg$."},{"title":"Use friction","body":"The limiting friction is $F=\\mu R=\\dfrac45\\mu mg$."},{"title":"Use the sliding-up condition","body":"When $X=2P$, the particle is about to slide up, so friction acts down the plane. Hence $2P=mg\\sin\\alpha+F=\\dfrac35mg+\\dfrac45\\mu mg$."},{"title":"Use the sliding-down condition","body":"When $X=P$, the particle is about to slide down, so friction acts up the plane. Hence $P+F=mg\\sin\\alpha$, so $P=\\dfrac35mg-\\dfrac45\\mu mg$."},{"title":"Eliminate P","body":"Double the second equation: $2P=\\dfrac65mg-\\dfrac85\\mu mg$. This equals the first expression for $2P$."},{"title":"Solve for mu","body":"$\\dfrac65mg-\\dfrac85\\mu mg=\\dfrac35mg+\\dfrac45\\mu mg$. Cancel $mg$ and multiply by $5$: $6-8\\mu=3+4\\mu$. Hence $3=12\\mu$ and $\\mu=\\dfrac14$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_Jan_Q07","year":2022,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2022","qNo":7,"marks":13,"topic":"08_ResolvingForcesInclinedPlanes","topicName":"Resolving Forces, Inclined Planes","primaryTopic":"08_ResolvingForcesInclinedPlanes","primaryTopicName":"Resolving Forces, Inclined Planes","secondaryTopics":["07_NewtonsSecondLaw"],"secondaryTopicNames":["Newton's Second Law"],"topics":["08_ResolvingForcesInclinedPlanes","07_NewtonsSecondLaw"],"topicNames":["Resolving Forces, Inclined Planes","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2022_Jan_Q07_M13_08_ResolvingForcesInclinedPlanes.png","downloadName":"WME01-01_Y2022_Jan_Q07_M13_08_ResolvingForcesInclinedPlanes.png","finalAnswer":"$(a)\\ T=ma.\\quad (b)\\ T=\\dfrac{8}{25}mg.\\quad (c)\\ \\text{resultant}=\\dfrac{8\\sqrt{10}}{125}mg.\\quad (d)$ Same tension was used on both sides of the pulley.","steps":[{"title":"Write the equation for Q","body":"Q lies on a smooth horizontal plane. The only horizontal force on Q is the tension, so $T=ma$."},{"title":"Use the trig ratios","body":"Since $\\tan\\alpha=\\dfrac34$, $\\sin\\alpha=\\dfrac35$ and $\\cos\\alpha=\\dfrac45$."},{"title":"Find friction on P","body":"For P, $R=4mg\\cos\\alpha=4mg\\cdot\\dfrac45=\\dfrac{16mg}{5}$. With coefficient $\\dfrac14$, friction is $F=\\dfrac14R=\\dfrac{4mg}{5}$."},{"title":"Apply Newtons second law to P","body":"P moves down the plane. Taking down the plane as positive: $4mg\\sin\\alpha-T-F=4ma$."},{"title":"Substitute values","body":"$4mg\\cdot\\dfrac35-T-\\dfrac{4mg}{5}=4ma$, so $\\dfrac{8mg}{5}-T=4ma$."},{"title":"Use T = ma","body":"From Q, $a=\\dfrac{T}{m}$. Substitute into the equation for P: $\\dfrac{8mg}{5}-T=4T$."},{"title":"Find T","body":"$\\dfrac{8mg}{5}=5T$, so $T=\\dfrac{8}{25}mg$."},{"title":"Find the pulley resultant","body":"The pulley is pulled by two tensions of magnitude $T$: one horizontal and one along the inclined string. Their resultant has components $T-T\\cos\\alpha$ horizontally and $T\\sin\\alpha$ vertically."},{"title":"Calculate the resultant","body":"Magnitude $=\\sqrt{(T-T\\cos\\alpha)^2+(T\\sin\\alpha)^2}=T\\sqrt{(1-\\tfrac45)^2+(\\tfrac35)^2}=\\dfrac{T}{5}\\sqrt{10}$. With $T=\\dfrac{8}{25}mg$, the resultant is $\\dfrac{8\\sqrt{10}}{125}mg$."},{"title":"Use the light-string model","body":"The string is light, so the tension can be treated as the same on the P side and the Q side of the pulley."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_Oct_Q03","year":2022,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2022","qNo":3,"marks":11,"topic":"08_ResolvingForcesInclinedPlanes","topicName":"Resolving Forces, Inclined Planes","primaryTopic":"08_ResolvingForcesInclinedPlanes","primaryTopicName":"Resolving Forces, Inclined Planes","secondaryTopics":["06_Forces"],"secondaryTopicNames":["Forces"],"topics":["08_ResolvingForcesInclinedPlanes","06_Forces"],"topicNames":["Resolving Forces, Inclined Planes","Forces"],"image":"ial/wme01/questions/WME01-01_Y2022_Oct_Q03_M11_08_ResolvingForcesInclinedPlanes.png","downloadName":"WME01-01_Y2022_Oct_Q03_M11_08_ResolvingForcesInclinedPlanes.png","finalAnswer":"$(a)$ When $X=14.7$, $F=0$. $(b)\\ X_{\\min}=\\dfrac{4g}{11}=3.56\\ldots\\ \\mathrm{N}$.","steps":[{"title":"Use the trig ratios","body":"Since $\\tan\\alpha=\\dfrac34$, $\\sin\\alpha=\\dfrac35$ and $\\cos\\alpha=\\dfrac45$."},{"title":"Check the no-friction case","body":"If there is no friction, the component of the horizontal force up the plane balances the component of weight down the plane: $X\\cos\\alpha=2g\\sin\\alpha$."},{"title":"Substitute X = 14.7","body":"$14.7\\cdot\\dfrac45=11.76$, and $2(9.8)\\cdot\\dfrac35=11.76$. The components balance exactly, so the frictional force is zero."},{"title":"Set the direction for smallest X","body":"For the smallest possible $X$, the particle is about to slide down the plane, so friction acts up the plane."},{"title":"Resolve perpendicular to the plane","body":"The horizontal force increases the normal reaction, so $R=2g\\cos\\alpha+X\\sin\\alpha$."},{"title":"Use limiting friction","body":"With $\\mu=0.5$, the limiting friction is $F=0.5R=0.5(2g\\cos\\alpha+X\\sin\\alpha)$."},{"title":"Resolve along the plane","body":"At the limiting case, $X\\cos\\alpha+F=2g\\sin\\alpha$."},{"title":"Solve for X","body":"Substitute the exact trig values: $\\dfrac45X+0.5\\left(2g\\cdot\\dfrac45+X\\cdot\\dfrac35\\right)=2g\\cdot\\dfrac35$. This gives $\\dfrac{11}{10}X+\\dfrac{4g}{5}=\\dfrac{6g}{5}$, so $X=\\dfrac{4g}{11}=3.56\\ldots\\ \\mathrm{N}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2023_Jan_Q08","year":2023,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2023","qNo":8,"marks":15,"topic":"08_ResolvingForcesInclinedPlanes","topicName":"Resolving Forces, Inclined Planes","primaryTopic":"08_ResolvingForcesInclinedPlanes","primaryTopicName":"Resolving Forces, Inclined Planes","secondaryTopics":["07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"secondaryTopicNames":["Newton's Second Law","Constant Acceleration in 1D"],"topics":["08_ResolvingForcesInclinedPlanes","07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"topicNames":["Resolving Forces, Inclined Planes","Newton's Second Law","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2023_Jan_Q08_M15_08_ResolvingForcesInclinedPlanes.png","downloadName":"WME01-01_Y2023_Jan_Q08_M15_08_ResolvingForcesInclinedPlanes.png","finalAnswer":"$(a)\\ a=1.18\\ \\mathrm{m\\,s^{-2}}\\ \\text{up the plane}.\\quad (b)\\ v=3.98\\ \\mathrm{m\\,s^{-1}}\\approx4.0\\ \\mathrm{m\\,s^{-1}}.\\quad (c)$ P will not remain at rest at C.","steps":[{"title":"Resolve perpendicular to the plane","body":"The force of $18$ N is angled away from the plane, so $R+18\\sin40^\\circ=2g\\cos30^\\circ$. Hence $R=2g\\cos30^\\circ-18\\sin40^\\circ$."},{"title":"Use friction","body":"The parcel moves up the plane, so friction acts down the plane. With $\\mu=0.3$, $F=0.3R$."},{"title":"Resolve parallel to the plane","body":"Taking up the plane as positive: $18\\cos40^\\circ-F-2g\\sin30^\\circ=2a$."},{"title":"Substitute for R and F","body":"$18\\cos40^\\circ-0.3(2g\\cos30^\\circ-18\\sin40^\\circ)-2g\\sin30^\\circ=2a$."},{"title":"Find the acceleration","body":"Using $g=9.8$, this gives $a=1.18\\ldots\\ \\mathrm{m\\,s^{-2}}$ up the plane."},{"title":"Find the speed at B","body":"From A to B, $u=2$, $s=5$ and $a=1.18\\ldots$. Use $v^2=u^2+2as$: $v^2=2^2+2(1.18\\ldots)(5)$."},{"title":"State the speed","body":"$v=3.98\\ldots\\ \\mathrm{m\\,s^{-1}}$, about $4.0\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Check rest after the force is removed","body":"At C, with the pulling force removed, $R=2g\\cos30^\\circ$. The maximum friction is $0.3R=0.3(2g\\cos30^\\circ)=5.09\\ldots\\ \\mathrm{N}$."},{"title":"Compare with the downslope weight component","body":"The component of weight down the plane is $2g\\sin30^\\circ=9.8\\ \\mathrm{N}$. Since $9.8>5.09\\ldots$, friction is not large enough to hold P at rest, so P will not remain at rest at C."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2023_Oct_Q07","year":2023,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2023","qNo":7,"marks":13,"topic":"08_ResolvingForcesInclinedPlanes","topicName":"Resolving Forces, Inclined Planes","primaryTopic":"08_ResolvingForcesInclinedPlanes","primaryTopicName":"Resolving Forces, Inclined Planes","secondaryTopics":["07_NewtonsSecondLaw"],"secondaryTopicNames":["Newton's Second Law"],"topics":["08_ResolvingForcesInclinedPlanes","07_NewtonsSecondLaw"],"topicNames":["Resolving Forces, Inclined Planes","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2023_Oct_Q07_M13_08_ResolvingForcesInclinedPlanes.png","downloadName":"WME01-01_Y2023_Oct_Q07_M13_08_ResolvingForcesInclinedPlanes.png","finalAnswer":"$(a)(i)\\ a=\\dfrac{11g}{15}.\\quad (a)(ii)\\ k=5.\\quad (b)\\ \\text{resultant}=\\dfrac{32}{15}mg$.","steps":[{"title":"Use the trig ratios","body":"Given $\\tan\\alpha=\\dfrac{7}{24}$, use $\\sin\\alpha=\\dfrac{7}{25}$ and $\\cos\\alpha=\\dfrac{24}{25}$."},{"title":"Find friction on A","body":"For block A, $R=mg\\cos\\alpha=\\dfrac{24mg}{25}$. Since $\\mu=\\dfrac13$, friction is $F=\\dfrac13R=\\dfrac{8mg}{25}$."},{"title":"Apply Newtons second law to A","body":"A moves up the plane, so friction and the component of weight act down the plane. Taking up the plane as positive: $T-mg\\sin\\alpha-F=ma$."},{"title":"Find the acceleration","body":"Substitute $T=\\dfrac43mg$, $mg\\sin\\alpha=\\dfrac{7mg}{25}$ and $F=\\dfrac{8mg}{25}$: $ma=\\dfrac43mg-\\dfrac{15mg}{25}=\\left(\\dfrac43-\\dfrac35\\right)mg=\\dfrac{11mg}{15}$. Hence $a=\\dfrac{11g}{15}$."},{"title":"Apply Newtons second law to B","body":"Block B moves downwards with the same acceleration. Taking downward as positive: $kmg-T=kma$."},{"title":"Find k","body":"Substitute $T=\\dfrac43mg$ and $a=\\dfrac{11g}{15}$: $kmg-\\dfrac43mg=k m\\dfrac{11g}{15}$. Divide by $mg$ to get $k-\\dfrac43=\\dfrac{11k}{15}$, so $15k-20=11k$ and $k=5$."},{"title":"Resolve the force on the pulley","body":"The pulley is pulled by two tensions of magnitude $T$. One is vertical and the other is along the plane. The horizontal component of the resultant is $T\\cos\\alpha$ and the vertical component is $T+T\\sin\\alpha$."},{"title":"Find the resultant","body":"The magnitude is $T\\sqrt{\\cos^2\\alpha+(1+\\sin\\alpha)^2}$. With $\\sin\\alpha=\\dfrac{7}{25}$ and $\\cos\\alpha=\\dfrac{24}{25}$, this is $T\\sqrt{\\dfrac{576}{625}+\\dfrac{1024}{625}}=\\dfrac{8T}{5}$. Since $T=\\dfrac43mg$, the resultant is $\\dfrac{32}{15}mg$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2024_Jan_Q08","year":2024,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2024","qNo":8,"marks":12,"topic":"08_ResolvingForcesInclinedPlanes","topicName":"Resolving Forces, Inclined Planes","primaryTopic":"08_ResolvingForcesInclinedPlanes","primaryTopicName":"Resolving Forces, Inclined Planes","secondaryTopics":["04_ConstantAcceleration1D"],"secondaryTopicNames":["Constant Acceleration in 1D"],"topics":["08_ResolvingForcesInclinedPlanes","04_ConstantAcceleration1D"],"topicNames":["Resolving Forces, Inclined Planes","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2024_Jan_Q08_M12_08_ResolvingForcesInclinedPlanes.png","downloadName":"WME01-01_Y2024_Jan_Q08_M12_08_ResolvingForcesInclinedPlanes.png","finalAnswer":"$(a)\\ \\mu=\\dfrac18.\\quad (b)\\ V=2.05\\ \\mathrm{m\\,s^{-1}}\\ \\text{approximately}$.","steps":[{"title":"Use the trig ratios","body":"Given $\\tan\\alpha=\\dfrac{5}{12}$, use $\\sin\\alpha=\\dfrac{5}{13}$ and $\\cos\\alpha=\\dfrac{12}{13}$."},{"title":"Find the tension","body":"Q has mass $0.5m$ and the system is in equilibrium, so the tension is $T=0.5mg$."},{"title":"Resolve P parallel to the plane","body":"P is on the point of slipping up the plane, so friction acts down the plane. Along the plane, $T=mg\\sin\\alpha+F$."},{"title":"Find the friction force","body":"$F=T-mg\\sin\\alpha=\\dfrac12mg-\\dfrac{5}{13}mg=\\dfrac{3}{26}mg$."},{"title":"Find the normal reaction and mu","body":"$R=mg\\cos\\alpha=\\dfrac{12}{13}mg$. Since $F=\\mu R$, $\\mu=\\dfrac{3mg/26}{12mg/13}=\\dfrac18$."},{"title":"Find acceleration after the string breaks","body":"P moves down the plane, so friction acts up the plane. The resultant down the plane is $mg\\sin\\alpha-F=\\dfrac{5}{13}mg-\\dfrac18\\cdot\\dfrac{12}{13}mg=\\dfrac{7}{26}mg$."},{"title":"Apply Newtons second law","body":"As P has mass $m$, $a=\\dfrac{7g}{26}$ down the plane."},{"title":"Find V","body":"From rest over $0.8$ m, $V^2=2\\left(\\dfrac{7g}{26}\\right)(0.8)$. With $g=9.8$, $V=2.05\\ \\mathrm{m\\,s^{-1}}$ to 3 significant figures."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2024_MayJune_Q06","year":2024,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2024","qNo":6,"marks":12,"topic":"08_ResolvingForcesInclinedPlanes","topicName":"Resolving Forces, Inclined Planes","primaryTopic":"08_ResolvingForcesInclinedPlanes","primaryTopicName":"Resolving Forces, Inclined Planes","secondaryTopics":["04_ConstantAcceleration1D"],"secondaryTopicNames":["Constant Acceleration in 1D"],"topics":["08_ResolvingForcesInclinedPlanes","04_ConstantAcceleration1D"],"topicNames":["Resolving Forces, Inclined Planes","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2024_MayJune_Q06_M12_08_ResolvingForcesInclinedPlanes.png","downloadName":"WME01-01_Y2024_MayJune_Q06_M12_08_ResolvingForcesInclinedPlanes.png","finalAnswer":"$(a)\\ T=\\dfrac{mg}{3}.\\quad (b)\\ d=\\dfrac{9u^2}{8g}$.","steps":[{"title":"Use the trig ratios","body":"Given $\\tan\\theta=\\dfrac34$, use $\\sin\\theta=\\dfrac35$ and $\\cos\\theta=\\dfrac45$."},{"title":"Resolve vertically","body":"The box moves at constant speed, so it is in equilibrium. Vertically, $R+T\\sin\\theta=mg$, hence $R=mg-T\\sin\\theta$."},{"title":"Resolve horizontally","body":"Horizontally, the tension component balances friction: $T\\cos\\theta=F$."},{"title":"Use friction","body":"With $\\mu=\\dfrac13$, $F=\\dfrac13R$. Therefore $T\\cos\\theta=\\dfrac13(mg-T\\sin\\theta)$."},{"title":"Find T","body":"Substitute $\\sin\\theta=\\dfrac35$ and $\\cos\\theta=\\dfrac45$: $\\dfrac45T=\\dfrac13\\left(mg-\\dfrac35T\\right)$. This gives $\\dfrac45T=\\dfrac{mg}{3}-\\dfrac15T$, so $T=\\dfrac{mg}{3}$."},{"title":"Find the deceleration when the rope is removed","body":"On the horizontal plane without the rope, $R=mg$ and friction is $\\dfrac13mg$. Hence the acceleration is $-\\dfrac{g}{3}$."},{"title":"Use SUVAT to find d","body":"When the speed has fallen from $u$ to $\\dfrac12u$, use $v^2=u^2+2as$: $\\left(\\dfrac{u}{2}\\right)^2=u^2+2\\left(-\\dfrac{g}{3}\\right)d$."},{"title":"Solve for d","body":"$\\dfrac{u^2}{4}=u^2-\\dfrac{2gd}{3}$, so $\\dfrac{2gd}{3}=\\dfrac{3u^2}{4}$ and $d=\\dfrac{9u^2}{8g}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2024_MayJune_Q08","year":2024,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2024","qNo":8,"marks":15,"topic":"08_ResolvingForcesInclinedPlanes","topicName":"Resolving Forces, Inclined Planes","primaryTopic":"08_ResolvingForcesInclinedPlanes","primaryTopicName":"Resolving Forces, Inclined Planes","secondaryTopics":["07_NewtonsSecondLaw"],"secondaryTopicNames":["Newton's Second Law"],"topics":["08_ResolvingForcesInclinedPlanes","07_NewtonsSecondLaw"],"topicNames":["Resolving Forces, Inclined Planes","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2024_MayJune_Q08_M15_08_ResolvingForcesInclinedPlanes.png","downloadName":"WME01-01_Y2024_MayJune_Q08_M15_08_ResolvingForcesInclinedPlanes.png","finalAnswer":"$(a)\\ F=\\dfrac{22}{39}mg.\\quad (b)\\ 3mg-T=3ma.\\quad (c)\\ a=\\dfrac{g}{3}.\\quad (d)\\ \\text{total distance}=\\dfrac{3h}{2}$.","steps":[{"title":"Use the trig ratios","body":"Here $\\tan\\alpha=\\dfrac{5}{12}$, so $\\sin\\alpha=\\dfrac{5}{13}$ and $\\cos\\alpha=\\dfrac{12}{13}$."},{"title":"Show the frictional force on A","body":"For A, $R=2mg\\cos\\alpha=2mg\\cdot\\dfrac{12}{13}=\\dfrac{24mg}{13}$. Since $\\mu=\\dfrac{11}{36}$, $F=\\mu R=\\dfrac{11}{36}\\cdot\\dfrac{24mg}{13}=\\dfrac{22mg}{39}$."},{"title":"Write the equation for B","body":"B moves down as A moves up. Taking downward as positive for B: $3mg-T=3ma$."},{"title":"Write the equation for A","body":"Taking up the plane as positive for A: $T-2mg\\sin\\alpha-F=2ma$. Substituting $\\sin\\alpha=\\dfrac{5}{13}$ and $F=\\dfrac{22mg}{39}$ gives $T-\\dfrac{10mg}{13}-\\dfrac{22mg}{39}=2ma$."},{"title":"Show the acceleration","body":"From B, $T=3mg-3ma$. Substitute into A equation: $3mg-3ma-\\dfrac{10mg}{13}-\\dfrac{22mg}{39}=2ma$. The constant part is $\\dfrac{5mg}{3}$, so $\\dfrac{5mg}{3}=5ma$ and $a=\\dfrac{g}{3}$."},{"title":"Find the speed when B reaches the ground","body":"While B descends distance $h$, A moves distance $h$ up the plane from rest with acceleration $g/3$. Thus $v^2=2\\left(\\dfrac{g}{3}\\right)h=\\dfrac{2gh}{3}$."},{"title":"Find the later deceleration of A","body":"After B reaches the ground, the string no longer pulls A. The forces down the plane on A are $2mg\\sin\\alpha+F=\\dfrac{10mg}{13}+\\dfrac{22mg}{39}=\\dfrac{4mg}{3}$. Since A has mass $2m$, its deceleration is $\\dfrac{2g}{3}$."},{"title":"Find the extra distance and total distance","body":"Let the extra distance be $d$. Using $0=v^2-2\\left(\\dfrac{2g}{3}\\right)d$ with $v^2=\\dfrac{2gh}{3}$ gives $d=\\dfrac{h}{2}$. Total distance travelled by A is $h+\\dfrac{h}{2}=\\dfrac{3h}{2}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2024_Oct_Q06","year":2024,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2024","qNo":6,"marks":12,"topic":"08_ResolvingForcesInclinedPlanes","topicName":"Resolving Forces, Inclined Planes","primaryTopic":"08_ResolvingForcesInclinedPlanes","primaryTopicName":"Resolving Forces, Inclined Planes","secondaryTopics":["04_ConstantAcceleration1D"],"secondaryTopicNames":["Constant Acceleration in 1D"],"topics":["08_ResolvingForcesInclinedPlanes","04_ConstantAcceleration1D"],"topicNames":["Resolving Forces, Inclined Planes","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2024_Oct_Q06_M12_08_ResolvingForcesInclinedPlanes.png","downloadName":"WME01-01_Y2024_Oct_Q06_M12_08_ResolvingForcesInclinedPlanes.png","finalAnswer":"$(a)\\ H=\\dfrac{40g}{19}\\ \\mathrm{N}\\approx20.6\\ \\mathrm{N}.\\quad (b)\\ T=0.875\\ \\mathrm{s}$.","steps":[{"title":"Use the triangle for alpha","body":"From $\\tan\\alpha=\\dfrac34$, use $\\sin\\alpha=\\dfrac35$ and $\\cos\\alpha=\\dfrac45$."},{"title":"Resolve perpendicular to the plane","body":"The horizontal force has a component into the plane, so $R=5g\\cos\\alpha+H\\sin\\alpha=4g+\\dfrac35H$."},{"title":"Resolve parallel for the smallest H","body":"For the smallest $H$, the particle is on the point of sliding down, so friction acts up the plane. Parallel to the plane, $H\\cos\\alpha+F=5g\\sin\\alpha$."},{"title":"Use friction to find H","body":"With $F=\\dfrac14R$, the parallel equation becomes $\\dfrac45H+\\dfrac14\\left(4g+\\dfrac35H\\right)=3g$. Hence $0.95H+g=3g$, so $H=\\dfrac{40g}{19}=20.6\\ \\mathrm{N}$."},{"title":"Find the acceleration after H is removed","body":"When $H$ is removed, $R=5g\\cos\\alpha=4g$ and friction is $\\dfrac14R=g$. The component of weight down the plane is $5g\\sin\\alpha=3g$, so the resultant down the plane is $2g$."},{"title":"Apply Newtons second law","body":"$2g=5a$, so $a=\\dfrac{2g}{5}=3.92\\ \\mathrm{m\\,s^{-2}}$ down the plane."},{"title":"Find T from the displacement","body":"From rest, the particle moves $1.5$ m with acceleration $2g/5$. Using $s=\\dfrac12at^2$: $1.5=\\dfrac12\\left(\\dfrac{2g}{5}\\right)T^2=\\dfrac{g}{5}T^2$. Thus $T=\\sqrt{\\dfrac{7.5}{9.8}}=0.875\\ \\mathrm{s}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2025_Jan_Q06","year":2025,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2025","qNo":6,"marks":12,"topic":"08_ResolvingForcesInclinedPlanes","topicName":"Resolving Forces, Inclined Planes","primaryTopic":"08_ResolvingForcesInclinedPlanes","primaryTopicName":"Resolving Forces, Inclined Planes","secondaryTopics":["06_Forces"],"secondaryTopicNames":["Forces"],"topics":["08_ResolvingForcesInclinedPlanes","06_Forces"],"topicNames":["Resolving Forces, Inclined Planes","Forces"],"image":"ial/wme01/questions/WME01-01_Y2025_Jan_Q06_M12_08_ResolvingForcesInclinedPlanes.png","downloadName":"WME01-01_Y2025_Jan_Q06_M12_08_ResolvingForcesInclinedPlanes.png","finalAnswer":"$(a)\\ F=0.75mg\\cos\\alpha-mg\\sin\\alpha.\\quad (b)\\ \\tan\\alpha=\\dfrac25.\\quad (c)\\ P\\ \\text{remains at rest}$.","steps":[{"title":"Resolve parallel to the plane","body":"P is on the point of moving up the plane, so friction acts down the plane. The tension has component $0.75mg\\cos\\alpha$ up the plane, and the weight component is $mg\\sin\\alpha$ down the plane."},{"title":"Find the frictional force","body":"For equilibrium parallel to the plane, $0.75mg\\cos\\alpha=mg\\sin\\alpha+F$. Hence $F=0.75mg\\cos\\alpha-mg\\sin\\alpha$."},{"title":"Resolve perpendicular to the plane","body":"The string has a component away from the plane, so $R=mg\\cos\\alpha-0.75mg\\sin\\alpha$."},{"title":"Use the coefficient of friction","body":"Given $\\mu=\\dfrac12$, limiting friction gives $F=\\dfrac12R$. Therefore $0.75mg\\cos\\alpha-mg\\sin\\alpha=\\dfrac12(mg\\cos\\alpha-0.75mg\\sin\\alpha)$."},{"title":"Show the tangent result","body":"Divide by $mg$ and collect terms: $0.75\\cos\\alpha-\\sin\\alpha=0.5\\cos\\alpha-0.375\\sin\\alpha$. Thus $0.25\\cos\\alpha=0.625\\sin\\alpha$, so $\\tan\\alpha=\\dfrac{0.25}{0.625}=\\dfrac25$."},{"title":"Check what happens when the string breaks","body":"Without the string, $R=mg\\cos\\alpha$ and the maximum friction is $\\dfrac12mg\\cos\\alpha$. The component of weight down the plane is $mg\\sin\\alpha$."},{"title":"Compare friction with the downslope component","body":"Since $\\tan\\alpha=\\dfrac25<\\dfrac12$, we have $mg\\sin\\alpha<\\dfrac12mg\\cos\\alpha$. The available friction is large enough to hold P, so P remains at rest."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2025_MayJune_Q06","year":2025,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2025","qNo":6,"marks":11,"topic":"08_ResolvingForcesInclinedPlanes","topicName":"Resolving Forces, Inclined Planes","primaryTopic":"08_ResolvingForcesInclinedPlanes","primaryTopicName":"Resolving Forces, Inclined Planes","secondaryTopics":["04_ConstantAcceleration1D"],"secondaryTopicNames":["Constant Acceleration in 1D"],"topics":["08_ResolvingForcesInclinedPlanes","04_ConstantAcceleration1D"],"topicNames":["Resolving Forces, Inclined Planes","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2025_MayJune_Q06_M11_08_ResolvingForcesInclinedPlanes.png","downloadName":"WME01-01_Y2025_MayJune_Q06_M11_08_ResolvingForcesInclinedPlanes.png","finalAnswer":"$(a)\\ \\text{deceleration}=\\dfrac{4g}{5}$, as required. $(b)\\ U=4.85\\ \\mathrm{m\\,s^{-1}}$ (about $4.8\\ \\mathrm{m\\,s^{-1}}$). $(c)\\ X=7.84\\ \\mathrm{N}$ (about $7.8\\ \\mathrm{N}$).","steps":[{"title":"Part (a): Show deceleration = $\\frac{4g}{5}$ - Find exact trig values","body":"Given: $\\tan\\theta = \\frac{3}{4}$\n \n Using 3-4-5 right triangle:\n $\\sin\\theta = \\frac{3}{5}, \\quad \\cos\\theta = \\frac{4}{5}$"},{"title":"Part (a): Show deceleration = $\\frac{4g}{5}$ - Resolve perpendicular to plane","body":"$\\perp: \\sum F = 0$\n \n $R = mg\\cos\\theta$ $R = \\frac{4mg}{5}$"},{"title":"Part (a): Show deceleration = $\\frac{4g}{5}$ - Calculate friction force","body":"Package moving UP, so friction acts DOWN the plane:\n \n $F = \\mu R$ $= \\frac{1}{4} \\times \\frac{4mg}{5}$ $= \\frac{mg}{5}$"},{"title":"Part (a): Show deceleration = $\\frac{4g}{5}$ - Resolve parallel to plane","body":"Taking up the plane as positive:\n \n $\\parallel: \\sum F = ma$\n \n $-mg\\sin\\theta - F = ma$ $-mg \\times \\frac{3}{5} - \\frac{mg}{5} = ma$ $-\\frac{3mg}{5} - \\frac{mg}{5} = ma$ $-\\frac{4mg}{5} = ma$ $a = -\\frac{4g}{5}$\n \n Deceleration = $\\left|-\\frac{4g}{5}\\right| = \\frac{4g}{5}$"},{"title":"Part (b): Find initial speed U - Identify SUVAT variables","body":"Package projected up plane, comes to rest at B:\n \n ; $u = U$ m s$^{-1}$ (unknown)\n ; $v = 0$ m s$^{-1}$ (comes to rest)\n ; $a = -\\frac{4g}{5}$ m s$^{-2}$ (from part a)\n ; $s = 1.5$ m"},{"title":"Part (b): Find initial speed U - Apply $v^2 = u^2 + 2as$","body":"$v^2 = u^2 + 2as$\n \n $0^2 = U^2 + 2\\left(-\\frac{4g}{5}\\right)(1.5)$ $0 = U^2 - 2 \\times \\frac{4 \\times 9.8}{5} \\times 1.5$ $0 = U^2 - \\frac{8 \\times 9.8 \\times 1.5}{5}$ $0 = U^2 - 23.52$ $U^2 = 23.52$ $U = 4.85 \\text{ m s}^{-1}$\n \n Or using exact form: $U = \\sqrt{2 \\times \\frac{4g}{5} \\times 1.5} = \\sqrt{\\frac{12g}{5}}$"},{"title":"Part (c): Find smallest value of X - Analyze forces when package at rest at B","body":"Package held at rest on slope by force X up the plane.\n \n Without X, package would slide down (component down > friction up).\n \n For MINIMUM X, friction acts UP the plane (at limiting friction)."},{"title":"Part (c): Find smallest value of X - Resolve perpendicular to plane","body":"Mass = 2 kg, so weight = $2g$ N\n \n $R = 2g\\cos\\theta$ $= 2g \\times \\frac{4}{5}$ $= \\frac{8g}{5} \\text{ N}$"},{"title":"Part (c): Find smallest value of X - Calculate friction","body":"Friction acts UP the plane (limiting):\n \n $F = \\mu R$ $= \\frac{1}{4} \\times \\frac{8g}{5}$ $= \\frac{2g}{5} \\text{ N}$"},{"title":"Part (c): Find smallest value of X - Resolve parallel to plane","body":"For equilibrium (package at rest):\n \n $\\parallel: \\sum F = 0$\n \n Taking up plane as positive:\n \n $X + F - 2g\\sin\\theta = 0$ $X + \\frac{2g}{5} - 2g \\times \\frac{3}{5} = 0$ $X + \\frac{2g}{5} - \\frac{6g}{5} = 0$ $X = \\frac{6g}{5} - \\frac{2g}{5}$ $X = \\frac{4g}{5}$ $X = \\frac{4 \\times 9.8}{5}$ $X = 7.84 \\text{ N}$"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2025_Oct_Q05","year":2025,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2025","qNo":5,"marks":13,"topic":"08_ResolvingForcesInclinedPlanes","topicName":"Resolving Forces, Inclined Planes","primaryTopic":"08_ResolvingForcesInclinedPlanes","primaryTopicName":"Resolving Forces, Inclined Planes","secondaryTopics":["07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"secondaryTopicNames":["Newton's Second Law","Constant Acceleration in 1D"],"topics":["08_ResolvingForcesInclinedPlanes","07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"topicNames":["Resolving Forces, Inclined Planes","Newton's Second Law","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2025_Oct_Q05_M13_08_ResolvingForcesInclinedPlanes.png","downloadName":"WME01-01_Y2025_Oct_Q05_M13_08_ResolvingForcesInclinedPlanes.png","finalAnswer":"$(a)\\ P=21.8\\ \\mathrm{N}.\\quad (b)\\ a=0.96\\ \\mathrm{m\\,s^{-2}}.\\quad (c)\\ v=1.7\\ \\mathrm{m\\,s^{-1}}$.","steps":[{"title":"Part (a): Find P when box is on point of sliding - Resolve vertically","body":"$\\uparrow: \\sum F_{\\text{vertical}} = 0$\n \n $R + P\\sin 30° = mg$ $R + 0.5P = 4 \\times 9.8$ $R = 39.2 - 0.5P \\quad \\text{...(1)}$"},{"title":"Part (a): Find P when box is on point of sliding - Apply friction law","body":"At limiting equilibrium (on point of sliding):\n \n $F = \\mu R$\n \n $F = \\frac{2}{3} \\times R$ $F = \\frac{2}{3}(39.2 - 0.5P)$ $F = 26.133... - \\frac{P}{3} \\quad \\text{...(2)}$"},{"title":"Part (a): Find P when box is on point of sliding - Resolve horizontally","body":"Box on point of sliding means $a = 0$:\n \n $\\rightarrow: \\sum F_{\\text{horizontal}} = 0$\n \n $P\\cos 30° = F$ $P \\times \\frac{\\sqrt{3}}{2} = 26.133... - \\frac{P}{3}$ $0.866P = 26.133 - 0.333P$ $0.866P + 0.333P = 26.133$ $1.199P = 26.133$ $P = 21.8 \\text{ N (3 s.f.)}$"},{"title":"Part (b): Find acceleration when P = 25 N - Find normal reaction when P = 25 N","body":"From equation (1) in part (a):\n \n $R = 39.2 - 0.5P$ $R = 39.2 - 0.5(25)$ $R = 39.2 - 12.5$ $R = 26.7 \\text{ N}$"},{"title":"Part (b): Find acceleration when P = 25 N - Find friction force","body":"Box is now moving, so:\n \n $F = \\mu R$ $F = \\frac{2}{3} \\times 26.7$ $F = 17.8 \\text{ N}$"},{"title":"Part (b): Find acceleration when P = 25 N - Resolve horizontally and apply F = ma","body":"$\\rightarrow: \\sum F = ma$\n \n $P\\cos 30° - F = ma$ $25 \\times 0.866 - 17.8 = 4a$ $21.65 - 17.8 = 4a$ $3.85 = 4a$ $a = 0.9625$ $a = 0.96 \\text{ m s}^{-2} \\text{ (2 s.f.)}$"},{"title":"Part (c): Find speed when box has moved 1.5 m - Identify SUVAT variables","body":"$u = 0$ m s$^{-1}$ (starts from rest)\n ; $a = 0.9625$ m s$^{-2}$ (from part b)\n ; $s = 1.5$ m\n ; $v = ?$"},{"title":"Part (c): Find speed when box has moved 1.5 m - Apply $v^2 = u^2 + 2as$","body":"$v^2 = u^2 + 2as$\n \n $v^2 = 0^2 + 2(0.9625)(1.5)$ $v^2 = 2.8875$ $v = \\sqrt{2.8875}$ $v = 1.699...$ $v = 1.7 \\text{ m s}^{-1} \\text{ (2 s.f.)}$"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2025_Oct_Q07","year":2025,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2025","qNo":7,"marks":14,"topic":"08_ResolvingForcesInclinedPlanes","topicName":"Resolving Forces, Inclined Planes","primaryTopic":"08_ResolvingForcesInclinedPlanes","primaryTopicName":"Resolving Forces, Inclined Planes","secondaryTopics":["07_NewtonsSecondLaw"],"secondaryTopicNames":["Newton's Second Law"],"topics":["08_ResolvingForcesInclinedPlanes","07_NewtonsSecondLaw"],"topicNames":["Resolving Forces, Inclined Planes","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2025_Oct_Q07_M14_08_ResolvingForcesInclinedPlanes.png","downloadName":"WME01-01_Y2025_Oct_Q07_M14_08_ResolvingForcesInclinedPlanes.png","finalAnswer":"$(a)\\ 5mg-T=5ma.\\quad (b)\\ T=\\dfrac{15mg}{7}.\\quad (c)\\ \\text{both particles have the same magnitude of acceleration}.\\quad (d)\\ k=2.38$.","steps":[{"title":"Part (a): Write equation of motion for Q","body":"Forces on Q (mass = 5m):\n \n \n \n Taking downward as positive for Q:\n \n $\\text{For Q: } \\sum F = ma$\n \n $5mg - T = 5ma$"},{"title":"Part (b): Find T in terms of m and g - Resolve perpendicular to plane","body":"$\\perp \\text{ to plane: } \\sum F = 0$\n \n $R = 2mg\\cos\\alpha$ $R = 2mg \\times \\frac{12}{13}$ $R = \\frac{24mg}{13}$"},{"title":"Part (b): Find T in terms of m and g - Find friction force","body":"P is moving UP the plane, so friction acts DOWN the plane:\n \n $F = \\mu R$ $= \\frac{1}{8} \\times \\frac{24mg}{13}$ $= \\frac{3mg}{13}$"},{"title":"Part (b): Find T in terms of m and g - Resolve parallel to plane","body":"Taking up the plane as positive:\n \n $\\parallel \\text{ to plane: } \\sum F = ma$\n \n $T - 2mg\\sin\\alpha - F = 2ma$ $T - 2mg \\times \\frac{5}{13} - \\frac{3mg}{13} = 2ma$ $T - \\frac{10mg}{13} - \\frac{3mg}{13} = 2ma$ $T - \\frac{13mg}{13} = 2ma$ $T - mg = 2ma \\quad \\text{...(1)}$"},{"title":"Part (b): Find T in terms of m and g - Combine with equation for Q","body":"From part (a): $5mg - T = 5ma$ ...(2)\n \n Add equations (1) and (2):\n \n $(T - mg) + (5mg - T) = 2ma + 5ma$ $4mg = 7ma$ $a = \\frac{4g}{7}$"},{"title":"Part (b): Find T in terms of m and g - Substitute back to find T","body":"From equation (1):\n \n $T = mg + 2ma$ $= mg + 2m \\times \\frac{4g}{7}$ $= mg + \\frac{8mg}{7}$ $= \\frac{7mg + 8mg}{7}$ $= \\frac{15mg}{7}$"},{"title":"Part (c): State how solution uses fact that string is inextensible","body":"An inextensible string means the string cannot stretch.\n \n This has the following consequence:\n \n \n For an inextensible string over a pulley:\n \n The magnitude of acceleration of both connected particles must be equal.\n \n In this problem: $|a_P| = |a_Q| = a$\n \n \n \n How this was used in part (b):\n \n When we wrote the equations of motion:\n \n ; For P: $T - mg = 2ma$\n ; For Q: $5mg - T = 5ma$\n \n \n We used the same acceleration $a$ for both particles because the string is inextensible.\n \n If the string could stretch, the two particles could have different accelerations."},{"title":"Part (d): Find value of k (force on pulley = kmg) - Identify the angle between tensions","body":"The string from Q is vertical (downward).\n The string from P is along the plane at angle $\\alpha$ to horizontal.\n \n Angle between the two strings = $90^\\circ + \\alpha$"},{"title":"Part (d): Find value of k (force on pulley = kmg) - Use vector components","body":"Let's take horizontal (right) and vertical (up) as positive directions.\n \n Tension from Q:\n \n ; Horizontal component: $0$\n ; Vertical component: $-T = -\\frac{15mg}{7}$ (downward)\n \n \n Tension from P along plane:\n The plane makes angle $\\alpha$ with horizontal, so:\n \n ; Horizontal component: $-T\\cos\\alpha = -\\frac{15mg}{7} \\times \\frac{12}{13} = -\\frac{180mg}{91}$\n ; Vertical component: $T\\sin\\alpha = \\frac{15mg}{7} \\times \\frac{5}{13} = \\frac{75mg}{91}$"},{"title":"Part (d): Find value of k (force on pulley = kmg) - Find resultant","body":"$R_x = 0 - \\frac{180mg}{91} = -\\frac{180mg}{91}$ $R_y = -\\frac{15mg}{7} + \\frac{75mg}{91}$\n Convert $\\frac{15mg}{7}$ to denominator 91: $\\frac{15mg}{7} = \\frac{195mg}{91}$\n $R_y = -\\frac{195mg}{91} + \\frac{75mg}{91} = -\\frac{120mg}{91}$"},{"title":"Part (d): Find value of k (force on pulley = kmg) - Find magnitude","body":"$|R| = \\sqrt{R_x^2 + R_y^2}$ $= \\sqrt{\\left(\\frac{180mg}{91}\\right)^2 + \\left(\\frac{120mg}{91}\\right)^2}$ $= \\frac{mg}{91}\\sqrt{180^2 + 120^2}$ $= \\frac{mg}{91}\\sqrt{32400 + 14400}$ $= \\frac{mg}{91}\\sqrt{46800}$ $= \\frac{mg}{91} \\times 216.333...$ $= 2.377... mg$ $= 2.38mg \\text{ (3 s.f.)}$\n Therefore: $k = 2.38$"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2026_Jan_Q05","year":2026,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2026","qNo":5,"marks":12,"topic":"08_ResolvingForcesInclinedPlanes","topicName":"Resolving Forces, Inclined Planes","primaryTopic":"08_ResolvingForcesInclinedPlanes","primaryTopicName":"Resolving Forces, Inclined Planes","secondaryTopics":["04_ConstantAcceleration1D"],"secondaryTopicNames":["Constant Acceleration in 1D"],"topics":["08_ResolvingForcesInclinedPlanes","04_ConstantAcceleration1D"],"topicNames":["Resolving Forces, Inclined Planes","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2026_Jan_Q05_M12_08_ResolvingForcesInclinedPlanes.png","downloadName":"WME01-01_Y2026_Jan_Q05_M12_08_ResolvingForcesInclinedPlanes.png","finalAnswer":"$(a)\\ U=2.1\\ \\mathrm{m\\,s^{-1}}\\ \\text{to 2 s.f.}.\\quad (b)\\ 0.25\\ \\mathrm{s}.\\quad (c)\\ AC=1.4\\ \\mathrm{m}$.","steps":[{"title":"Find the acceleration from friction","body":"On a horizontal surface, $R=mg$ and the friction is $F=\\mu R=\\dfrac17mg$. The friction is the only horizontal force, so the acceleration is opposite the motion with magnitude $\\dfrac{F}{m}=\\dfrac{g}{7}=1.4\\ \\mathrm{m\\,s^{-2}}$."},{"title":"Use A to B to find U","body":"From A to B, $u=U$, $v=\\dfrac{U}{2}$, $a=-\\dfrac{g}{7}$ and $t=0.75$. Using $v=u+at$: $\\dfrac{U}{2}=U-\\dfrac{g}{7}(0.75)$."},{"title":"Show the value of U","body":"With $g=9.8$, $\\dfrac{g}{7}(0.75)=1.05$, so $\\dfrac{U}{2}=U-1.05$. Hence $U=2.10\\ \\mathrm{m\\,s^{-1}}$, which is $2.1\\ \\mathrm{m\\,s^{-1}}$ to 2 significant figures."},{"title":"Find the time from B to C","body":"From B to C, the speed falls from $\\dfrac{U}{2}$ to $\\dfrac{U}{3}$ with the same acceleration $-1.4$. Thus $\\dfrac{U}{3}=\\dfrac{U}{2}-1.4t$. With $U=2.1$, this gives $0.7=1.05-1.4t$, so $t=0.25\\ \\mathrm{s}$."},{"title":"Find the distance AC","body":"Use average speed on each section. $AB=\\dfrac{U+U/2}{2}(0.75)=1.18125\\ \\mathrm{m}$ and $BC=\\dfrac{U/2+U/3}{2}(0.25)=0.21875\\ \\mathrm{m}$. Therefore $AC=1.18125+0.21875=1.4\\ \\mathrm{m}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2026_Jan_Q07","year":2026,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2026","qNo":7,"marks":14,"topic":"08_ResolvingForcesInclinedPlanes","topicName":"Resolving Forces, Inclined Planes","primaryTopic":"08_ResolvingForcesInclinedPlanes","primaryTopicName":"Resolving Forces, Inclined Planes","secondaryTopics":["07_NewtonsSecondLaw"],"secondaryTopicNames":["Newton's Second Law"],"topics":["08_ResolvingForcesInclinedPlanes","07_NewtonsSecondLaw"],"topicNames":["Resolving Forces, Inclined Planes","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2026_Jan_Q07_M14_08_ResolvingForcesInclinedPlanes.png","downloadName":"WME01-01_Y2026_Jan_Q07_M14_08_ResolvingForcesInclinedPlanes.png","finalAnswer":"$(a)\\ \\mu=\\dfrac14.\\quad (b)(i)\\ n=3.\\quad (b)(ii)\\ a=\\dfrac{2g}{41}=0.478\\ \\mathrm{m\\,s^{-2}}\\ \\text{approximately}$.","steps":[{"title":"Find the trigonometric ratios","body":"Since $\\tan\\theta=\\dfrac43$, use a $3$-$4$-$5$ triangle: $\\sin\\theta=\\dfrac45$ and $\\cos\\theta=\\dfrac35$."},{"title":"Use limiting equilibrium in part (a)","body":"With one $0.2$ kg block in the bucket, the bucket side has mass $0.45+0.2=0.65$ kg. Since the package is on the point of slipping down the plane, friction on P acts up the plane."},{"title":"Find the friction force","body":"The tension equals the bucket weight, so $T=0.65g$. Along the plane for P in equilibrium, $T+F=g\\sin\\theta$. Hence $0.65g+F=\\dfrac45g$, so $F=\\dfrac{3g}{20}$."},{"title":"Find the normal reaction and mu","body":"Perpendicular to the plane, $R=g\\cos\\theta=\\dfrac35g$. Since $F=\\mu R$, $\\mu=\\dfrac{F}{R}=\\dfrac{3g/20}{3g/5}=\\dfrac14$."},{"title":"Set the condition for upward motion","body":"When P is about to move up the plane, friction acts down the plane. With $n$ blocks in the bucket, the bucket-side mass is $0.45+0.2n$. The bucket weight must exceed the downslope resistance: $(0.45+0.2n)g>g\\sin\\theta+\\mu R$."},{"title":"Find n","body":"Using $g\\sin\\theta=\\dfrac45g$ and $\\mu R=\\dfrac14\\cdot\\dfrac35g=\\dfrac{3g}{20}$, the condition is $0.45+0.2n>\\dfrac45+\\dfrac{3}{20}=0.95$. Hence $0.2n>0.50$, so $n>2.5$ and the least integer is $n=3$."},{"title":"Apply Newtons second law after motion begins","body":"For $n=3$, the bucket-side mass is $0.45+0.6=1.05$ kg and the total moving mass is $1+1.05=2.05$ kg. The driving force is $1.05g-\\dfrac45g-\\dfrac{3g}{20}=0.10g$."},{"title":"Find the acceleration","body":"Using $F=ma$, $0.10g=2.05a$, so $a=\\dfrac{0.10g}{2.05}=\\dfrac{2g}{41}=0.478\\ \\mathrm{m\\,s^{-2}}$ to 3 significant figures."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2019_Oct_Q01","year":2019,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2019","qNo":1,"marks":6,"topic":"09_MomentumImpulseCollisions","topicName":"Momentum, Impulse & Collisions","primaryTopic":"09_MomentumImpulseCollisions","primaryTopicName":"Momentum, Impulse & Collisions","secondaryTopics":["07_NewtonsSecondLaw"],"secondaryTopicNames":["Newton's Second Law"],"topics":["09_MomentumImpulseCollisions","07_NewtonsSecondLaw"],"topicNames":["Momentum, Impulse & Collisions","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2019_Oct_Q01_M06_09_MomentumImpulseCollisions.png","downloadName":"WME01-01_Y2019_Oct_Q01_M06_09_MomentumImpulseCollisions.png","finalAnswer":"$(a)\\ v=\\dfrac{6u}{5}.\\quad (b)\\ I=\\dfrac{42}{5}mu$.","steps":[{"title":"Choose a direction","body":"Take P's initial direction as positive. Then P initially has velocity $4u$ and Q initially has velocity $-3u$."},{"title":"Use conservation of momentum","body":"When the string becomes taut, both particles move with common speed $v$. Hence $3m(4u)+2m(-3u)=(3m+2m)v$."},{"title":"Find the common speed","body":"$12mu-6mu=5mv$, so $v=\\dfrac{6u}{5}$."},{"title":"Use impulse on Q","body":"Impulse on Q equals change in momentum: $I=2m\\left(\\dfrac{6u}{5}-(-3u)\\right)$."},{"title":"Find the impulse magnitude","body":"$I=2m\\left(\\dfrac{6u}{5}+\\dfrac{15u}{5}\\right)=2m\\cdot\\dfrac{21u}{5}=\\dfrac{42}{5}mu$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2020_Jan_Q01","year":2020,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2020","qNo":1,"marks":8,"topic":"09_MomentumImpulseCollisions","topicName":"Momentum, Impulse & Collisions","primaryTopic":"09_MomentumImpulseCollisions","primaryTopicName":"Momentum, Impulse & Collisions","secondaryTopics":["01_QuantitiesUnitsModelling"],"secondaryTopicNames":["Quantities, Units & Modelling"],"topics":["09_MomentumImpulseCollisions","01_QuantitiesUnitsModelling"],"topicNames":["Momentum, Impulse & Collisions","Quantities, Units & Modelling"],"image":"ial/wme01/questions/WME01-01_Y2020_Jan_Q01_M08_09_MomentumImpulseCollisions.png","downloadName":"WME01-01_Y2020_Jan_Q01_M08_09_MomentumImpulseCollisions.png","finalAnswer":"$(a)\\ I=\\dfrac{4}{3}m_2u.\\quad (b)\\ \\text{speed of P}=\\dfrac{(4m_2-3m_1)u}{3m_1}.\\quad (c)\\ m_2>\\dfrac34m_1$.","steps":[{"title":"Choose a positive direction","body":"Take P's original direction as positive. Before collision, $v_P=u$ and $v_Q=-u$. After collision, Q has velocity $\\dfrac{u}{3}$ because its direction is reversed."},{"title":"Find the impulse on Q","body":"Impulse on Q equals change in momentum: $I=m_2\\left(\\dfrac{u}{3}-(-u)\\right)=m_2\\left(\\dfrac{4u}{3}\\right)=\\dfrac{4}{3}m_2u$."},{"title":"Use conservation of momentum","body":"Let the speed of P after collision be $v$. Since P reverses direction, its velocity is $-v$. Hence $m_1u-m_2u=-m_1v+\\dfrac13m_2u$."},{"title":"Solve for P's speed","body":"Rearrange: $m_1v=\\dfrac43m_2u-m_1u$, so $v=\\dfrac{(4m_2-3m_1)u}{3m_1}$."},{"title":"Use the fact that speed is positive","body":"Since $u>0$ and $m_1>0$, the numerator must be positive: $4m_2-3m_1>0$. Therefore $m_2>\\dfrac34m_1$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_Jan_Q02","year":2021,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2021","qNo":2,"marks":6,"topic":"09_MomentumImpulseCollisions","topicName":"Momentum, Impulse & Collisions","primaryTopic":"09_MomentumImpulseCollisions","primaryTopicName":"Momentum, Impulse & Collisions","secondaryTopics":["01_QuantitiesUnitsModelling"],"secondaryTopicNames":["Quantities, Units & Modelling"],"topics":["09_MomentumImpulseCollisions","01_QuantitiesUnitsModelling"],"topicNames":["Momentum, Impulse & Collisions","Quantities, Units & Modelling"],"image":"ial/wme01/questions/WME01-01_Y2021_Jan_Q02_M06_09_MomentumImpulseCollisions.png","downloadName":"WME01-01_Y2021_Jan_Q02_M06_09_MomentumImpulseCollisions.png","finalAnswer":"$(a)\\ \\text{speed of P}=\\dfrac{u}{2}.\\quad (b)\\ \\text{speed of Q}=3u$.","steps":[{"title":"Choose a positive direction","body":"Take P's original direction as positive. Before collision, P has velocity $3u$ and Q has velocity $-2u$."},{"title":"Use impulse on P","body":"The impulse on P is opposite to P's original motion and has magnitude $5mu$. Let P's velocity after collision be $v$. Then $-5mu=2m(v-3u)$."},{"title":"Find P speed","body":"Divide by $m$: $-5u=2v-6u$, so $2v=u$ and $v=\\dfrac{u}{2}$."},{"title":"Use impulse on Q","body":"The impulse on Q is in P's original direction. Let Q's velocity after collision be $w$. Then $5mu=m(w-(-2u))$."},{"title":"Find Q speed","body":"$5u=w+2u$, so $w=3u$. Therefore the speed of Q is $3u$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_MayJune_Q01","year":2021,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2021","qNo":1,"marks":7,"topic":"09_MomentumImpulseCollisions","topicName":"Momentum, Impulse & Collisions","primaryTopic":"09_MomentumImpulseCollisions","primaryTopicName":"Momentum, Impulse & Collisions","secondaryTopics":["01_QuantitiesUnitsModelling","02_WorkingWithVectors"],"secondaryTopicNames":["Quantities, Units & Modelling","Working with Vectors"],"topics":["09_MomentumImpulseCollisions","01_QuantitiesUnitsModelling","02_WorkingWithVectors"],"topicNames":["Momentum, Impulse & Collisions","Quantities, Units & Modelling","Working with Vectors"],"image":"ial/wme01/questions/WME01-01_Y2021_MayJune_Q01_M07_09_MomentumImpulseCollisions.png","downloadName":"WME01-01_Y2021_MayJune_Q01_M07_09_MomentumImpulseCollisions.png","finalAnswer":"$(a)\\ I=25mu.\\quad (b)\\ k=\\dfrac{28}{3}\\ \\text{or}\\ \\dfrac{22}{3}$.","steps":[{"title":"Choose a positive direction","body":"Take P's original direction as positive. Q initially has velocity $-2u$. Since Q reverses direction and then has speed $3u$, its final velocity is $3u$."},{"title":"Find the impulse on Q","body":"Impulse equals change in momentum: $I=5m(3u-(-2u))=25mu$."},{"title":"Use conservation of momentum","body":"Before collision, total momentum is $3m(ku)+5m(-2u)=3mku-10mu$."},{"title":"Case 1: P continues in its original direction","body":"If P has final velocity $u$, final momentum is $3m(u)+5m(3u)=18mu$. So $3mku-10mu=18mu$, giving $3k=28$ and $k=\\dfrac{28}{3}$."},{"title":"Case 2: P reverses direction","body":"If P has final velocity $-u$, final momentum is $3m(-u)+5m(3u)=12mu$. So $3mku-10mu=12mu$, giving $3k=22$ and $k=\\dfrac{22}{3}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_Oct_Q02","year":2021,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2021","qNo":2,"marks":10,"topic":"09_MomentumImpulseCollisions","topicName":"Momentum, Impulse & Collisions","primaryTopic":"09_MomentumImpulseCollisions","primaryTopicName":"Momentum, Impulse & Collisions","secondaryTopics":["07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"secondaryTopicNames":["Newton's Second Law","Constant Acceleration in 1D"],"topics":["09_MomentumImpulseCollisions","07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"topicNames":["Momentum, Impulse & Collisions","Newton's Second Law","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2021_Oct_Q02_M10_09_MomentumImpulseCollisions.png","downloadName":"WME01-01_Y2021_Oct_Q02_M10_09_MomentumImpulseCollisions.png","finalAnswer":"$(a)\\ \\text{speed of P}=u.\\quad (b)\\ \\text{P reverses direction}.\\quad (c)\\ \\mu=\\dfrac13$.","steps":[{"title":"Use conservation of momentum","body":"Take P's original direction as positive. Before collision, P has velocity $3u$ and Q is at rest. After collision, Q has velocity $2u$. Let P's velocity be $v$."},{"title":"Find P velocity","body":"$2m(3u)=2mv+4m(2u)$. Thus $6mu=2mv+8mu$, so $2mv=-2mu$ and $v=-u$."},{"title":"State speed and direction","body":"The speed of P is $u$. The negative sign shows that P moves in the opposite direction after the collision."},{"title":"Find the deceleration of Q","body":"After collision, Q starts with speed $2u$ and stops after distance $\\dfrac{6u^2}{g}$. Use $v^2=u^2+2as$: $0=(2u)^2+2a\\left(\\dfrac{6u^2}{g}\\right)$."},{"title":"Simplify acceleration","body":"$0=4u^2+\\dfrac{12au^2}{g}$, so $a=-\\dfrac{g}{3}$. The deceleration magnitude is $\\dfrac{g}{3}$."},{"title":"Use friction on Q","body":"For Q, $R=4mg$, so friction is $\\mu R=4\\mu mg$. This friction produces deceleration: $4\\mu mg=4m\\cdot\\dfrac{g}{3}$."},{"title":"Find mu","body":"Cancel $4mg$: $\\mu=\\dfrac13$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_Jan_Q02","year":2022,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2022","qNo":2,"marks":7,"topic":"09_MomentumImpulseCollisions","topicName":"Momentum, Impulse & Collisions","primaryTopic":"09_MomentumImpulseCollisions","primaryTopicName":"Momentum, Impulse & Collisions","secondaryTopics":["02_WorkingWithVectors"],"secondaryTopicNames":["Working with Vectors"],"topics":["09_MomentumImpulseCollisions","02_WorkingWithVectors"],"topicNames":["Momentum, Impulse & Collisions","Working with Vectors"],"image":"ial/wme01/questions/WME01-01_Y2022_Jan_Q02_M07_09_MomentumImpulseCollisions.png","downloadName":"WME01-01_Y2022_Jan_Q02_M07_09_MomentumImpulseCollisions.png","finalAnswer":"$(a)\\ k=\\dfrac13.\\quad (b)\\ I=\\dfrac32mu$.","steps":[{"title":"Choose a positive direction","body":"Take the original direction of P as positive. Before the collision, P has velocity $3u$ and Q has velocity $-u$."},{"title":"Write the velocities after collision","body":"After collision, each direction is reversed and each speed is halved. So P has velocity $-\\dfrac32u$ and Q has velocity $\\dfrac12u$."},{"title":"Use conservation of momentum","body":"$km(3u)+m(-u)=km\\left(-\\dfrac32u\\right)+m\\left(\\dfrac12u\\right)$."},{"title":"Find k","body":"Divide by $mu$: $3k-1=-\\dfrac32k+\\dfrac12$. Hence $\\dfrac92k=\\dfrac32$, so $k=\\dfrac13$."},{"title":"Find impulse on Q","body":"Impulse on Q equals change in momentum of Q: $I=m\\left(\\dfrac12u-(-u)\\right)=\\dfrac32mu$."},{"title":"State the magnitude","body":"The magnitude of the impulse is $\\dfrac32mu$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_MayJune_Q01","year":2022,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2022","qNo":1,"marks":4,"topic":"09_MomentumImpulseCollisions","topicName":"Momentum, Impulse & Collisions","primaryTopic":"09_MomentumImpulseCollisions","primaryTopicName":"Momentum, Impulse & Collisions","secondaryTopics":[],"secondaryTopicNames":[],"topics":["09_MomentumImpulseCollisions"],"topicNames":["Momentum, Impulse & Collisions"],"image":"ial/wme01/questions/WME01-01_Y2022_MayJune_Q01_M04_09_MomentumImpulseCollisions.png","downloadName":"WME01-01_Y2022_MayJune_Q01_M04_09_MomentumImpulseCollisions.png","finalAnswer":"$(a)\\ \\text{speed}=\\dfrac{2u}{3}.\\quad (b)\\ \\text{same direction as before the collision}$.","steps":[{"title":"Use impulse as change in momentum","body":"Take the original direction of Q as positive. Q has mass $3m$ and initial velocity $2u$. Let its velocity after collision be $v$."},{"title":"Set up the impulse equation","body":"The impulse has magnitude $4mu$ and acts opposite to Q's original motion, so $4mu=3m(2u-v)$."},{"title":"Find the speed","body":"Cancel $m$: $4u=6u-3v$. Thus $3v=2u$ and $v=\\dfrac{2u}{3}$."},{"title":"State the direction","body":"Since $v$ is positive in Q's original direction, Q continues in the same direction after the collision."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_Oct_Q01","year":2022,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2022","qNo":1,"marks":5,"topic":"09_MomentumImpulseCollisions","topicName":"Momentum, Impulse & Collisions","primaryTopic":"09_MomentumImpulseCollisions","primaryTopicName":"Momentum, Impulse & Collisions","secondaryTopics":["01_QuantitiesUnitsModelling"],"secondaryTopicNames":["Quantities, Units & Modelling"],"topics":["09_MomentumImpulseCollisions","01_QuantitiesUnitsModelling"],"topicNames":["Momentum, Impulse & Collisions","Quantities, Units & Modelling"],"image":"ial/wme01/questions/WME01-01_Y2022_Oct_Q01_M05_09_MomentumImpulseCollisions.png","downloadName":"WME01-01_Y2022_Oct_Q01_M05_09_MomentumImpulseCollisions.png","finalAnswer":"$(a)\\ v=1.6\\ \\mathrm{m\\,s^{-1}}.\\quad (b)\\ I=48000\\ \\mathrm{N\\,s}$.","steps":[{"title":"Use conservation of momentum","body":"The trucks join together, so they move with a common speed $v$. Using tonnes consistently, $20(4)+30(0)=(20+30)v$."},{"title":"Find the common speed","body":"$80=50v$, so $v=1.6\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Use change in momentum of S","body":"Truck S has mass $20\\,000$ kg. Its speed changes from $4$ to $1.6\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Find the impulse magnitude","body":"$I=20000|1.6-4|=20000(2.4)=48000\\ \\mathrm{N\\,s}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2023_Jan_Q02","year":2023,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2023","qNo":2,"marks":8,"topic":"09_MomentumImpulseCollisions","topicName":"Momentum, Impulse & Collisions","primaryTopic":"09_MomentumImpulseCollisions","primaryTopicName":"Momentum, Impulse & Collisions","secondaryTopics":["01_QuantitiesUnitsModelling","02_WorkingWithVectors"],"secondaryTopicNames":["Quantities, Units & Modelling","Working with Vectors"],"topics":["09_MomentumImpulseCollisions","01_QuantitiesUnitsModelling","02_WorkingWithVectors"],"topicNames":["Momentum, Impulse & Collisions","Quantities, Units & Modelling","Working with Vectors"],"image":"ial/wme01/questions/WME01-01_Y2023_Jan_Q02_M08_09_MomentumImpulseCollisions.png","downloadName":"WME01-01_Y2023_Jan_Q02_M08_09_MomentumImpulseCollisions.png","finalAnswer":"$(a)(i)\\ \\text{speed of A}=0.5\\ \\mathrm{m\\,s^{-1}}.\\quad (a)(ii)\\ \\text{speed of B}=1.5\\ \\mathrm{m\\,s^{-1}}.\\quad (b)\\ I=3m\\ \\mathrm{N\\,s}$.","steps":[{"title":"Choose a positive direction","body":"Take the original direction of A as positive. Before the collision, A has velocity $1.5$ and B has velocity $-1.5$."},{"title":"Use the speed difference","body":"After the collision, A keeps the same direction. Let A's speed be $v$. The valid motion has B moving in A's direction with speed $v+1$."},{"title":"Use conservation of momentum","body":"$3m(1.5)+m(-1.5)=3mv+m(v+1)$."},{"title":"Find the two speeds","body":"$4.5m-1.5m=3mv+mv+m$, so $3=4v+1$. Hence $v=0.5$, and B's speed is $v+1=1.5$."},{"title":"Find the impulse on B","body":"For B, impulse equals change in momentum: $I=m(1.5-(-1.5))=3m$."},{"title":"State the magnitude","body":"The magnitude of the impulse is $3m\\ \\mathrm{N\\,s}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2023_MayJune_Q01","year":2023,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2023","qNo":1,"marks":7,"topic":"09_MomentumImpulseCollisions","topicName":"Momentum, Impulse & Collisions","primaryTopic":"09_MomentumImpulseCollisions","primaryTopicName":"Momentum, Impulse & Collisions","secondaryTopics":["01_QuantitiesUnitsModelling"],"secondaryTopicNames":["Quantities, Units & Modelling"],"topics":["09_MomentumImpulseCollisions","01_QuantitiesUnitsModelling"],"topicNames":["Momentum, Impulse & Collisions","Quantities, Units & Modelling"],"image":"ial/wme01/questions/WME01-01_Y2023_MayJune_Q01_M07_09_MomentumImpulseCollisions.png","downloadName":"WME01-01_Y2023_MayJune_Q01_M07_09_MomentumImpulseCollisions.png","finalAnswer":"$(a)\\ \\text{speed of A}=\\dfrac{u}{2}.\\quad (b)\\ \\text{A reverses direction}.\\quad (c)\\ I=10u\\ \\mathrm{N\\,s}$.","steps":[{"title":"Choose a positive direction","body":"Take the original direction of A as positive. Before the collision, A has velocity $2u$ and B has velocity $-3u$. After the collision, B has velocity $2u$ because its direction is reversed."},{"title":"Use conservation of momentum","body":"Let the velocity of A after the collision be $v$. Then $4(2u)+2(-3u)=4v+2(2u)$."},{"title":"Solve for the velocity of A","body":"$8u-6u=4v+4u$, so $2u=4v+4u$. Hence $4v=-2u$ and $v=-\\dfrac{u}{2}$."},{"title":"State the speed and direction","body":"The speed of A is the magnitude of its velocity, so it is $\\dfrac{u}{2}$. The negative sign shows that A has reversed direction."},{"title":"Find the impulse on B","body":"Impulse equals change in momentum. For B, $I=2\\left(2u-(-3u)\\right)=2(5u)=10u$."},{"title":"Attach the units","body":"The impulse is $10u\\ \\mathrm{N\\,s}$, equivalently $10u\\ \\mathrm{kg\\,m\\,s^{-1}}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2023_Oct_Q03","year":2023,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2023","qNo":3,"marks":10,"topic":"09_MomentumImpulseCollisions","topicName":"Momentum, Impulse & Collisions","primaryTopic":"09_MomentumImpulseCollisions","primaryTopicName":"Momentum, Impulse & Collisions","secondaryTopics":["04_ConstantAcceleration1D","07_NewtonsSecondLaw"],"secondaryTopicNames":["Constant Acceleration in 1D","Newton's Second Law"],"topics":["09_MomentumImpulseCollisions","04_ConstantAcceleration1D","07_NewtonsSecondLaw"],"topicNames":["Momentum, Impulse & Collisions","Constant Acceleration in 1D","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2023_Oct_Q03_M10_09_MomentumImpulseCollisions.png","downloadName":"WME01-01_Y2023_Oct_Q03_M10_09_MomentumImpulseCollisions.png","finalAnswer":"$(a)\\ v=9\\ \\mathrm{m\\,s^{-1}}$. $(b)\\ I=1.8\\ \\mathrm{N\\,s}$. $(c)\\ R\\approx695\\ \\mathrm{N}$.","steps":[{"title":"Use conservation of momentum","body":"Take downward as positive during the impact. Before impact, the hammer has momentum $1.8(10)$ and the peg has momentum $0$. After impact, the combined mass is $1.8+0.2=2.0$ kg."},{"title":"Find the common speed","body":"$1.8(10)=2.0v$, so $18=2v$ and $v=9\\ \\mathrm{m\\,s^{-1}}$."},{"title":"Use impulse on the peg","body":"The peg changes from rest to speed $9\\ \\mathrm{m\\,s^{-1}}$ downward. The impulse magnitude is $0.2(9-0)=1.8\\ \\mathrm{N\\,s}$."},{"title":"Find the deceleration in the ground","body":"The hammer and peg move together from speed $9$ to rest over $0.12$ m. With downward positive, $0=9^2+2a(0.12)$, so $a=-337.5\\ \\mathrm{m\\,s^{-2}}$."},{"title":"Apply Newtons second law","body":"For the combined mass $2.0$ kg, forces are weight $2g$ downward and resistance $R$ upward. With downward positive, $2g-R=2a$."},{"title":"Find R","body":"$19.6-R=2(-337.5)=-675$, so $R=694.6\\ \\mathrm{N}$, which is about $695\\ \\mathrm{N}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2024_Jan_Q02","year":2024,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2024","qNo":2,"marks":6,"topic":"09_MomentumImpulseCollisions","topicName":"Momentum, Impulse & Collisions","primaryTopic":"09_MomentumImpulseCollisions","primaryTopicName":"Momentum, Impulse & Collisions","secondaryTopics":["01_QuantitiesUnitsModelling"],"secondaryTopicNames":["Quantities, Units & Modelling"],"topics":["09_MomentumImpulseCollisions","01_QuantitiesUnitsModelling"],"topicNames":["Momentum, Impulse & Collisions","Quantities, Units & Modelling"],"image":"ial/wme01/questions/WME01-01_Y2024_Jan_Q02_M06_09_MomentumImpulseCollisions.png","downloadName":"WME01-01_Y2024_Jan_Q02_M06_09_MomentumImpulseCollisions.png","finalAnswer":"$(a)\\ x=2.5.\\quad (b)\\ I=10\\ \\mathrm{N\\,s}$.","steps":[{"title":"Choose a sign convention","body":"Take the initial direction of A as positive. Before collision, A has velocity $3$ and B has velocity $-x$."},{"title":"Set up conservation of momentum","body":"After collision, A still moves in the same direction with velocity $1$. B has speed $1.5$ in the positive direction for the valid solution. Hence $5(3)+x(-x)=5(1)+1.5x$."},{"title":"Solve for x","body":"$15-x^2=5+1.5x$, so $x^2+1.5x-10=0$. This gives $x=2.5$ or $x=-4$. Since mass is positive, $x=2.5$."},{"title":"Use change in momentum of A","body":"The impulse exerted on A equals the change in momentum of A: $I=5(1-3)=-10\\ \\mathrm{N\\,s}$ using the chosen positive direction."},{"title":"Give the magnitude","body":"The magnitude of the impulse is $10\\ \\mathrm{N\\,s}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2024_MayJune_Q01","year":2024,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2024","qNo":1,"marks":5,"topic":"09_MomentumImpulseCollisions","topicName":"Momentum, Impulse & Collisions","primaryTopic":"09_MomentumImpulseCollisions","primaryTopicName":"Momentum, Impulse & Collisions","secondaryTopics":["07_NewtonsSecondLaw"],"secondaryTopicNames":["Newton's Second Law"],"topics":["09_MomentumImpulseCollisions","07_NewtonsSecondLaw"],"topicNames":["Momentum, Impulse & Collisions","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2024_MayJune_Q01_M05_09_MomentumImpulseCollisions.png","downloadName":"WME01-01_Y2024_MayJune_Q01_M05_09_MomentumImpulseCollisions.png","finalAnswer":"$(a)\\ S=\\dfrac{U}{4}.\\quad (b)\\ I=\\dfrac{3mU}{4}$.","steps":[{"title":"Use conservation of momentum","body":"When the string becomes taut, A and B move with the same speed $S$. Before this, only A is moving. Hence $mU=(m+3m)S=4mS$."},{"title":"Find the common speed","body":"From $mU=4mS$, cancel $m$ to get $S=\\dfrac{U}{4}$."},{"title":"Use impulse on A","body":"The impulse on A equals the magnitude of its change in momentum: $I=m\\left|\\dfrac{U}{4}-U\\right|$."},{"title":"Simplify the impulse","body":"$I=m\\left(\\dfrac{3U}{4}\\right)=\\dfrac{3mU}{4}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2024_Oct_Q01","year":2024,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2024","qNo":1,"marks":6,"topic":"09_MomentumImpulseCollisions","topicName":"Momentum, Impulse & Collisions","primaryTopic":"09_MomentumImpulseCollisions","primaryTopicName":"Momentum, Impulse & Collisions","secondaryTopics":["01_QuantitiesUnitsModelling"],"secondaryTopicNames":["Quantities, Units & Modelling"],"topics":["09_MomentumImpulseCollisions","01_QuantitiesUnitsModelling"],"topicNames":["Momentum, Impulse & Collisions","Quantities, Units & Modelling"],"image":"ial/wme01/questions/WME01-01_Y2024_Oct_Q01_M06_09_MomentumImpulseCollisions.png","downloadName":"WME01-01_Y2024_Oct_Q01_M06_09_MomentumImpulseCollisions.png","finalAnswer":"$(a)\\ \\dfrac{y}{x}=\\dfrac{5}{11}.\\quad (b)\\ I=\\dfrac{108}{11}mx$.","steps":[{"title":"Choose a sign convention","body":"Take the initial direction of A as positive. Before collision, A has velocity $2x$ and B has velocity $-x$. After collision, both reverse direction, so A has velocity $-y$ and B has velocity $5y$."},{"title":"Apply conservation of momentum","body":"$4m(2x)+3m(-x)=4m(-y)+3m(5y)$. The left side is $5mx$ and the right side is $11my$."},{"title":"Show the ratio","body":"$5mx=11my$, so $\\dfrac{y}{x}=\\dfrac{5}{11}$."},{"title":"Use change in momentum for A","body":"The impulse received by A is the change in momentum of A: $I=4m|-y-2x|=4m(y+2x)$."},{"title":"Substitute y","body":"Using $y=\\dfrac{5x}{11}$, $I=4m\\left(\\dfrac{5x}{11}+2x\\right)=4m\\left(\\dfrac{27x}{11}\\right)=\\dfrac{108}{11}mx$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2025_Jan_Q03","year":2025,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2025","qNo":3,"marks":12,"topic":"09_MomentumImpulseCollisions","topicName":"Momentum, Impulse & Collisions","primaryTopic":"09_MomentumImpulseCollisions","primaryTopicName":"Momentum, Impulse & Collisions","secondaryTopics":["08_ResolvingForcesInclinedPlanes","04_ConstantAcceleration1D"],"secondaryTopicNames":["Resolving Forces, Inclined Planes","Constant Acceleration in 1D"],"topics":["09_MomentumImpulseCollisions","08_ResolvingForcesInclinedPlanes","04_ConstantAcceleration1D"],"topicNames":["Momentum, Impulse & Collisions","Resolving Forces, Inclined Planes","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2025_Jan_Q03_M12_09_MomentumImpulseCollisions.png","downloadName":"WME01-01_Y2025_Jan_Q03_M12_09_MomentumImpulseCollisions.png","finalAnswer":"$(a)\\ \\lambda=15m.\\quad (b)\\ \\mu=0.68\\ \\text{or}\\ 0.683.\\quad (c)\\ \\text{speed of P}=1.8\\ \\mathrm{m\\,s^{-1}}$.","steps":[{"title":"Use impulse to find lambda","body":"P starts from rest and immediately after the impulse has speed $5\\ \\mathrm{m\\,s^{-1}}$. Since the mass of P is $3m$, $\\lambda=3m(5-0)=15m$."},{"title":"Find the acceleration before collision","body":"Between the impulse and the collision, P slows from $5$ to $2.5\\ \\mathrm{m\\,s^{-1}}$ over $1.4$ m. Using $v^2=u^2+2as$: $(2.5)^2=5^2+2a(1.4)$."},{"title":"Calculate the acceleration","body":"$6.25=25+2.8a$, so $a=\\dfrac{-18.75}{2.8}=-6.696\\ldots\\ \\mathrm{m\\,s^{-2}}$."},{"title":"Connect friction to acceleration","body":"On the horizontal surface, $R=3mg$ and friction is $F=\\mu R=3\\mu mg$. This friction is opposite the motion, so $-3\\mu mg=3ma$ and therefore $a=-\\mu g$."},{"title":"Find mu","body":"$\\mu=\\dfrac{-a}{g}=\\dfrac{6.696\\ldots}{9.8}=0.683\\ldots$, so $\\mu=0.68$ to 2 significant figures."},{"title":"Use momentum in the collision","body":"Immediately before collision, P has speed $2.5$ and Q is at rest. Immediately after, Q has speed $2.1$ and P has speed $v$. Conservation of momentum gives $3m(2.5)+m(0)=3mv+m(2.1)$."},{"title":"Find the speed after collision","body":"$7.5=3v+2.1$, so $3v=5.4$ and $v=1.8\\ \\mathrm{m\\,s^{-1}}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2025_MayJune_Q01","year":2025,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2025","qNo":1,"marks":6,"topic":"09_MomentumImpulseCollisions","topicName":"Momentum, Impulse & Collisions","primaryTopic":"09_MomentumImpulseCollisions","primaryTopicName":"Momentum, Impulse & Collisions","secondaryTopics":["01_QuantitiesUnitsModelling","02_WorkingWithVectors"],"secondaryTopicNames":["Quantities, Units & Modelling","Working with Vectors"],"topics":["09_MomentumImpulseCollisions","01_QuantitiesUnitsModelling","02_WorkingWithVectors"],"topicNames":["Momentum, Impulse & Collisions","Quantities, Units & Modelling","Working with Vectors"],"image":"ial/wme01/questions/WME01-01_Y2025_MayJune_Q01_M06_09_MomentumImpulseCollisions.png","downloadName":"WME01-01_Y2025_MayJune_Q01_M06_09_MomentumImpulseCollisions.png","finalAnswer":"$(a)\\ v=3.5u=\\dfrac{7u}{2}.\\quad (b)\\ k=1.5=\\dfrac{3}{2}$.","steps":[{"title":"Part (a): Find v in terms of u - Apply impulse-momentum theorem to Q","body":"$\\text{Impulse} = \\text{Final momentum} - \\text{Initial momentum}$\n \n For particle Q:\n \n ; Mass = $3m$\n ; Initial velocity = $2u$\n ; Final velocity = $v$\n ; Impulse received = $4.5mu$"},{"title":"Part (a): Find v in terms of u - Set up equation","body":"$4.5mu = 3m \\times v - 3m \\times 2u$ $4.5mu = 3mv - 6mu$ $4.5u = 3v - 6u$ $4.5u + 6u = 3v$ $10.5u = 3v$ $v = \\frac{10.5u}{3}$ $v = 3.5u$"},{"title":"Part (b): Find the value of k - Apply conservation of momentum","body":"$\\text{Total momentum before} = \\text{Total momentum after}$\n \n Before collision:\n $\\text{P momentum} = km \\times 5u = 5kmu$ $\\text{Q momentum} = 3m \\times 2u = 6mu$ $\\text{Total} = 5kmu + 6mu$\n \n After collision:\n $\\text{P momentum} = km \\times 2u = 2kmu$ $\\text{Q momentum} = 3m \\times 3.5u = 10.5mu$ $\\text{Total} = 2kmu + 10.5mu$"},{"title":"Part (b): Find the value of k - Set up equation","body":"$5kmu + 6mu = 2kmu + 10.5mu$ $5km + 6m = 2km + 10.5m$ $5k + 6 = 2k + 10.5$ $5k - 2k = 10.5 - 6$ $3k = 4.5$ $k = \\frac{4.5}{3}$ $k = 1.5$"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2025_Oct_Q02","year":2025,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2025","qNo":2,"marks":8,"topic":"09_MomentumImpulseCollisions","topicName":"Momentum, Impulse & Collisions","primaryTopic":"09_MomentumImpulseCollisions","primaryTopicName":"Momentum, Impulse & Collisions","secondaryTopics":["01_QuantitiesUnitsModelling","08_ResolvingForcesInclinedPlanes","02_WorkingWithVectors"],"secondaryTopicNames":["Quantities, Units & Modelling","Resolving Forces, Inclined Planes","Working with Vectors"],"topics":["09_MomentumImpulseCollisions","01_QuantitiesUnitsModelling","08_ResolvingForcesInclinedPlanes","02_WorkingWithVectors"],"topicNames":["Momentum, Impulse & Collisions","Quantities, Units & Modelling","Resolving Forces, Inclined Planes","Working with Vectors"],"image":"ial/wme01/questions/WME01-01_Y2025_Oct_Q02_M08_09_MomentumImpulseCollisions.png","downloadName":"WME01-01_Y2025_Oct_Q02_M08_09_MomentumImpulseCollisions.png","finalAnswer":"$(a)\\ w=\\dfrac{u}{12}.\\quad (b)\\ k=\\dfrac{7}{12}\\ \\text{or}\\ k=\\dfrac{5}{12}$.","steps":[{"title":"Part (a): Find w in terms of u - Apply impulse-momentum theorem to Q","body":"$\\text{Impulse} = \\text{Final momentum} - \\text{Initial momentum}$\n \n For particle Q (mass = 3m):\n \n ; Initial velocity: $-u$ (moving left, negative)\n ; Final velocity: $+2w$ (moving right, positive)\n \n \n $\\text{Impulse} = 3m(2w) - 3m(-u)$ $\\frac{7mu}{2} = 6mw + 3mu$ $\\frac{7mu}{2} = 3m(2w + u)$ $\\frac{7u}{2} = 6w + 3u$ $6w = \\frac{7u}{2} - 3u$ $6w = \\frac{7u - 6u}{2}$ $6w = \\frac{u}{2}$ $w = \\frac{u}{12}$"},{"title":"Part (b): Find the two possible values of k - Apply conservation of momentum","body":"$\\text{Total momentum before} = \\text{Total momentum after}$\n \n Before collision:\n $\\text{P momentum} = 7m \\times ku = 7mku \\text{ (right)}$ $\\text{Q momentum} = 3m \\times (-u) = -3mu \\text{ (left)}$ $\\text{Total} = 7mku - 3mu$\n \n After collision:\n $\\text{P momentum} = 7m \\times w = 7mw \\text{ (right)}$ $\\text{Q momentum} = 3m \\times 2w = 6mw \\text{ (right)}$ $\\text{Total} = 7mw + 6mw = 13mw$"},{"title":"Part (b): Find the two possible values of k - Set up equation","body":"$7mku - 3mu = 13mw$ $7ku - 3u = 13w$"},{"title":"Part (b): Find the two possible values of k - Substitute $w = \\frac{u}{12}$","body":"$7ku - 3u = 13 \\times \\frac{u}{12}$ $7ku - 3u = \\frac{13u}{12}$ $7ku = \\frac{13u}{12} + 3u$ $7ku = \\frac{13u + 36u}{12}$ $7ku = \\frac{49u}{12}$ $7k = \\frac{49}{12}$ $k = \\frac{49}{84} = \\frac{7}{12}$"},{"title":"Part (b): Find the two possible values of k - Consider both directions for P after collision","body":"P could move either right (velocity = $+w$) or left (velocity = $-w$)\n \n Case 1: P moves right with velocity $+w$\n \n Already solved: $k = \\frac{7}{12}$\n \n Case 2: P moves left with velocity $-w$\n \n Total momentum after = $-7mw + 6mw = -mw$\n \n $7mku - 3mu = -mw$ $7ku - 3u = -w$ $7ku - 3u = -\\frac{u}{12}$ $7ku = 3u - \\frac{u}{12}$ $7ku = \\frac{36u - u}{12}$ $7ku = \\frac{35u}{12}$ $k = \\frac{35}{84} = \\frac{5}{12}$"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2026_Jan_Q01","year":2026,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2026","qNo":1,"marks":6,"topic":"09_MomentumImpulseCollisions","topicName":"Momentum, Impulse & Collisions","primaryTopic":"09_MomentumImpulseCollisions","primaryTopicName":"Momentum, Impulse & Collisions","secondaryTopics":["01_QuantitiesUnitsModelling","08_ResolvingForcesInclinedPlanes","02_WorkingWithVectors"],"secondaryTopicNames":["Quantities, Units & Modelling","Resolving Forces, Inclined Planes","Working with Vectors"],"topics":["09_MomentumImpulseCollisions","01_QuantitiesUnitsModelling","08_ResolvingForcesInclinedPlanes","02_WorkingWithVectors"],"topicNames":["Momentum, Impulse & Collisions","Quantities, Units & Modelling","Resolving Forces, Inclined Planes","Working with Vectors"],"image":"ial/wme01/questions/WME01-01_Y2026_Jan_Q01_M06_09_MomentumImpulseCollisions.png","downloadName":"WME01-01_Y2026_Jan_Q01_M06_09_MomentumImpulseCollisions.png","finalAnswer":"$(i)\\ \\text{speed of P}=\\dfrac{5u}{2}.\\quad (ii)\\ \\text{speed of Q}=\\dfrac{7u}{10}$.","steps":[{"title":"Choose a sign convention","body":"Take the initial direction of P as positive. Then before impact, $v_P=3u$ and $v_Q=-4u$. The impulse on P acts opposite to P\\'s initial motion, so its signed impulse is $-\\dfrac{33}{2}mu$."},{"title":"Use impulse on P","body":"For P, impulse equals change in momentum: $-\\dfrac{33}{2}mu=3m(v_P-3u)$. Dividing by $3m$ gives $v_P-3u=-\\dfrac{11u}{2}$, so $v_P=-\\dfrac{5u}{2}$."},{"title":"Interpret the speed of P","body":"The negative sign means P has reversed direction. Its speed is therefore $\\left|-\\dfrac{5u}{2}\\right|=\\dfrac{5u}{2}$."},{"title":"Use the equal and opposite impulse on Q","body":"Q receives impulse $+\\dfrac{33}{2}mu$ in the positive direction. Hence $\\dfrac{33}{2}mu=5m(v_Q-(-4u))=5m(v_Q+4u)$."},{"title":"Interpret the speed of Q","body":"Dividing by $5m$ gives $v_Q+4u=\\dfrac{33u}{10}$, so $v_Q=-\\dfrac{7u}{10}$. Q is still moving in its original direction, and its speed is $\\dfrac{7u}{10}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2019_Oct_Q05","year":2019,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2019","qNo":5,"marks":8,"topic":"10_Moments","topicName":"Moments","primaryTopic":"10_Moments","primaryTopicName":"Moments","secondaryTopics":["01_QuantitiesUnitsModelling","07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"secondaryTopicNames":["Quantities, Units & Modelling","Newton's Second Law","Constant Acceleration in 1D"],"topics":["10_Moments","01_QuantitiesUnitsModelling","07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"topicNames":["Moments","Quantities, Units & Modelling","Newton's Second Law","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2019_Oct_Q05_M08_10_Moments.png","downloadName":"WME01-01_Y2019_Oct_Q05_M08_10_Moments.png","finalAnswer":"$(a)\\ M=14.\\quad (b)\\ x=2.8\\ \\mathrm{m}$.","steps":[{"title":"Locate the key distances","body":"The beam is $5$ m long. Since $CB=1.5$ m, $AC=3.5$ m. The centre of mass is $1.75$ m from A, so it is also $1.75$ m from C."},{"title":"Use the largest M condition","body":"For the largest possible $M$ at B, the rope at A is just slack, so the beam is supported at C only."},{"title":"Take moments about C","body":"The particle at B is $1.5$ m to the right of C, and the beam's weight acts $1.75$ m to the left of C. Hence $Mg(1.5)=12g(1.75)$."},{"title":"Find M","body":"$M=\\dfrac{12(1.75)}{1.5}=14$."},{"title":"Set the tensions for part b","body":"Let the tension at A be $T$. The tension at C is $2T$. Vertical equilibrium gives $T+2T=12g+15g=27g$, so $T=9g$ and the tension at C is $18g$."},{"title":"Take moments about A","body":"For the new particle at $AD=x$, moments about A give $18g(3.5)=12g(1.75)+15gx$."},{"title":"Solve for x","body":"Cancel $g$: $63=21+15x$. Thus $15x=42$ and $x=2.8$ m."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2020_Jan_Q02","year":2020,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2020","qNo":2,"marks":7,"topic":"10_Moments","topicName":"Moments","primaryTopic":"10_Moments","primaryTopicName":"Moments","secondaryTopics":["07_NewtonsSecondLaw","01_QuantitiesUnitsModelling","04_ConstantAcceleration1D"],"secondaryTopicNames":["Newton's Second Law","Quantities, Units & Modelling","Constant Acceleration in 1D"],"topics":["10_Moments","07_NewtonsSecondLaw","01_QuantitiesUnitsModelling","04_ConstantAcceleration1D"],"topicNames":["Moments","Newton's Second Law","Quantities, Units & Modelling","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2020_Jan_Q02_M07_10_Moments.png","downloadName":"WME01-01_Y2020_Jan_Q02_M07_10_Moments.png","finalAnswer":"$(a)\\ W=120\\ \\mathrm{N}.\\quad (b)$ The rod model keeps the beam straight and rigid, so the stated distances along the beam are fixed.","steps":[{"title":"Set the tensions","body":"Let the tension at A be $T$. The tension at C is then $T+20$. Since $CB=1.5$ m and $AB=6$ m, $AC=4.5$ m."},{"title":"Use vertical equilibrium","body":"The upward tensions balance the weight: $T+(T+20)=W$, so $2T+20=W$."},{"title":"Take moments about A","body":"The centre of mass is $2.625$ m from A. Taking moments about A gives $4.5(T+20)=2.625W$."},{"title":"Solve for W","body":"From the moments equation, $T+20=\\dfrac{2.625}{4.5}W=\\dfrac{7}{12}W$. Also $T+20=\\dfrac{W+20}{2}$. Hence $\\dfrac{W+20}{2}=\\dfrac{7W}{12}$, so $6W+120=7W$ and $W=120$ N."},{"title":"State the modelling use","body":"Modelling the beam as a rod means it stays straight and rigid, so the distances used in the moments equations do not change."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_Jan_Q04","year":2021,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2021","qNo":4,"marks":6,"topic":"10_Moments","topicName":"Moments","primaryTopic":"10_Moments","primaryTopicName":"Moments","secondaryTopics":["01_QuantitiesUnitsModelling","07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"secondaryTopicNames":["Quantities, Units & Modelling","Newton's Second Law","Constant Acceleration in 1D"],"topics":["10_Moments","01_QuantitiesUnitsModelling","07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"topicNames":["Moments","Quantities, Units & Modelling","Newton's Second Law","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2021_Jan_Q04_M06_10_Moments.png","downloadName":"WME01-01_Y2021_Jan_Q04_M06_10_Moments.png","finalAnswer":"$x=3.5\\ \\mathrm{m}$.","steps":[{"title":"Set support positions","body":"The girder has length $6$ m, with C $1$ m from A and D $1$ m from B. So D is $5$ m from A."},{"title":"Use tilting about D","body":"When the $900$ N upward force is applied at A, the girder is about to tilt about D. Taking moments about D gives $900(5)=W(5-x)$."},{"title":"Use tilting about C","body":"When the $1500$ N upward force is applied at B, the girder is about to tilt about C. Taking moments about C gives $1500(5)=W(x-1)$."},{"title":"Solve the equations","body":"The equations are $W(5-x)=4500$ and $W(x-1)=7500$. Add them: $W[(5-x)+(x-1)]=12000$, so $4W=12000$ and $W=3000$."},{"title":"Find x","body":"Use $W(x-1)=7500$: $3000(x-1)=7500$, so $x-1=2.5$ and $x=3.5$ m."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_MayJune_Q07","year":2021,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2021","qNo":7,"marks":10,"topic":"10_Moments","topicName":"Moments","primaryTopic":"10_Moments","primaryTopicName":"Moments","secondaryTopics":["01_QuantitiesUnitsModelling","08_ResolvingForcesInclinedPlanes","04_ConstantAcceleration1D"],"secondaryTopicNames":["Quantities, Units & Modelling","Resolving Forces, Inclined Planes","Constant Acceleration in 1D"],"topics":["10_Moments","01_QuantitiesUnitsModelling","08_ResolvingForcesInclinedPlanes","04_ConstantAcceleration1D"],"topicNames":["Moments","Quantities, Units & Modelling","Resolving Forces, Inclined Planes","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2021_MayJune_Q07_M10_10_Moments.png","downloadName":"WME01-01_Y2021_MayJune_Q07_M10_10_Moments.png","finalAnswer":"$(a)\\ x=\\dfrac{19a}{4}.\\quad (b)\\ M=50$.","steps":[{"title":"Set the support positions","body":"The beam length is $8a$. C is at distance $a$ from A, and D is at distance $6a$ from A because $DB=2a$."},{"title":"Name the reactions","body":"Let the reaction at C be $R$. The reaction at D is $3R$."},{"title":"Use vertical equilibrium","body":"$R+3R=60g$, so $4R=60g$ and $R=15g$."},{"title":"Take moments about A","body":"The beam's weight acts at distance $x$ from A. Hence $60g x=R(a)+3R(6a)$."},{"title":"Find x","body":"Substitute $R=15g$: $60g x=15ga+45g(6a)=285ga$. Thus $x=\\dfrac{285a}{60}=\\dfrac{19a}{4}$."},{"title":"Use equal reactions with the box","body":"When the box is added, let each support reaction be $S$. Vertical equilibrium gives $2S=(60+M)g$."},{"title":"Take moments about A again","body":"The box is at $AE=2a$. Moments about A give $60g\\left(\\dfrac{19a}{4}\\right)+Mg(2a)=S(a)+S(6a)=7aS$."},{"title":"Solve for M","body":"Substitute $S=\\dfrac{(60+M)g}{2}$ and cancel $ag$: $285+2M=\\dfrac{7}{2}(60+M)=210+\\dfrac72M$. Hence $75=\\dfrac32M$ and $M=50$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2021_Oct_Q01","year":2021,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2021","qNo":1,"marks":6,"topic":"10_Moments","topicName":"Moments","primaryTopic":"10_Moments","primaryTopicName":"Moments","secondaryTopics":["06_Forces"],"secondaryTopicNames":["Forces"],"topics":["10_Moments","06_Forces"],"topicNames":["Moments","Forces"],"image":"ial/wme01/questions/WME01-01_Y2021_Oct_Q01_M06_10_Moments.png","downloadName":"WME01-01_Y2021_Oct_Q01_M06_10_Moments.png","finalAnswer":"$d=5.5\\ \\mathrm{m}$.","steps":[{"title":"Set the support positions","body":"C is $2.5$ m from A. Since $DB=2$ m and $AB=9$ m, D is $7$ m from A."},{"title":"Name the reactions","body":"Let the reaction at C be $R$. The reaction at D is twice this, so it is $2R$."},{"title":"Use vertical equilibrium","body":"$R+2R=Mg$, so $3R=Mg$."},{"title":"Take moments about A","body":"$R(2.5)+2R(7)=Mgd$."},{"title":"Substitute Mg = 3R","body":"$2.5R+14R=3Rd$. Hence $16.5R=3Rd$."},{"title":"Find d","body":"Cancel $R$: $d=\\dfrac{16.5}{3}=5.5\\ \\mathrm{m}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_Jan_Q03","year":2022,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2022","qNo":3,"marks":7,"topic":"10_Moments","topicName":"Moments","primaryTopic":"10_Moments","primaryTopicName":"Moments","secondaryTopics":["01_QuantitiesUnitsModelling"],"secondaryTopicNames":["Quantities, Units & Modelling"],"topics":["10_Moments","01_QuantitiesUnitsModelling"],"topicNames":["Moments","Quantities, Units & Modelling"],"image":"ial/wme01/questions/WME01-01_Y2022_Jan_Q03_M07_10_Moments.png","downloadName":"WME01-01_Y2022_Jan_Q03_M07_10_Moments.png","finalAnswer":"$(a)\\ \\text{beam mass}=20\\ \\mathrm{kg}.\\quad (b)\\ X=\\dfrac{150}{37}\\ \\mathrm{kg}\\approx4.05\\ \\mathrm{kg}.\\quad (c)$ The block's mass is treated as concentrated at A.","steps":[{"title":"Set the distances from D","body":"The beam length is $5$ m and $DB=1.3$ m, so D is $3.7$ m from A. The centre of mass of the uniform beam is at its midpoint, so it is $1.2$ m to the left of D. Point C is $0.8$ m to the right of D."},{"title":"Use the first tilting condition","body":"When the boy stands at C, the beam is about to tilt about D. Let the mass of the beam be $M$ kg."},{"title":"Take moments about D","body":"$Mg(1.2)=30g(0.8)$. Hence $1.2M=24$ and $M=20\\ \\mathrm{kg}$."},{"title":"Set up the second tilting condition","body":"With the boy at B, his moment about D is $30g(1.3)$. The block at A is $3.7$ m to the left of D, and the beam's weight acts $1.2$ m to the left of D."},{"title":"Take moments about D again","body":"$Xg(3.7)+20g(1.2)=30g(1.3)$."},{"title":"Find X","body":"$3.7X+24=39$, so $3.7X=15$ and $X=\\dfrac{150}{37}=4.05\\ldots\\ \\mathrm{kg}$."},{"title":"Use the particle model","body":"The block is modelled as a particle, so its mass is treated as acting at one point, A."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_MayJune_Q05","year":2022,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2022","qNo":5,"marks":9,"topic":"10_Moments","topicName":"Moments","primaryTopic":"10_Moments","primaryTopicName":"Moments","secondaryTopics":["01_QuantitiesUnitsModelling","05_ConstantAcceleration2D","06_Forces"],"secondaryTopicNames":["Quantities, Units & Modelling","Constant Acceleration in 2D","Forces"],"topics":["10_Moments","01_QuantitiesUnitsModelling","05_ConstantAcceleration2D","06_Forces"],"topicNames":["Moments","Quantities, Units & Modelling","Constant Acceleration in 2D","Forces"],"image":"ial/wme01/questions/WME01-01_Y2022_MayJune_Q05_M09_10_Moments.png","downloadName":"WME01-01_Y2022_MayJune_Q05_M09_10_Moments.png","finalAnswer":"$(a)\\ R_C=(16.25-M)g.\\quad (b)\\ R_D=(2M-1.25)g.\\quad (c)\\ 0.625\\le M\\le16.25$.","steps":[{"title":"Set the positions","body":"Take distances from A. Then C is at $1$ m, D is at $3$ m, the rod's centre of mass is at $2.5$ m, and B is at $5$ m."},{"title":"Find RC by moments about D","body":"Taking moments about D: $R_C(2)+Mg(2)=10g(3)+5g(0.5)$."},{"title":"Simplify RC","body":"$2R_C+2Mg=30g+2.5g=32.5g$, so $R_C=16.25g-Mg=(16.25-M)g$."},{"title":"Find RD by moments about C","body":"Taking moments about C: $10g(1)+R_D(2)=5g(1.5)+Mg(4)$."},{"title":"Simplify RD","body":"$10g+2R_D=7.5g+4Mg$, so $2R_D=(4M-2.5)g$ and $R_D=(2M-1.25)g$."},{"title":"Use non-negative reactions","body":"For the rod to rest on both supports, both reactions must be non-negative."},{"title":"Find the range","body":"$R_C\\ge0$ gives $16.25-M\\ge0$, so $M\\le16.25$. Also $R_D\\ge0$ gives $2M-1.25\\ge0$, so $M\\ge0.625$. Therefore $0.625\\le M\\le16.25$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2022_Oct_Q02","year":2022,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2022","qNo":2,"marks":6,"topic":"10_Moments","topicName":"Moments","primaryTopic":"10_Moments","primaryTopicName":"Moments","secondaryTopics":["07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"secondaryTopicNames":["Newton's Second Law","Constant Acceleration in 1D"],"topics":["10_Moments","07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"topicNames":["Moments","Newton's Second Law","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2022_Oct_Q02_M06_10_Moments.png","downloadName":"WME01-01_Y2022_Oct_Q02_M06_10_Moments.png","finalAnswer":"$(a)\\ \\text{largest mass}=\\dfrac{2M}{3}.\\quad (b)\\ T_C=\\dfrac{1}{10}Mg$.","steps":[{"title":"Set the distances","body":"The rod length is $2a$. The centre of mass is at the midpoint, distance $a$ from A. Also $AC=\\dfrac{2a}{5}$ and $AD=2a-\\dfrac{3a}{5}=\\dfrac{7a}{5}$."},{"title":"Use the largest mass condition","body":"For the largest possible mass at B, the string at C is just slack and the rod is about to tilt about D."},{"title":"Take moments about D","body":"Let the particle mass be $X$. The distance from D to B is $\\dfrac{3a}{5}$ and the distance from D to the rod's centre of mass is $\\dfrac{2a}{5}$. Hence $Xg\\left(\\dfrac{3a}{5}\\right)=Mg\\left(\\dfrac{2a}{5}\\right)$."},{"title":"Find the largest mass","body":"Cancel $ga/5$: $3X=2M$, so $X=\\dfrac{2M}{3}$."},{"title":"Use the given mass","body":"Now the particle has mass $\\dfrac12M$. Let the tensions at C and D be $T_C$ and $T_D$."},{"title":"Take moments about D","body":"About D, $T_C(a)+\\dfrac12Mg\\left(\\dfrac{3a}{5}\\right)=Mg\\left(\\dfrac{2a}{5}\\right)$."},{"title":"Find the tension at C","body":"$T_Ca+\\dfrac{3}{10}Mga=\\dfrac{2}{5}Mga$, so $T_C=\\dfrac{1}{10}Mg$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2023_Jan_Q04","year":2023,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2023","qNo":4,"marks":8,"topic":"10_Moments","topicName":"Moments","primaryTopic":"10_Moments","primaryTopicName":"Moments","secondaryTopics":["01_QuantitiesUnitsModelling","07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"secondaryTopicNames":["Quantities, Units & Modelling","Newton's Second Law","Constant Acceleration in 1D"],"topics":["10_Moments","01_QuantitiesUnitsModelling","07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"topicNames":["Moments","Quantities, Units & Modelling","Newton's Second Law","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2023_Jan_Q04_M08_10_Moments.png","downloadName":"WME01-01_Y2023_Jan_Q04_M08_10_Moments.png","finalAnswer":"$(i)\\ W=300\\ \\mathrm{N}.\\quad (ii)\\ x=0.63\\ \\mathrm{m}$.","steps":[{"title":"Set the distances","body":"The branch has length $1.5$ m. Since $AC=0.24$ m and $DB=0.36$ m, $CB=1.26$ m and $CD=0.90$ m. The centre of mass is $x$ m from C."},{"title":"Use the first tilting condition","body":"With the $150$ N upward force at B, the branch is on the point of tilting about C, so the support at D has zero reaction."},{"title":"Take moments about C","body":"The upward force at B balances the weight moment: $150(1.26)=Wx$. Thus $Wx=189$."},{"title":"Use the second tilting condition","body":"With the $225$ N downward force at B, the branch is on the point of tilting about D, so the support at C has zero reaction."},{"title":"Take moments about D","body":"The distance from D to the centre of mass is $0.90-x$. Hence $225(0.36)=W(0.90-x)$."},{"title":"Solve the simultaneous equations","body":"From the second equation, $81=0.90W-Wx$. Since $Wx=189$, $81=0.90W-189$, so $0.90W=270$ and $W=300\\ \\mathrm{N}$."},{"title":"Find x","body":"Using $Wx=189$, $300x=189$, so $x=0.63\\ \\mathrm{m}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2023_MayJune_Q04","year":2023,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2023","qNo":4,"marks":12,"topic":"10_Moments","topicName":"Moments","primaryTopic":"10_Moments","primaryTopicName":"Moments","secondaryTopics":["01_QuantitiesUnitsModelling","07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"secondaryTopicNames":["Quantities, Units & Modelling","Newton's Second Law","Constant Acceleration in 1D"],"topics":["10_Moments","01_QuantitiesUnitsModelling","07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"topicNames":["Moments","Quantities, Units & Modelling","Newton's Second Law","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2023_MayJune_Q04_M12_10_Moments.png","downloadName":"WME01-01_Y2023_MayJune_Q04_M12_10_Moments.png","finalAnswer":"$(a)\\ p=\\dfrac{4}{21}.\\quad (b)\\ q=\\dfrac{2}{3}.\\quad (c)$ The beam weight acts at its midpoint.","steps":[{"title":"Set the geometry","body":"The beam is $2$ m long. Since $AC=0.6$ m and $DB=0.2$ m, point D is $1.8$ m from A. The uniform beam has weight $mg$ acting $1.0$ m from A."},{"title":"Name the tensions","body":"Let the tension at D be $T$. The tension at C is four times this, so it is $4T$."},{"title":"Use vertical equilibrium","body":"$4T+T=pmg+mg$, so $5T=(p+1)mg$."},{"title":"Take moments about A","body":"The particle at A has no moment about A. Hence $4T(0.6)+T(1.8)=mg(1.0)$."},{"title":"Find T","body":"$2.4T+1.8T=mg$, so $4.2T=mg$ and $T=\\dfrac{5mg}{21}$."},{"title":"Find p","body":"Substitute into $5T=(p+1)mg$: $5\\cdot\\dfrac{5mg}{21}=(p+1)mg$. Thus $p+1=\\dfrac{25}{21}$ and $p=\\dfrac{4}{21}$."},{"title":"Use the tilting condition","body":"When the particle of mass $qm$ is at A and the beam is on the point of tilting, the rope at D is just slack, so its tension is zero."},{"title":"Take moments about C","body":"About C, the particle at A has moment $qmg(0.6)$ and the beam weight has moment $mg(0.4)$ in the opposite direction. Thus $qmg(0.6)=mg(0.4)$, giving $q=\\dfrac{2}{3}$."},{"title":"Use the modelling assumption","body":"The beam is uniform, so its centre of mass is at the midpoint of the beam and its weight acts there."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2023_Oct_Q01","year":2023,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2023","qNo":1,"marks":5,"topic":"10_Moments","topicName":"Moments","primaryTopic":"10_Moments","primaryTopicName":"Moments","secondaryTopics":["01_QuantitiesUnitsModelling","07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"secondaryTopicNames":["Quantities, Units & Modelling","Newton's Second Law","Constant Acceleration in 1D"],"topics":["10_Moments","01_QuantitiesUnitsModelling","07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"topicNames":["Moments","Quantities, Units & Modelling","Newton's Second Law","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2023_Oct_Q01_M05_10_Moments.png","downloadName":"WME01-01_Y2023_Oct_Q01_M05_10_Moments.png","finalAnswer":"$(i)\\ T_D=8\\ \\mathrm{N}.\\quad (ii)\\ x=\\dfrac{7}{3}\\ \\mathrm{m}\\approx2.33\\ \\mathrm{m}$.","steps":[{"title":"Name the tensions","body":"Let the tension at D be $T$. The tension at C is double this, so it is $2T$."},{"title":"Use vertical equilibrium","body":"The beam is in equilibrium, so the upward forces equal the weight: $2T+T=24$. Hence $3T=24$ and $T=8\\ \\mathrm{N}$."},{"title":"Set the moment distances","body":"The beam is uniform, so its weight acts at the midpoint, $3$ m from A. Also $AC=x$ and $AD=x+2$."},{"title":"Take moments about A","body":"Clockwise and anticlockwise moments balance: $(2T)x+T(x+2)=24\\cdot3$."},{"title":"Solve for x","body":"Substitute $T=8$: $16x+8(x+2)=72$. Thus $24x+16=72$, so $24x=56$ and $x=\\dfrac{7}{3}$ m."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2024_Jan_Q05","year":2024,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2024","qNo":5,"marks":10,"topic":"10_Moments","topicName":"Moments","primaryTopic":"10_Moments","primaryTopicName":"Moments","secondaryTopics":["01_QuantitiesUnitsModelling","06_Forces"],"secondaryTopicNames":["Quantities, Units & Modelling","Forces"],"topics":["10_Moments","01_QuantitiesUnitsModelling","06_Forces"],"topicNames":["Moments","Quantities, Units & Modelling","Forces"],"image":"ial/wme01/questions/WME01-01_Y2024_Jan_Q05_M10_10_Moments.png","downloadName":"WME01-01_Y2024_Jan_Q05_M10_10_Moments.png","finalAnswer":"$(a)\\ R_C=686-245x.\\quad (b)\\ x=0.08.\\quad (c)\\ M=82.5$.","steps":[{"title":"Set the positions on the beam","body":"$AC=0.4$ m and $DB=0.4$ m, so $CD=2.2$ m. The beam is uniform, so its weight $30g$ acts at the midpoint, which is $1.1$ m from D. The person is $2.2-x$ m from D."},{"title":"Take moments about D","body":"Taking moments about D removes $R_D$: $R_C(2.2)=55g(2.2-x)+30g(1.1)$."},{"title":"Show the expression for RC","body":"Using $g=9.8$, $R_C=\\dfrac{539(2.2-x)+294(1.1)}{2.2}=686-245x$."},{"title":"Use the reaction ratio","body":"Given $R_C=4R_D$ and vertical equilibrium gives $R_C+R_D=(55+30)g=833$. Hence $5R_D=833$ and $R_C=666.4$."},{"title":"Find x","body":"$686-245x=666.4$, so $245x=19.6$ and $x=0.08$."},{"title":"Use the tilting condition with the package","body":"When the package is at A and the beam is on the point of tilting about C, the reaction at D is zero."},{"title":"Find M","body":"Take moments about C: $Mg(0.4)=30g(1.1)$. Thus $M=\\dfrac{33}{0.4}=82.5$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2024_MayJune_Q04","year":2024,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2024","qNo":4,"marks":6,"topic":"10_Moments","topicName":"Moments","primaryTopic":"10_Moments","primaryTopicName":"Moments","secondaryTopics":["06_Forces","01_QuantitiesUnitsModelling"],"secondaryTopicNames":["Forces","Quantities, Units & Modelling"],"topics":["10_Moments","06_Forces","01_QuantitiesUnitsModelling"],"topicNames":["Moments","Forces","Quantities, Units & Modelling"],"image":"ial/wme01/questions/WME01-01_Y2024_MayJune_Q04_M06_10_Moments.png","downloadName":"WME01-01_Y2024_MayJune_Q04_M06_10_Moments.png","finalAnswer":"$(a)\\ M=0.8.\\quad (b)\\ R_C=5.2g\\ \\mathrm{N}\\approx51\\ \\mathrm{N}$.","steps":[{"title":"Set the positions relative to C","body":"The rod is 6.5 m long and overhangs C by 1.5 m, so C is 5.0 m from A. The rod centre of mass is 3.0 m from A, so it is 2.0 m to the left of C. Point D is 0.5 m from A, so it is 4.5 m to the left of C."},{"title":"Use the limiting balance for smallest M","body":"For the smallest $M$, the rod is just prevented from tilting clockwise about C. Taking moments about C: $Mg(4.5)+1.2g(2)=4g(1.5)$."},{"title":"Find M","body":"$4.5M+2.4=6$, so $4.5M=3.6$ and $M=0.8$."},{"title":"Place the new particle E","body":"Now the old particles are removed. Since $EB=0.9$ m and $AB=6.5$ m, E is $5.6$ m from A, so E is $0.6$ m to the right of C."},{"title":"Find the new particle mass from moments","body":"At tilting about C, moments about C give $Xg(0.6)=1.2g(2)$, so $X=4$."},{"title":"Find the force at C","body":"The upward force at C balances the rod and the new particle: $R_C=1.2g+4g=5.2g\\ \\mathrm{N}$, which is about $51\\ \\mathrm{N}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2024_Oct_Q02","year":2024,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2024","qNo":2,"marks":9,"topic":"10_Moments","topicName":"Moments","primaryTopic":"10_Moments","primaryTopicName":"Moments","secondaryTopics":["01_QuantitiesUnitsModelling","08_ResolvingForcesInclinedPlanes","07_NewtonsSecondLaw"],"secondaryTopicNames":["Quantities, Units & Modelling","Resolving Forces, Inclined Planes","Newton's Second Law"],"topics":["10_Moments","01_QuantitiesUnitsModelling","08_ResolvingForcesInclinedPlanes","07_NewtonsSecondLaw"],"topicNames":["Moments","Quantities, Units & Modelling","Resolving Forces, Inclined Planes","Newton's Second Law"],"image":"ial/wme01/questions/WME01-01_Y2024_Oct_Q02_M09_10_Moments.png","downloadName":"WME01-01_Y2024_Oct_Q02_M09_10_Moments.png","finalAnswer":"$(a)\\ x=1.38.\\quad (b)\\ M=55$.","steps":[{"title":"Find the reactions from vertical equilibrium","body":"Vertically, $R_C+R_D=50g+25g=75g$. Given $2R_D=3R_C$, we have $R_D=1.5R_C$. Therefore $2.5R_C=75g$, so $R_C=30g$ and $R_D=45g$."},{"title":"Set the distances from D","body":"$D$ is $6-1.8=4.2$ m from A. The support C is $4.2-0.9=3.3$ m to the left of D, the child at E is $4.2-3=1.2$ m to the left of D, and the centre of mass is $x$ m to the left of D."},{"title":"Take moments about D","body":"Balancing moments about D gives $50gx+25g(1.2)=R_C(3.3)$."},{"title":"Show x is 1.38","body":"Substitute $R_C=30g$: $50x+30=99$, so $50x=69$ and $x=\\dfrac{69}{50}=1.38$."},{"title":"Use the tilting condition with the block","body":"When the block at B is on the point of making the beam tilt, the beam is about to pivot about D and the reaction at C is zero."},{"title":"Take moments about D for the block","body":"The child and the beam act to the left of D, and the block at B acts $1.8$ m to the right of D. Hence $25g(1.2)+50g(1.38)=Mg(1.8)$."},{"title":"Find M","body":"$30+69=1.8M$, so $M=\\dfrac{99}{1.8}=55$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2025_Jan_Q04","year":2025,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2025","qNo":4,"marks":10,"topic":"10_Moments","topicName":"Moments","primaryTopic":"10_Moments","primaryTopicName":"Moments","secondaryTopics":["07_NewtonsSecondLaw","01_QuantitiesUnitsModelling","04_ConstantAcceleration1D"],"secondaryTopicNames":["Newton's Second Law","Quantities, Units & Modelling","Constant Acceleration in 1D"],"topics":["10_Moments","07_NewtonsSecondLaw","01_QuantitiesUnitsModelling","04_ConstantAcceleration1D"],"topicNames":["Moments","Newton's Second Law","Quantities, Units & Modelling","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2025_Jan_Q04_M10_10_Moments.png","downloadName":"WME01-01_Y2025_Jan_Q04_M10_10_Moments.png","finalAnswer":"$(a)\\ W=490.\\quad (b)\\ d=2.5.\\quad (c)\\ X=\\dfrac{980}{3}\\ \\mathrm{N}\\approx327\\ \\mathrm{N}$.","steps":[{"title":"Use moments to find W","body":"Take moments about A. The rope at C is $2.1$ m from A and the weight of the uniform rod acts at its midpoint, $1.5$ m from A. Hence $350(2.1)=W(1.5)$."},{"title":"Show W is 490","body":"$735=1.5W$, so $W=490\\ \\mathrm{N}$."},{"title":"Set up moments with particle P","body":"When P is attached, the tension at C is $600$ N. Taking moments about A: $600(2.1)=490(1.5)+210d$."},{"title":"Find d","body":"$1260=735+210d$, so $525=210d$ and $d=2.5$."},{"title":"Use the tilting condition","body":"When Q is attached at B and the rod is on the point of tilting, the rope at A is just slack. The rod is about to tilt about C."},{"title":"Find X","body":"Take moments about C. The rod weight acts $2.1-1.5=0.6$ m to the left of C, and Q acts $3-2.1=0.9$ m to the right. Thus $490(0.6)=X(0.9)$, so $X=\\dfrac{980}{3}\\ \\mathrm{N}$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2025_MayJune_Q05","year":2025,"session":"MayJune","paperCode":"WME01-01","paper":"WME01/01 May/June 2025","qNo":5,"marks":6,"topic":"10_Moments","topicName":"Moments","primaryTopic":"10_Moments","primaryTopicName":"Moments","secondaryTopics":["04_ConstantAcceleration1D","06_Forces"],"secondaryTopicNames":["Constant Acceleration in 1D","Forces"],"topics":["10_Moments","04_ConstantAcceleration1D","06_Forces"],"topicNames":["Moments","Constant Acceleration in 1D","Forces"],"image":"ial/wme01/questions/WME01-01_Y2025_MayJune_Q05_M06_10_Moments.png","downloadName":"WME01-01_Y2025_MayJune_Q05_M06_10_Moments.png","finalAnswer":"$d=\\dfrac{24a}{17}=1.41a$.","steps":[{"title":"Setup Diagrams - Scenario 1 - Tilting about A","body":"Taking moments about A:\n \n $\\sum M_A = 0$\n \n Clockwise moments = Anticlockwise moments\n \n $P \\times 3a = W \\times d$ $3aP = Wd \\quad \\text{...(1)}$"},{"title":"Setup Diagrams - Scenario 2 - Tilting about C","body":"Taking moments about C:\n \n $\\sum M_C = 0$\n \n Distance from C to COM = $(2a - d)$\n \n Distance from C to B = $a$\n \n $1.25P \\times a = W \\times (2a - d)$ $1.25Pa = W(2a - d)$ $1.25Pa = 2aW - Wd \\quad \\text{...(2)}$"},{"title":"Setup Diagrams - Substitute equation (1) into equation (2)","body":"From (1): $Wd = 3aP$\n \n $1.25Pa = 2aW - 3aP$ $1.25Pa + 3aP = 2aW$ $4.25Pa = 2aW$ $P = \\frac{2aW}{4.25a}$ $P = \\frac{2W}{4.25}$\n \n Substitute back into (1):\n \n $3a \\times \\frac{2W}{4.25} = Wd$ $\\frac{6aW}{4.25} = Wd$ $d = \\frac{6a}{4.25}$ $d = \\frac{6a}{17/4}$ $d = \\frac{24a}{17}$ $d = 1.41a \\text{ (3 sf)}$\n \n Or in exact form: $d = \\frac{24a}{17}$"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2025_Oct_Q01","year":2025,"session":"Oct","paperCode":"WME01-01","paper":"WME01/01 October 2025","qNo":1,"marks":7,"topic":"10_Moments","topicName":"Moments","primaryTopic":"10_Moments","primaryTopicName":"Moments","secondaryTopics":["07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"secondaryTopicNames":["Newton's Second Law","Constant Acceleration in 1D"],"topics":["10_Moments","07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"topicNames":["Moments","Newton's Second Law","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2025_Oct_Q01_M07_10_Moments.png","downloadName":"WME01-01_Y2025_Oct_Q01_M07_10_Moments.png","finalAnswer":"$(a)\\ x=\\dfrac{2}{3}.\\quad (b)\\ W=24\\ \\mathrm{N}$.","steps":[{"title":"Part (a): Show that x = 2/3 - Identify distances from C","body":"From the diagram:\n \n ; Distance AC = 2 m\n ; Distance CD = 8 - 2 - x = (6-x) m\n ; Distance from A to center = 4 m, so distance from C to center = 4 - 2 = 2 m"},{"title":"Part (a): Show that x = 2/3 - Take moments about C","body":"$\\sum M_C = 0$\n \n Clockwise moments = Anticlockwise moments\n \n $90 \\times (6-x) = 240 \\times 2$ $90(6-x) = 480$ $540 - 90x = 480$ $90x = 60$ $x = \\frac{60}{90} = \\frac{2}{3}$"},{"title":"Part (b): Find the greatest possible value of W - Apply vertical equilibrium","body":"$\\sum F_{\\text{vertical}} = 0$\n \n $T_C + T_D = 240 + W$ $183 + T_D = 240 + W$ $T_D = 57 + W$"},{"title":"Part (b): Find the greatest possible value of W - Take moments about C","body":"$\\sum M_C = 0$\n \n Clockwise moments = Anticlockwise moments\n \n Distance CD = $6 - \\frac{2}{3} = \\frac{16}{3}$ m\n \n $T_D \\times \\frac{16}{3} + W \\times 2 = 240 \\times 2$ $(57 + W) \\times \\frac{16}{3} + 2W = 480$ $\\frac{16(57 + W)}{3} + 2W = 480$ $\\frac{912 + 16W}{3} + 2W = 480$\n \n Multiply through by 3:\n $912 + 16W + 6W = 1440$ $22W = 528$ $W = 24$"}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"},{"id":"WME01-01_2026_Jan_Q04","year":2026,"session":"Jan","paperCode":"WME01-01","paper":"WME01/01 January 2026","qNo":4,"marks":9,"topic":"10_Moments","topicName":"Moments","primaryTopic":"10_Moments","primaryTopicName":"Moments","secondaryTopics":["07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"secondaryTopicNames":["Newton's Second Law","Constant Acceleration in 1D"],"topics":["10_Moments","07_NewtonsSecondLaw","04_ConstantAcceleration1D"],"topicNames":["Moments","Newton's Second Law","Constant Acceleration in 1D"],"image":"ial/wme01/questions/WME01-01_Y2026_Jan_Q04_M09_10_Moments.png","downloadName":"WME01-01_Y2026_Jan_Q04_M09_10_Moments.png","finalAnswer":"$(a)(i)\\ T_C=368\\ \\mathrm{N}\\ \\text{or}\\ 370\\ \\mathrm{N}.\\quad (a)(ii)\\ T_A=123\\ \\mathrm{N}\\ \\text{or}\\ 120\\ \\mathrm{N}.\\quad (b)\\ M=195$.","steps":[{"title":"Set the distances","body":"The rod is 6 m long and C is 0.4 m from B, so $AC=5.6$ m. The rod is uniform, so its weight $30g$ acts at the midpoint, 3 m from A. The 20 kg particle at B has weight $20g$."},{"title":"Take moments about A","body":"Moments about A remove the tension at A. Clockwise moments from the rod and particle equal the anticlockwise moment from the rope at C: $T_C(5.6)=30g(3)+20g(6)$."},{"title":"Find the tension at C","body":"$T_C(5.6)=210g$, so $T_C=37.5g=367.5\\ \\mathrm{N}$. To suitable accuracy, $T_C=368\\ \\mathrm{N}$, or $370\\ \\mathrm{N}$ to 2 significant figures."},{"title":"Use vertical equilibrium","body":"Vertically, $T_A+T_C=30g+20g=50g$. Therefore $T_A=50g-37.5g=12.5g=122.5\\ \\mathrm{N}$, so $T_A=123\\ \\mathrm{N}$, or $120\\ \\mathrm{N}$ to 2 significant figures."},{"title":"Use the limiting case for maximum M","body":"For the greatest possible mass at B, the rope at A is just slack, so $T_A=0$. Take moments about C: the clockwise moment of $Mg$ at B balances the anticlockwise moment of the rod weight."},{"title":"Solve for M","body":"The distance from C to B is $0.4$ m and the rod weight acts $5.6-3=2.6$ m to the left of C. Hence $Mg(0.4)=30g(2.6)$, so $M=\\dfrac{78}{0.4}=195$."}],"status":"checked","checkedBy":"Dr Eslam Ahmed","updated":"2026-06-11T00:00:00"}];
